import React, { useState, useEffect } from "react";
import { Link, useNavigate } from "react-router-dom";
import logo from "../assets/Rentfit Logo.png";
import { IoMdNotifications } from "react-icons/io";
import notificationAxiosInstance from "../services/notificationAxiosInstance";
import NotificationDropdown from "./NotificationDropdown.jsx";

const Navbar = () => {
  const navigate = useNavigate();
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [userRole, setUserRole] = useState("");
  const [unreadCount, setUnreadCount] = useState(0);
  const [showNotifications, setShowNotifications] = useState(false);

  useEffect(() => {
    const checkAuth = () => {
      const token = localStorage.getItem("access_token") || localStorage.getItem("authToken");
      const role = localStorage.getItem("role") || localStorage.getItem("userType");
      setIsLoggedIn(!!token);
      // Normalize role names
      if (role === 'Store' || role === 'store') setUserRole('Store');
      else if (role === 'Customer' || role === 'user') setUserRole('Customer');
      else if (role === 'Admin' || role === 'admin') setUserRole('Admin');
      else setUserRole('');
    };

    checkAuth();
    window.addEventListener("authChange", checkAuth);
    return () => window.removeEventListener("authChange", checkAuth);
  }, []);

  useEffect(() => {
    if (!isLoggedIn) {
      setUnreadCount(0);
      return;
    }

    const fetchUnreadCount = async () => {
      try {
        const response = await notificationAxiosInstance.get('notifications/unread-count/');
        setUnreadCount(response.data.unread_count);
      } catch (error) {
        console.error("Error fetching unread count:", error);
      }
    };

    fetchUnreadCount();
    const interval = setInterval(fetchUnreadCount, 15000); // Poll every 15s

    return () => clearInterval(interval);
  }, [isLoggedIn]);

  const handleLogout = () => {
    localStorage.clear();
    setIsLoggedIn(false);
    setUserRole("");
    navigate("/login");
  };
  return (
    <nav className="bg-white shadow-sm border-b border-gray-200">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center h-16">

          {/* LOGO */}
          <Link to="/" className="flex items-center gap-3">
            <img
              src={logo}
              alt="RentFit Logo"
              className="h-16 w-auto"
            />
            <span className="text-2xl font-bold text-gray-900">Rentfit</span>
          </Link>

          {/* NAV LINKS */}
          <div className="hidden md:flex items-center space-x-8">
            {(!isLoggedIn || userRole === 'Customer') && (
              <Link
                to="/browseClothes"
                className="text-gray-600 hover:text-gray-900 text-sm font-medium transition-colors"
              >
                Browse
              </Link>
            )}

            {/* Logged Out Links - Locations & About */}
            {(!isLoggedIn || userRole === 'Customer') && (
              <Link
                to="/nearbyStores"
                className="text-gray-600 hover:text-gray-900 text-sm font-medium transition-colors"
              >
                Nearby Stores
              </Link>
            )}
            {!isLoggedIn && (
              <>
                <Link
                  to="/about"
                  className="text-gray-600 hover:text-gray-900 text-sm font-medium transition-colors"
                >
                  About
                </Link>
                <Link
                  to="/donate"
                  className="text-gray-600 hover:text-gray-900 text-sm font-medium transition-colors"
                >
                  Donation
                </Link>
              </>
            )}

            {/* Logged In Links */}
            {isLoggedIn && userRole === 'Customer' && (
              <Link
                to="/myrentals"
                className="text-gray-600 hover:text-gray-900 text-sm font-medium transition-colors"
              >
                My Rentals
              </Link>
            )}
            {isLoggedIn && userRole === 'Store' && (
              <>
                <Link
                  to="/rentmanagement"
                  className="text-gray-600 hover:text-gray-900 text-sm font-medium transition-colors"
                >
                  Rental Requests
                </Link>
                <Link
                  to="/addClothingItem"
                  className="text-gray-600 hover:text-gray-900 text-sm font-medium transition-colors"
                >
                  List Clothes
                </Link>
                <Link
                  to="/storedonations"
                  className="text-gray-600 hover:text-gray-900 text-sm font-medium transition-colors"
                >
                  Donations
                </Link>
              </>
            )}
            {isLoggedIn && userRole === 'Customer' && (
              <Link
                to="/donate"
                className="text-gray-600 hover:text-gray-900 text-sm font-medium transition-colors"
              >
                Donate
              </Link>
            )}

            {/* Dashboard - Logged In Only */}
            {isLoggedIn && (
              <Link
                to={userRole === 'Store' ? "/storeDashboard" : userRole === 'Admin' ? "/adminDashboard" : "/dashboard"}
                className="text-gray-600 hover:text-gray-900 text-sm font-medium transition-colors"
              >
                Dashboard
              </Link>
            )}
          </div>

          {/* RIGHT ACTIONS */}
          <div className="flex items-center space-x-4">
            {/* NOTIFICATION BELL */}
            {isLoggedIn && (
              <div className="relative">
                <button
                  onClick={() => setShowNotifications(!showNotifications)}
                  className="p-2 text-gray-600 hover:text-gray-900 transition-colors relative"
                >
                  <IoMdNotifications className="w-6 h-6" />
                  {unreadCount > 0 && (
                    <span className="absolute top-1 right-1 flex h-4 w-4 items-center justify-center rounded-full bg-red-600 text-[10px] font-bold text-white ring-2 ring-white">
                      {unreadCount > 9 ? '9+' : unreadCount}
                    </span>
                  )}
                </button>

                {showNotifications && (
                  <NotificationDropdown onClose={() => setShowNotifications(false)} />
                )}
              </div>
            )}

            {/* HEART ICON */}
            <button className="p-2 text-gray-600 hover:text-gray-900 transition-colors">
              <svg
                className="w-6 h-6"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z"
                />
              </svg>
            </button>

            {isLoggedIn ? (
              <button
                onClick={handleLogout}
                className="px-6 py-2 bg-red-600 text-white text-sm font-medium rounded-md hover:bg-red-700 transition-colors"
              >
                Log out
              </button>
            ) : (
              <>
                <Link
                  to="/login"
                  className="px-6 py-2 text-purple-600 border border-purple-600 text-sm font-medium rounded-md hover:bg-purple-50 transition-colors"
                >
                  Log in
                </Link>
                <Link
                  to="/createAccount"
                  className="px-6 py-2 bg-purple-600 text-white text-sm font-medium rounded-md hover:bg-purple-700 transition-colors"
                >
                  Sign up
                </Link>
              </>
            )}
          </div>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;

import React, { useState } from 'react';
import rentalAxiosInstance from '../services/rentalAxiosInstance';
import paymentAxiosInstance from '../services/paymentAxiosInstance';
import EsewaPayment from './EsewaPayment';

const RentalModal = ({ isOpen, onClose, clothing, onRentalCreated, prefilledStartDate, prefilledSize }) => {
    const [startDate, setStartDate] = useState(prefilledStartDate || '');
    const [endDate, setEndDate] = useState('');
    const [selectedSize, setSelectedSize] = useState(prefilledSize || '');
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState('');
    const [paymentData, setPaymentData] = useState(null);

    React.useEffect(() => {
        if (isOpen) {
            console.log('RentalModal opened for:', clothing.item_name, 'available sizes:', clothing.size);
            setSelectedSize(prefilledSize || ''); // Use prefilled if available
            setStartDate(prefilledStartDate || ''); // Use prefilled if available
            setEndDate('');
            setError('');
        }
    }, [isOpen, clothing.id, prefilledStartDate, prefilledSize]);

    if (!isOpen) return null;

    console.log('RentalModal Render - selectedSize:', selectedSize);

    const handleSubmit = async (e) => {
        e.preventDefault();
        setIsLoading(true);
        setError('');

        try {
            // Step 1: Create Rental
            await rentalAxiosInstance.post('rentals/create/', {
                clothing: clothing.id,
                selected_size: selectedSize,
                rent_start_date: startDate,
                rent_end_date: endDate,
            });

            onRentalCreated('Rental request sent to store! Waiting for approval.', 'success');
            onClose();

        } catch (err) {
            console.error('Rental Creation Error:', err.response?.data);

            let errorMsg = 'Failed to create rental request.';

            if (err.response?.data) {
                const data = err.response.data;
                if (data.error) {
                    errorMsg = data.error;
                } else if (data.non_field_errors && data.non_field_errors.length > 0) {
                    errorMsg = data.non_field_errors[0];
                }
            }

            setError(errorMsg);
            onRentalCreated(errorMsg, 'error');
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <>
            {paymentData && <EsewaPayment data={paymentData} />}

            <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
                <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden transform transition-all scale-100">
                    <div className="bg-purple-600 p-6 text-white text-center">
                        <h2 className="text-2xl font-bold">Rent Item</h2>
                        <p className="text-purple-100 mt-1">{clothing.item_name}</p>
                    </div>

                    <form onSubmit={handleSubmit} className="p-6 space-y-4">
                        {error && (
                            <div className="p-3 bg-red-100 text-red-700 rounded-lg text-sm font-medium">
                                {error}
                            </div>
                        )}

                        <div className="space-y-1">
                            <label className="text-sm font-semibold text-gray-700">Start Date</label>
                            <input
                                type="date"
                                required
                                min={new Date().toISOString().split('T')[0]}
                                value={startDate}
                                onChange={(e) => setStartDate(e.target.value)}
                                className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-purple-500 focus:border-transparent outline-none transition-all"
                            />
                        </div>

                        <div className="space-y-1">
                            <label className="text-sm font-semibold text-gray-700">End Date</label>
                            <input
                                type="date"
                                required
                                min={startDate || new Date().toISOString().split('T')[0]}
                                value={endDate}
                                onChange={(e) => setEndDate(e.target.value)}
                                className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-purple-500 focus:border-transparent outline-none transition-all"
                            />
                        </div>

                        {/* Size Selection */}
                        <div className="space-y-2">
                            <label className="text-sm font-semibold text-gray-700 block">Select Your Size *</label>
                            <div className="flex flex-wrap gap-2">
                                {clothing.size?.split(',').map(s => s.trim()).filter(Boolean).map(size => (
                                    <button
                                        key={size}
                                        type="button"
                                        onClick={() => setSelectedSize(size)}
                                        className={`px-4 py-2 rounded-xl text-xs font-bold uppercase tracking-widest transition-all ${selectedSize === size
                                            ? 'bg-purple-600 text-white shadow-lg shadow-purple-100 scale-105'
                                            : 'bg-gray-50 text-gray-500 hover:bg-gray-100 border border-gray-100'
                                            }`}
                                    >
                                        {size}
                                    </button>
                                ))}
                            </div>
                            {!selectedSize && <p className="text-[10px] text-red-500 font-medium italic">Please pick one available size to continue.</p>}
                        </div>

                        <div className="p-4 bg-gray-50 rounded-xl flex justify-between items-center">
                            <div className="flex flex-col">
                                <span className="text-gray-600 font-medium">Price per day:</span>
                                <span className="text-xs text-gray-400">Secure payment via eSewa</span>
                            </div>
                            <span className="text-xl font-bold text-purple-600">Γé╣{clothing.rental_price}</span>
                        </div>

                        <div className="flex gap-3 pt-4">
                            <button
                                type="button"
                                onClick={onClose}
                                className="flex-1 py-3 border border-gray-300 rounded-xl text-gray-700 font-bold hover:bg-gray-50 transition-colors"
                            >
                                Cancel
                            </button>
                            <button
                                type="submit"
                                disabled={isLoading || !selectedSize}
                                className={`flex-1 py-3 bg-purple-600 rounded-xl text-white font-bold shadow-lg transition-all ${isLoading || !selectedSize ? 'opacity-50 cursor-not-allowed' : 'hover:bg-purple-700 hover:-translate-y-0.5'
                                    }`}
                            >
                                {isLoading ? 'Sending Request...' : 'Request Rental'}
                            </button>
                        </div>
                    </form>
                </div>
            </div>
        </>
    );
};

export default RentalModal;

