import React, { useState, useEffect, useCallback } from "react";
import MapView from "./MapView";

const hasValidCoords = (lat, lng) =>
    lat !== null && lat !== undefined && lat !== "" &&
    lng !== null && lng !== undefined && lng !== "";

const StoreLocationMap = ({ onLocationSelect, initialLocation, city, readonly = false }) => {
    const [marker, setMarker] = useState(null);

    // Initialize marker from initialLocation
    useEffect(() => {
        if (hasValidCoords(initialLocation?.lat, initialLocation?.lng)) {
            setMarker({
                lat: parseFloat(initialLocation.lat),
                lng: parseFloat(initialLocation.lng),
            });
        }
    }, [initialLocation]);

    const onMapClick = useCallback(
        (e) => {
            if (readonly) return;
            const newPos = {
                lat: e.latlng.lat,
                lng: e.latlng.lng,
            };
            setMarker(newPos);
            if (onLocationSelect) {
                onLocationSelect(newPos.lat, newPos.lng);
            }
        },
        [readonly, onLocationSelect]
    );

    const handleManualChange = (e) => {
        const { name, value } = e.target;
        const newMarker = { ...marker, [name]: parseFloat(value) || 0 };
        setMarker(newMarker);
        if (onLocationSelect && hasValidCoords(newMarker.lat, newMarker.lng)) {
            onLocationSelect(newMarker.lat, newMarker.lng);
        }
    };

    return (
        <div className="space-y-4">
            {!readonly && (
                <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label className="block text-xs font-semibold text-gray-500 mb-1 ml-1 uppercase tracking-wider">Latitude</label>
                        <input
                            type="number"
                            name="lat"
                            value={marker?.lat || ""}
                            onChange={handleManualChange}
                            placeholder="e.g. 27.7172"
                            className="w-full p-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-purple-500 outline-none shadow-sm"
                        />
                    </div>
                    <div>
                        <label className="block text-xs font-semibold text-gray-500 mb-1 ml-1 uppercase tracking-wider">Longitude</label>
                        <input
                            type="number"
                            name="lng"
                            value={marker?.lng || ""}
                            onChange={handleManualChange}
                            placeholder="e.g. 85.324"
                            className="w-full p-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-purple-500 outline-none shadow-sm"
                        />
                    </div>
                </div>
            )}

            <div className="rounded-2xl overflow-hidden border border-gray-100 shadow-inner">
                <MapView
                    lat={marker?.lat}
                    lng={marker?.lng}
                    onMapClick={onMapClick}
                    readonly={readonly}
                    zoom={marker ? 15 : 12}
                />
            </div>

            {!readonly && (
                <p className="text-xs text-gray-500 mt-2 italic px-1">
                    ≡ƒÆí Click on the map or drag the marker to precisely set your shop location.
                </p>
            )}
        </div>
    );
};

export const searchAddressAndCenter = async (address, callback, setAlert) => {
    if (!address || address.trim() === "," || address.trim() === "") {
        if (setAlert) setAlert({ message: "Please enter a city and address first", type: "error" });
        return;
    }

    try {
        const url = `https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(address)}`;
        const res = await fetch(url, {
            headers: {
                'User-Agent': 'RentFit-App'
            }
        });
        const data = await res.json();

        if (data && data.length > 0) {
            const lat = parseFloat(data[0].lat);
            const lng = parseFloat(data[0].lon);

            if (callback) {
                callback({ lat, lng });
            }
        } else {
            if (setAlert) setAlert({ message: "Location not found. Please try a more specific address.", type: "error" });
        }
    } catch (error) {
        console.error("Geocoding error:", error);
        if (setAlert) setAlert({ message: "Error fetching location. Please try again later.", type: "error" });
    }
};

export default React.memo(StoreLocationMap);

import React, { useState, useEffect } from 'react';
import { FaArrowLeft, FaUpload, FaTimes } from 'react-icons/fa';
import { useNavigate, useSearchParams } from 'react-router-dom';
import axiosInstance from '../services/axiosInstance';
import Navbar from '../Components/Navbar';
import Footer from '../Components/Footer';
import StoreSidebar from "../Components/StoreSidebar";

const AddClothingItem = () => {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const editId = searchParams.get('edit');
  const isEditMode = !!editId;

  const categories = ['Formal Wear', 'Casual', 'Party Wear', 'Traditional', 'Sports Wear'];
  const eventTypes = ['Wedding', 'Party', 'Formal', 'Casual'];
  const conditions = ['New', 'Like New', 'Good', 'Used'];
  const sizes = ['XS', 'S', 'M', 'L', 'XL', 'XXL', 'Free', 'Custom'];

  const [formData, setFormData] = useState({
    item_name: '',
    category: '',
    event_type: '',
    gender: '',
    size: '',
    condition: '',
    rental_price: '',
    security_deposit: '',
    stock_quantity: '1',
    description: '',
    clothing_status: 'Available'
  });

  const [imageFile, setImageFile] = useState(null);
  const [imagePreview, setImagePreview] = useState(null);
  const [existingImage, setExistingImage] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState(false);

  useEffect(() => {
    if (isEditMode) {
      fetchClothingItem();
    }
  }, [editId]);

  const fetchClothingItem = async () => {
    try {
      setLoading(true);
      const response = await axiosInstance.get(`accounts/clothing/${editId}/`);
      if (response.data) {
        const item = response.data;
        setFormData({
          item_name: item.item_name || '',
          category: item.category || '',
          event_type: item.event_type || '',
          gender: item.gender || 'Female',
          size: item.size || '',
          condition: item.condition || '',
          rental_price: item.rental_price || '',
          security_deposit: item.security_deposit || '',
          stock_quantity: item.stock_quantity || '1',
          description: item.description || '',
          clothing_status: item.clothing_status || 'Available'
        });

        if (item.images) {
          setExistingImage(item.images);
        }
      }
    } catch (err) {
      console.error('Error fetching clothing item:', err);
      setError('Failed to load clothing item details');
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleImageChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      setImageFile(file);
      const reader = new FileReader();
      reader.onloadend = () => {
        setImagePreview(reader.result);
      };
      reader.readAsDataURL(file);
    }
  };

  const removeImage = () => {
    setImageFile(null);
    setImagePreview(null);
  };

  const handleSubmit = async (e) => {
    if (e) e.preventDefault();
    setLoading(true);
    setError('');
    setSuccess(false);

    try {
      const formDataToSend = new FormData();

      // Append all fields with cleanup
      Object.keys(formData).forEach(key => {
        let value = formData[key];

        if (['rental_price', 'security_deposit', 'stock_quantity'].includes(key)) {
          if (value === "" || value === null || value === undefined) {
            return;
          }
          value = Number(value);
        }

        if (value !== undefined && value !== null) {
          formDataToSend.append(key, value);
        }
      });

      // Append image ONLY if a new one was selected
      if (imageFile) {
        formDataToSend.append('images', imageFile);
      } else if (!isEditMode) {
        // If adding new item, image is probably required by backend
        // but it's already checked by required attribute in HTML
      }

      if (isEditMode) {
        await axiosInstance.put(`accounts/clothing/${editId}/update/`, formDataToSend, {
          headers: {
            'Content-Type': 'multipart/form-data',
          }
        });
      } else {
        await axiosInstance.post('accounts/clothing/create/', formDataToSend, {
          headers: {
            'Content-Type': 'multipart/form-data',
          }
        });
      }

      setSuccess(true);
      setTimeout(() => {
        navigate('/myClothingItems');
      }, 1500);

    } catch (err) {
      console.error('Error saving clothing item:', err);

      // Improved Error Handling: Show field-level errors
      if (err.response?.data) {
        const backendErrors = err.response.data;
        if (typeof backendErrors === 'object' && !Array.isArray(backendErrors)) {
          const errorMessages = Object.keys(backendErrors).map(field => {
            const messages = Array.isArray(backendErrors[field])
              ? backendErrors[field].join(", ")
              : backendErrors[field];
            return `${field.replace('_', ' ')}: ${messages}`;
          });
          setError(errorMessages.join(" | "));
        } else {
          setError(err.response?.data?.message || err.response?.data?.error || 'Failed to save clothing item');
        }
      } else {
        setError('Failed to connect to server. Please try again.');
      }
    } finally {
      setLoading(false);
    }
  };

  const handleSaveDraft = () => {
    localStorage.setItem('clothingDraft', JSON.stringify({
      formData,
      imagePreview
    }));
    setSuccess(true);
    setError('');
    setTimeout(() => {
      setSuccess(false);
    }, 3000);
  };

  if (loading && isEditMode) {
    return (
      <>
        <Navbar />
        <div className="min-h-screen bg-gray-50 flex items-center justify-center">
          <div className="text-center">
            <div className="w-12 h-12 border-4 border-purple-500 border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
            <p className="text-gray-600">Loading clothing item...</p>
          </div>
        </div>
        <Footer />
      </>
    );
  }

  return (
    <>
      <Navbar />
      <div className="flex flex-1">
        <StoreSidebar />

        <div className="flex-1 py-8 px-4 overflow-auto">
          {/* Header */}
          <div className="mb-6 flex flex-col md:flex-row md:items-center justify-between gap-4">
            <div>
              <h1 className="text-3xl font-bold text-gray-900 leading-tight">
                {isEditMode ? 'Edit Clothing Item' : 'Add New Clothing Item'}
              </h1>
              <p className="text-gray-500 mt-1">
                Fill in the details below to {isEditMode ? 'update' : 'add'} a new clothing item to the rental platform
              </p>
            </div>
            <button
              onClick={() => navigate('/myClothingItems')}
              className="px-6 py-2.5 bg-white border border-gray-100 rounded-xl shadow-sm text-sm font-bold text-gray-600 hover:text-purple-600 transition-all flex items-center gap-2"
            >
              <FaArrowLeft size={12} />
              Back to Inventory
            </button>
          </div>

          <div className="space-y-6">
            {/* Success Message */}
            {success && (
              <div className="p-4 bg-green-50 border border-green-100 rounded-2xl text-green-700 font-medium animate-pulse">
                {isEditMode ? 'Item updated successfully!' : 'Your item has been submitted and is pending admin approval.'}
              </div>
            )}

            {/* Error Message */}
            {error && (
              <div className="p-4 bg-red-50 border border-red-100 rounded-2xl text-red-700 font-medium">
                {error}
              </div>
            )}

            <form onSubmit={handleSubmit} className="space-y-6">
              {/* Item Information Card */}
              <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
                <div className="p-6 border-b border-gray-50 bg-gray-50/30">
                  <div className="flex items-center gap-4">
                    <div className="w-12 h-12 bg-purple-50 text-purple-600 rounded-xl flex items-center justify-center shadow-sm">
                      <span className="text-2xl font-bold">+</span>
                    </div>
                    <div>
                      <h2 className="text-xl font-bold text-gray-900">Item Information</h2>
                      <p className="text-sm text-gray-500">Provide accurate details for better customer experience</p>
                    </div>
                  </div>
                </div>

                <div className="p-8">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    {/* Item Name */}
                    <div className="md:col-span-2">
                      <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-3">Item Name *</label>
                      <input
                        type="text"
                        name="item_name"
                        value={formData.item_name}
                        onChange={handleInputChange}
                        placeholder="e.g., Designer Evening Gown"
                        className="w-full px-4 py-4 bg-gray-50 border border-gray-100 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500 transition-all text-sm font-medium"
                        required
                      />
                    </div>

                    {/* Category */}
                    <div>
                      <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-3">Category *</label>
                      <div className="relative">
                        <select
                          name="category"
                          value={formData.category}
                          onChange={handleInputChange}
                          className="w-full px-4 py-4 bg-gray-50 border border-gray-100 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500 appearance-none text-sm font-medium transition-all"
                          required
                        >
                          <option value="">Select Category</option>
                          {categories.map(cat => (
                            <option key={cat} value={cat}>{cat}</option>
                          ))}
                        </select>
                        <FaArrowLeft className="absolute right-4 top-1/2 -translate-y-1/2 -rotate-90 text-gray-400 pointer-events-none" size={12} />
                      </div>
                    </div>

                    {/* Gender Selection */}
                    <div>
                      <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-3">Gender *</label>
                      <div className="relative">
                        <select
                          name="gender"
                          value={formData.gender}
                          onChange={handleInputChange}
                          className="w-full px-4 py-4 bg-gray-50 border border-gray-100 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500 appearance-none text-sm font-medium transition-all"
                          required
                        >
                          <option value="">Select Gender</option>
                          <option value="Male">Male</option>
                          <option value="Female">Female</option>
                          <option value="Other">Other</option>
                        </select>
                        <FaArrowLeft className="absolute right-4 top-1/2 -translate-y-1/2 -rotate-90 text-gray-400 pointer-events-none" size={12} />
                      </div>
                    </div>

                    {/* Condition */}
                    <div>
                      <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-3">Condition *</label>
                      <div className="relative">
                        <select
                          name="condition"
                          value={formData.condition}
                          onChange={handleInputChange}
                          className="w-full px-4 py-4 bg-gray-50 border border-gray-100 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500 appearance-none text-sm font-medium transition-all"
                          required
                        >
                          <option value="">Select Condition</option>
                          {conditions.map(cond => (
                            <option key={cond} value={cond}>{cond}</option>
                          ))}
                        </select>
                        <FaArrowLeft className="absolute right-4 top-1/2 -translate-y-1/2 -rotate-90 text-gray-400 pointer-events-none" size={12} />
                      </div>
                    </div>

                    {/* Event Type */}
                    <div>
                      <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-3">Event Type *</label>
                      <div className="relative">
                        <select
                          name="event_type"
                          value={formData.event_type}
                          onChange={handleInputChange}
                          className="w-full px-4 py-4 bg-gray-50 border border-gray-100 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500 appearance-none text-sm font-medium transition-all"
                          required
                        >
                          <option value="">Select Event Type</option>
                          {eventTypes.map(type => (
                            <option key={type} value={type}>{type}</option>
                          ))}
                        </select>
                        <FaArrowLeft className="absolute right-4 top-1/2 -translate-y-1/2 -rotate-90 text-gray-400 pointer-events-none" size={12} />
                      </div>
                    </div>

                    {/* Stock Quantity */}
                    <div>
                      <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-3">Stock Quantity *</label>
                      <input
                        type="number"
                        name="stock_quantity"
                        value={formData.stock_quantity}
                        onChange={handleInputChange}
                        placeholder="0"
                        min="1"
                        className="w-full px-4 py-4 bg-gray-50 border border-gray-100 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500 transition-all text-sm font-medium"
                        required
                      />
                    </div>

                    {/* Size Selection */}
                    <div>
                      <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-3">Size *</label>
                      <div className="flex flex-wrap gap-2">
                        {sizes.map(size => {
                          const selectedSizes = formData.size ? formData.size.split(',').map(s => s.trim()).filter(Boolean) : [];
                          const isSelected = selectedSizes.includes(size);

                          return (
                            <button
                              key={size}
                              type="button"
                              onClick={(e) => {
                                e.preventDefault();
                                setFormData(prev => {
                                  const current = prev.size ? prev.size.split(',').map(s => s.trim()).filter(Boolean) : [];
                                  const updated = current.includes(size)
                                    ? current.filter(s => s !== size)
                                    : [...current, size];
                                  return { ...prev, size: updated.join(', ') };
                                });
                              }}
                              className={`px-4 py-2.5 rounded-xl text-xs font-bold uppercase tracking-widest transition-all ${isSelected
                                ? 'bg-purple-600 text-white shadow-lg shadow-purple-100 scale-105'
                                : 'bg-gray-50 text-gray-500 hover:bg-gray-100 border border-gray-100'
                                }`}
                            >
                              {size}
                            </button>
                          );
                        })}
                      </div>
                      <p className="text-[10px] text-gray-400 mt-2 italic">Select all sizes available (Multiple choices allowed).</p>
                    </div>

                    {/* Product Images */}
                    <div className="md:row-span-3">
                      <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-3">Product Images *</label>
                      <div className="border-2 border-dashed border-gray-200 rounded-3xl p-8 text-center bg-gray-50/50 hover:bg-gray-50 transition-colors cursor-pointer group relative overflow-hidden">
                        {imagePreview || existingImage ? (
                          <div className="relative inline-block w-full group">
                            <img
                              src={imagePreview || existingImage}
                              alt="Item Preview"
                              className="w-full aspect-[4/5] object-cover rounded-2xl shadow-md transition-all duration-300 group-hover:scale-[1.02]"
                            />

                            {/* Hover Overlay */}
                            <label htmlFor="image-upload" className="absolute inset-0 bg-black/40 flex flex-col items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity cursor-pointer rounded-2xl">
                              <FaUpload className="text-white mb-2" size={20} />
                              <span className="text-white text-xs font-bold uppercase tracking-widest">Replace Image</span>
                            </label>

                            {/* Remove Preview Button (only for new uploads) */}
                            {imagePreview && (
                              <button
                                type="button"
                                onClick={(e) => {
                                  e.preventDefault();
                                  removeImage();
                                }}
                                className="absolute top-4 right-4 p-2 bg-white/90 backdrop-blur-md text-red-500 rounded-full shadow-lg hover:bg-white hover:scale-110 transition-all z-10"
                                title="Remove new image and restore original"
                              >
                                <FaTimes size={14} />
                              </button>
                            )}
                          </div>
                        ) : (
                          <label htmlFor="image-upload" className="block cursor-pointer py-10">
                            <div className="w-16 h-16 bg-white rounded-2xl flex items-center justify-center mx-auto mb-4 shadow-sm group-hover:scale-110 transition-transform">
                              <FaUpload className="text-purple-600" size={24} />
                            </div>
                            <h3 className="text-gray-900 font-bold mb-1">
                              {imageFile ? `Selected: ${imageFile.name}` : 'Click to upload images'}
                            </h3>
                            <p className="text-xs text-gray-400 font-medium">PNG, JPG up to 10MB each</p>
                            <div className="mt-6 px-6 py-2.5 bg-purple-600 text-white text-xs font-black uppercase tracking-widest rounded-xl inline-block shadow-lg shadow-purple-100 hover:bg-purple-700 transition-all">
                              {imageFile ? 'Change File' : 'Choose Files'}
                            </div>
                          </label>
                        )}
                        <input
                          type="file"
                          accept="image/*"
                          onChange={handleImageChange}
                          className="hidden"
                          id="image-upload"
                        />
                      </div>
                    </div>

                    {/* Rental Price */}
                    <div>
                      <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-3">Rental Price (per day) *</label>
                      <div className="relative">
                        <span className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 font-bold">Γé╣</span>
                        <input
                          type="number"
                          name="rental_price"
                          value={formData.rental_price}
                          onChange={handleInputChange}
                          placeholder="0.00"
                          step="0.01"
                          className="w-full pl-10 pr-4 py-4 bg-gray-50 border border-gray-100 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500 transition-all text-sm font-medium"
                          required
                        />
                      </div>
                    </div>

                    {/* Security Deposit */}
                    <div>
                      <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-3">Security Deposit *</label>
                      <div className="relative">
                        <span className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 font-bold">Γé╣</span>
                        <input
                          type="number"
                          name="security_deposit"
                          value={formData.security_deposit}
                          onChange={handleInputChange}
                          placeholder="0.00"
                          step="0.01"
                          className="w-full pl-10 pr-4 py-4 bg-gray-50 border border-gray-100 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500 transition-all text-sm font-medium"
                          required
                        />
                      </div>
                    </div>

                    {/* Description */}
                    <div className="md:col-span-1">
                      <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-3">Description</label>
                      <textarea
                        name="description"
                        value={formData.description}
                        onChange={handleInputChange}
                        placeholder="Describe the item details, material, occasion, care instructions..."
                        rows="6"
                        className="w-full px-4 py-4 bg-gray-50 border border-gray-100 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500 transition-all text-sm font-medium resize-none"
                      />
                    </div>
                  </div>
                </div>
              </div>

              {/* Action Buttons */}
              <div className="flex flex-col sm:flex-row justify-between items-center gap-6 pb-20">
                <button
                  type="button"
                  onClick={handleSaveDraft}
                  className="w-full sm:w-auto px-8 py-3.5 bg-white border border-gray-100 text-gray-700 font-bold rounded-xl shadow-sm hover:bg-gray-50 transition-all uppercase tracking-widest text-xs"
                >
                  Save as Draft
                </button>
                <div className="flex w-full sm:w-auto gap-4">
                  <button
                    type="button"
                    onClick={() => navigate('/myClothingItems')}
                    className="flex-1 sm:flex-none px-8 py-3.5 bg-white border border-gray-100 text-gray-500 font-bold rounded-xl hover:text-red-500 transition-all uppercase tracking-widest text-xs"
                  >
                    Cancel
                  </button>
                  <button
                    type="submit"
                    disabled={loading}
                    className="flex-1 sm:flex-none px-12 py-3.5 bg-purple-600 text-white font-black rounded-xl hover:bg-purple-700 transition-all disabled:bg-purple-300 shadow-xl shadow-purple-100 uppercase tracking-widest text-xs flex items-center justify-center gap-3"
                  >
                    {loading ? (
                      <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                    ) : (
                      <span>{isEditMode ? 'Update Item' : '+ Add Item to Inventory'}</span>
                    )}
                  </button>
                </div>
              </div>
            </form>

            {/* Quick Tips Section */}
            <div className="bg-blue-50/50 rounded-2xl p-8 border border-blue-100/50">
              <div className="flex items-start gap-4">
                <div className="p-2 bg-blue-100 rounded-lg text-blue-600">
                  <span className="text-xl font-bold">≡ƒÆí</span>
                </div>
                <div>
                  <h3 className="text-blue-900 font-black uppercase tracking-tighter text-sm mb-4">Quick Tips for Better Listings</h3>
                  <ul className="space-y-3">
                    <li className="text-blue-700/80 text-sm font-medium flex items-center gap-3">
                      <div className="w-1.5 h-1.5 bg-blue-400 rounded-full"></div>
                      Use high-quality, well-lit photos from multiple angles
                    </li>
                    <li className="text-blue-700/80 text-sm font-medium flex items-center gap-3">
                      <div className="w-1.5 h-1.5 bg-blue-400 rounded-full"></div>
                      Include detailed measurements and fabric information
                    </li>
                    <li className="text-blue-700/80 text-sm font-medium flex items-center gap-3">
                      <div className="w-1.5 h-1.5 bg-blue-400 rounded-full"></div>
                      Mention any special care instructions or restrictions
                    </li>
                    <li className="text-blue-700/80 text-sm font-medium flex items-center gap-3">
                      <div className="w-1.5 h-1.5 bg-blue-400 rounded-full"></div>
                      Set competitive pricing based on similar items in your area
                    </li>
                  </ul>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
      <Footer />
    </>
  );
};

export default AddClothingItem;

import React, { useState, useEffect } from 'react';
import axiosInstance from '../services/axiosInstance';
import AdminSidebar from '../Components/AdminSidebar';
import Navbar from '../Components/Navbar';
import Footer from '../Components/Footer';
import Alert from '../Components/Alert';
import {
    FaSearch,
    FaUserSlash,
    FaCheckCircle,
    FaFilter,
    FaStore,
    FaUserGraduate,
    FaUserShield
} from 'react-icons/fa';

const AdminUserManagement = () => {
    const [users, setUsers] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [searchQuery, setSearchQuery] = useState('');
    const [roleFilter, setRoleFilter] = useState('All');
    const [alert, setAlert] = useState({ message: '', type: '' });

    const fetchUsers = async () => {
        try {
            setIsLoading(true);
            const response = await axiosInstance.get('accounts/admin/users/');
            setUsers(response.data);
        } catch (error) {
            console.error("Error fetching users:", error);
            setAlert({ message: "Failed to fetch users list.", type: "error" });
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        fetchUsers();
    }, []);

    const handleDeactivate = async (userId) => {
        try {
            const response = await axiosInstance.patch(`accounts/admin/users/${userId}/deactivate/`);
            setAlert({ message: response.data.message, type: "success" });
            fetchUsers(); // Refresh list
        } catch (error) {
            setAlert({ message: "Failed to update user status.", type: "error" });
        }
    };

    const filteredUsers = users.filter(user => {
        const matchesSearch = user.email.toLowerCase().includes(searchQuery.toLowerCase()) ||
            user.name.toLowerCase().includes(searchQuery.toLowerCase());
        const matchesRole = roleFilter === 'All' || user.role === roleFilter;
        return matchesSearch && matchesRole;
    });

    const getRoleBadge = (role) => {
        switch (role) {
            case 'Admin': return <span className="bg-indigo-100 text-indigo-700 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest border border-indigo-200 flex items-center gap-1.5"><FaUserShield /> Admin</span>;
            case 'Store': return <span className="bg-amber-100 text-amber-700 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest border border-amber-200 flex items-center gap-1.5"><FaStore /> Store</span>;
            default: return <span className="bg-emerald-100 text-emerald-700 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest border border-emerald-200 flex items-center gap-1.5"><FaUserGraduate /> Customer</span>;
        }
    };

    return (
        <div className="min-h-screen bg-slate-50 flex flex-col">
            <Navbar />
            <div className="flex flex-1">
                <AdminSidebar />
                <main className="flex-1 p-8">
                    <div className="max-w-7xl mx-auto space-y-6">
                        {/* Header */}
                        <div className="flex justify-between items-end">
                            <div>
                                <h1 className="text-3xl font-black text-slate-900 tracking-tight">User Management</h1>
                                <p className="text-slate-500 font-medium">Control platform access and review user accounts.</p>
                            </div>
                            <div className="text-sm font-bold text-slate-400">Total Users: {users.length}</div>
                        </div>

                        {/* Search & Filters */}
                        <div className="bg-white p-4 rounded-3xl shadow-sm border border-slate-100 flex flex-col md:flex-row gap-4">
                            <div className="flex-1 relative">
                                <FaSearch className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
                                <input
                                    type="text"
                                    placeholder="Search by name or email..."
                                    className="w-full pl-12 pr-6 py-4 bg-slate-50 border-2 border-transparent focus:border-indigo-500 focus:bg-white rounded-2xl outline-none font-medium transition-all"
                                    value={searchQuery}
                                    onChange={(e) => setSearchQuery(e.target.value)}
                                />
                            </div>
                            <div className="flex items-center gap-2 px-4 bg-slate-50 rounded-2xl border-2 border-transparent">
                                <FaFilter className="text-slate-400" />
                                <select
                                    className="bg-transparent border-none py-4 text-sm font-bold text-slate-600 focus:ring-0 cursor-pointer"
                                    value={roleFilter}
                                    onChange={(e) => setRoleFilter(e.target.value)}
                                >
                                    <option value="All">All Roles</option>
                                    <option value="Admin">Admins</option>
                                    <option value="Store">Stores</option>
                                    <option value="Customer">Customers</option>
                                </select>
                            </div>
                        </div>

                        {/* User Table */}
                        <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-100 overflow-hidden">
                            <table className="w-full text-left">
                                <thead className="bg-slate-50 border-b border-slate-100">
                                    <tr>
                                        <th className="px-8 py-5 text-xs font-black text-slate-400 uppercase tracking-widest">User Information</th>
                                        <th className="px-8 py-5 text-xs font-black text-slate-400 uppercase tracking-widest">Role</th>
                                        <th className="px-8 py-5 text-xs font-black text-slate-400 uppercase tracking-widest text-center">Status</th>
                                        <th className="px-8 py-5 text-xs font-black text-slate-400 uppercase tracking-widest text-right">Actions</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-slate-50 font-medium">
                                    {isLoading ? (
                                        <tr><td colSpan="4" className="text-center py-20 text-slate-400 font-bold">Loading system users...</td></tr>
                                    ) : filteredUsers.length === 0 ? (
                                        <tr><td colSpan="4" className="text-center py-20 text-slate-400 font-bold">No users found matching your search.</td></tr>
                                    ) : (
                                        filteredUsers.map(user => (
                                            <tr key={user.id} className="hover:bg-slate-50/50 transition-colors">
                                                <td className="px-8 py-6">
                                                    <div className="flex items-center gap-4">
                                                        <div className="w-12 h-12 bg-slate-100 rounded-full flex items-center justify-center font-black text-slate-400 border border-slate-200 uppercase overflow-hidden">
                                                            {user.profile_image_url || user.store_logo_url ? (
                                                                <img
                                                                    src={user.profile_image_url || user.store_logo_url}
                                                                    alt={user.name}
                                                                    className="w-full h-full object-cover"
                                                                />
                                                            ) : (
                                                                user.name.charAt(0)
                                                            )}
                                                        </div>
                                                        <div>
                                                            <div className="font-bold text-slate-900">{user.name}</div>
                                                            <div className="text-sm text-slate-400">{user.email}</div>
                                                        </div>
                                                    </div>
                                                </td>
                                                <td className="px-8 py-6">
                                                    {getRoleBadge(user.role)}
                                                </td>
                                                <td className="px-8 py-6 text-center">
                                                    {user.is_active ? (
                                                        <span className="inline-flex items-center gap-1.5 text-emerald-500 font-bold text-sm">
                                                            <FaCheckCircle /> Active
                                                        </span>
                                                    ) : (
                                                        <span className="inline-flex items-center gap-1.5 text-rose-400 font-bold text-sm italic">
                                                            <FaUserSlash /> Deactivated
                                                        </span>
                                                    )}
                                                </td>
                                                <td className="px-8 py-6 text-right">
                                                    <button
                                                        onClick={() => handleDeactivate(user.id)}
                                                        className={`px-4 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${user.is_active
                                                            ? 'bg-rose-50 text-rose-500 hover:bg-rose-500 hover:text-white'
                                                            : 'bg-emerald-50 text-emerald-500 hover:bg-emerald-500 hover:text-white'}`}
                                                    >
                                                        {user.is_active ? 'Deactivate' : 'Reactivate'}
                                                    </button>
                                                </td>
                                            </tr>
                                        ))
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </main>
            </div>
            <Footer />
            <Alert message={alert.message} type={alert.type} onClose={() => setAlert({ message: '', type: '' })} />
        </div>
    );
};

export default AdminUserManagement;

import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axiosInstance from "../services/axiosInstance";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import DashboardSidebar from '../Components/DashboardSidebar';
import Alert from "../Components/Alert";
import RentalModal from "../Components/RentalModal";
import { FaHeart, FaRegHeart, FaTh, FaList, FaStar, FaFilter, FaSearch, FaChevronDown, FaChevronRight } from "react-icons/fa";

const BrowseClothes = () => {
  const navigate = useNavigate();
  const [clothes, setClothes] = useState([]);
  const [filteredClothes, setFilteredClothes] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [viewMode, setViewMode] = useState('grid');
  const [sortBy, setSortBy] = useState('popular');
  const [favorites, setFavorites] = useState([]);
  const [showFilters, setShowFilters] = useState(false);

  // Pagination State
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 6;

  // Rental states
  const [selectedClothing, setSelectedClothing] = useState(null);
  const [isRentalModalOpen, setIsRentalModalOpen] = useState(false);
  const [alert, setAlert] = useState({ message: '', type: '' });

  // Filter states
  const [filters, setFilters] = useState({
    category: '',
    size: '',
    priceRange: '',
    eventType: 'All Events',
    searchQuery: ''
  });

  const categories = ['Formal Wear', 'Casual', 'Party Wear', 'Traditional', 'Sports Wear'];
  const sizes = ['XS', 'S', 'M', 'L', 'XL', 'XXL'];
  const priceRanges = [
    { label: 'Under $20', value: '0-20' },
    { label: '$20 - $50', value: '20-50' },
    { label: '$50 - $100', value: '50-100' },
    { label: 'Over $100', value: '100-1000' }
  ];

  useEffect(() => {
    fetchClothes();
    fetchWishlist();
  }, []);

  const fetchWishlist = async () => {
    try {
      const token = localStorage.getItem("access_token");
      if (!token) return;

      const response = await axiosInstance.get("accounts/wishlist/");

      let wishlistData = [];
      if (Array.isArray(response.data)) {
        wishlistData = response.data;
      } else if (response.data?.data && Array.isArray(response.data.data)) {
        // Fix: Backend returns { data: [...] } structure
        wishlistData = response.data.data;
      } else if (response.data && Array.isArray(response.data.results)) {
        wishlistData = response.data.results;
      }

      if (wishlistData) {
        // Map wishlist items to just clothing IDs
        const wishlistedIds = wishlistData.map(item => item.clothing?.id || item.clothing_id);
        setFavorites(wishlistedIds);
      }
    } catch (error) {
      console.error("Error fetching wishlist:", error);
    }
  };

  const fetchClothes = async () => {
    try {
      setIsLoading(true);
      const response = await axiosInstance.get("accounts/clothing/all/");

      let clothingData = [];
      if (Array.isArray(response.data)) {
        clothingData = response.data;
      } else if (response.data && Array.isArray(response.data.results)) {
        clothingData = response.data.results;
      }

      setClothes(clothingData);
      setFilteredClothes(clothingData);
    } catch (error) {
      console.error("Error fetching clothes:", error);
      // Initialize with empty array on error to prevent crashes in render
      setClothes([]);
      setFilteredClothes([]);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    applyFilters();
  }, [clothes, filters, sortBy]);

  const applyFilters = () => {
    let result = [...clothes];

    // Search Query
    if (filters.searchQuery) {
      const query = filters.searchQuery.toLowerCase();
      result = result.filter(item =>
        item.item_name.toLowerCase().includes(query) ||
        item.category.toLowerCase().includes(query)
      );
    }

    // Category
    if (filters.category) {
      result = result.filter(item =>
        item.category === filters.category
      );
    }

    // Size
    if (filters.size) {
      result = result.filter(item =>
        item.size === filters.size
      );
    }

    // Price Range
    if (filters.priceRange) {
      const [min, max] = filters.priceRange.split('-').map(Number);
      result = result.filter(item => {
        const price = parseFloat(item.rental_price);
        return price >= min && price <= max;
      });
    }

    // Event Type (loose match as requested)
    if (filters.eventType && filters.eventType !== 'All Events') {
      // Assuming eventType might map to category or just text match
      result = result.filter(item =>
        item.category.includes(filters.eventType) ||
        item.description?.includes(filters.eventType)
      );
    }

    // Sorting
    switch (sortBy) {
      case 'price-low':
        result.sort((a, b) => parseFloat(a.rental_price) - parseFloat(b.rental_price));
        break;
      case 'price-high':
        result.sort((a, b) => parseFloat(b.rental_price) - parseFloat(a.rental_price));
        break;
      case 'newest':
        // Assuming there's a date or ID to sort by, fallback to ID if no date
        result.sort((a, b) => b.id - a.id);
        break;
      case 'popular':
      default:
        // Keep default order (or implement popularity logic)
        break;
    }

    setFilteredClothes(result);
  };

  // Reset to page 1 when filters or sort change
  useEffect(() => {
    setCurrentPage(1);
  }, [filters, sortBy, clothes]);

  // Pagination Logic
  const indexOfLastItem = currentPage * itemsPerPage;
  const indexOfFirstItem = indexOfLastItem - itemsPerPage;
  const paginatedClothes = filteredClothes.slice(indexOfFirstItem, indexOfLastItem);
  const totalPages = Math.ceil(filteredClothes.length / itemsPerPage);

  const goToPage = (page) => {
    if (page >= 1 && page <= totalPages) {
      setCurrentPage(page);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const nextPage = () => goToPage(currentPage + 1);
  const prevPage = () => goToPage(currentPage - 1);

  const handleFilterChange = (key, value) => {
    setFilters(prev => {
      // Handle 'All' for size
      if (key === 'size' && value === 'All') {
        return { ...prev, size: '' };
      }

      const stateKey = key === 'search' ? 'searchQuery' : key;

      // Toggle logic for Category and Size
      if (stateKey === 'category' || stateKey === 'size') {
        return {
          ...prev,
          [stateKey]: prev[stateKey] === value ? '' : value
        };
      }

      // For single values (Search, Price, Event)
      return { ...prev, [stateKey]: value };
    });
  };

  const clearFilters = () => {
    setFilters({
      category: '',
      size: '',
      priceRange: '',
      eventType: 'All Events',
      searchQuery: ''
    });
    setSortBy('popular');
  };

  const toggleFavorite = async (id) => {
    const token = localStorage.getItem("access_token");
    if (!token) {
      navigate("/login", { state: { message: "Please login to use wishlist" } });
      return;
    }

    // Optimistic Update
    const isAdding = !favorites.includes(id);
    setFavorites(prev =>
      isAdding ? [...prev, id] : prev.filter(fav => fav !== id)
    );

    try {
      if (isAdding) {
        await axiosInstance.post("accounts/wishlist/add/", { clothing_id: id });
        showAlert("Added to wishlist", "success");
      } else {
        await axiosInstance.delete(`accounts/wishlist/remove-by-clothing/${id}/`);
        showAlert("Removed from wishlist", "success");
      }
    } catch (error) {
      console.error("Error updating wishlist:", error);
      // Revert if error
      setFavorites(prev =>
        isAdding ? prev.filter(fav => fav !== id) : [...prev, id]
      );
      showAlert("Failed to update wishlist", "error");
    }
  };

  const handleRentNow = (item) => {
    const token = localStorage.getItem("access_token");
    if (!token) {
      navigate("/login", { state: { message: "Please login to continue renting" } });
      return;
    }

    // If not a customer, you might want to redirect or show alert
    const userRole = localStorage.getItem('role');
    if (userRole !== 'Customer') {
      showAlert('Only customers can rent items.', 'error');
      return;
    }
    setSelectedClothing(item);
    setIsRentalModalOpen(true);
  };

  const showAlert = (message, type) => {
    setAlert({ message, type });
  };

  const getStatusBadge = (status) => {
    const statusColors = {
      Available: 'bg-green-500',
      Rented: 'bg-blue-500',
      Unavailable: 'bg-red-500'
    };
    return statusColors[status] || 'bg-gray-500';
  };

  const isLoggedIn = !!localStorage.getItem("access_token");

  if (isLoading) {
    return (
      <>
        <Navbar />
        <div className="min-h-screen bg-gray-50 flex items-center justify-center">
          <div className="text-center">
            <div className="w-12 h-12 border-4 border-purple-500 border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
            <p className="text-gray-600">Loading clothes...</p>
          </div>
        </div>
        <Footer />
      </>
    );
  }

  return (
    <div className="bg-gray-50 min-h-screen flex flex-col">
      <Navbar />

      {isLoggedIn ? (
        <div className="flex flex-1 min-h-screen">
          <DashboardSidebar />
          <main className="flex-1 p-6">
            <div className="max-w-7xl mx-auto">
              <div className="flex flex-col lg:flex-row gap-8">
                {/* Sidebar Filters */}
                <aside className={`lg:w-80 flex-shrink-0 ${showFilters ? 'block' : 'hidden lg:block'}`}>
                  <div className="bg-white rounded-3xl shadow-md border border-gray-100 p-8 h-fit">
                    <div className="flex justify-between items-center mb-8">
                      <h3 className="text-xl font-black text-gray-900 uppercase tracking-tighter">Filters</h3>
                      <button
                        onClick={clearFilters}
                        className="text-xs font-bold text-purple-600 hover:text-purple-700 transition-colors uppercase tracking-widest"
                      >
                        Reset
                      </button>
                    </div>

                    <div className="space-y-8">
                      {/* Search */}
                      <div>
                        <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-3">Search</label>
                        <div className="relative">
                          <FaSearch className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
                          <input
                            type="text"
                            placeholder="Search items..."
                            value={filters.searchQuery}
                            onChange={(e) => handleFilterChange('searchQuery', e.target.value)}
                            className="w-full pl-12 pr-4 py-3 bg-gray-50 border border-gray-100 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500 transition-all text-sm font-medium"
                          />
                        </div>
                      </div>

                      {/* Category */}
                      <div>
                        <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-3">Category</label>
                        <div className="grid grid-cols-1 gap-2">
                          {categories.map(cat => (
                            <button
                              key={cat}
                              onClick={() => handleFilterChange('category', cat)}
                              className={`text-left px-4 py-2.5 rounded-xl text-sm font-bold transition-all ${filters.category === cat
                                ? 'bg-purple-600 text-white shadow-lg shadow-purple-100'
                                : 'bg-gray-50 text-gray-600 hover:bg-gray-100'
                                }`}
                            >
                              {cat}
                            </button>
                          ))}
                        </div>
                      </div>

                      {/* Size */}
                      <div>
                        <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-3">Size</label>
                        <div className="flex flex-wrap gap-2">
                          {['All', 'XS', 'S', 'M', 'L', 'XL', 'XXL'].map(size => (
                            <button
                              key={size}
                              onClick={() => handleFilterChange('size', size)}
                              className={`w-12 h-10 flex items-center justify-center rounded-xl text-xs font-bold transition-all ${(size === 'All' && !filters.size) || filters.size === size
                                ? 'bg-purple-600 text-white shadow-lg shadow-purple-100 scale-105'
                                : 'bg-gray-50 text-gray-600 hover:bg-gray-100'
                                }`}
                            >
                              {size}
                            </button>
                          ))}
                        </div>
                      </div>

                      {/* Price Range */}
                      <div>
                        <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-3">Price Range</label>
                        <div className="space-y-2">
                          {priceRanges.map(range => (
                            <label key={range.value} className="flex items-center gap-2 cursor-pointer group">
                              <input
                                type="radio"
                                name="priceRange"
                                checked={filters.priceRange === range.value}
                                onChange={() => handleFilterChange('priceRange', range.value)}
                                className="w-4 h-4 text-purple-600 border-gray-300 focus:ring-purple-500 cursor-pointer"
                              />
                              <span className={`text-sm transition-colors ${filters.priceRange === range.value ? 'text-purple-600 font-bold' : 'text-gray-600 group-hover:text-gray-900'}`}>
                                {range.label}
                              </span>
                            </label>
                          ))}
                        </div>
                      </div>

                      {/* Event Type */}
                      <div>
                        <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-3">Event Type</label>
                        <select
                          value={filters.eventType}
                          onChange={(e) => handleFilterChange('eventType', e.target.value)}
                          className="w-full px-4 py-2 bg-gray-50 border border-gray-100 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500 transition-all text-sm font-medium appearance-none"
                        >
                          <option>All Events</option>
                          <option>Wedding</option>
                          <option>Party</option>
                          <option>Formal</option>
                          <option>Casual</option>
                        </select>
                      </div>
                    </div>
                  </div>
                </aside>

                {/* Main Content */}
                <div className="flex-1">
                  {/* Header */}
                  <div className="mb-8 flex flex-col md:flex-row md:items-center justify-between gap-4">
                    <div>
                      <h1 className="text-3xl font-bold text-gray-900 leading-tight">Browse Clothes</h1>
                      <p className="text-gray-500 mt-1">Discover your perfect outfit for any occasion</p>
                      <div className="flex items-center gap-2 mt-4">
                        <span className="px-3 py-1 bg-purple-50 text-purple-600 rounded-full text-xs font-bold border border-purple-100 uppercase tracking-wider">
                          {filteredClothes.length} Results
                        </span>
                        <span className="text-xs text-gray-400 font-medium">Out of {clothes.length} items</span>
                      </div>
                    </div>
                    <div className="flex flex-wrap items-center gap-3">
                      <div className="relative">
                        <select
                          value={sortBy}
                          onChange={(e) => setSortBy(e.target.value)}
                          className="pl-4 pr-10 py-2.5 bg-white border border-gray-100 rounded-xl shadow-sm focus:outline-none focus:ring-2 focus:ring-purple-500 text-sm font-medium transition-all cursor-pointer appearance-none"
                        >
                          <option value="popular">Sort by: Popular</option>
                          <option value="newest">Newest First</option>
                          <option value="price-low">Price: Low to High</option>
                          <option value="price-high">Price: High to Low</option>
                        </select>
                        <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-gray-400">
                          <FaChevronDown size={10} />
                        </div>
                      </div>
                      <div className="flex p-1 bg-white border border-gray-100 rounded-xl shadow-sm">
                        <button
                          onClick={() => setViewMode('grid')}
                          className={`p-2 rounded-lg transition-all ${viewMode === 'grid' ? 'bg-purple-600 text-white shadow-md' : 'text-gray-400 hover:text-gray-600'}`}
                          title="Grid View"
                        >
                          <FaTh size={14} />
                        </button>
                        <button
                          onClick={() => setViewMode('list')}
                          className={`p-2 rounded-lg transition-all ${viewMode === 'list' ? 'bg-purple-600 text-white shadow-md' : 'text-gray-400 hover:text-gray-600'}`}
                          title="List View"
                        >
                          <FaList size={14} />
                        </button>
                      </div>
                    </div>
                  </div>

                  {/* Clothes Grid */}
                  {filteredClothes.length === 0 ? (
                    <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-20 text-center">
                      <div className="w-20 h-20 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-4">
                        <FaSearch className="text-gray-300 text-3xl" />
                      </div>
                      <h3 className="text-xl font-bold text-gray-900 mb-2">No clothes found</h3>
                      <p className="text-gray-500">Try adjusting your filters to find what you're looking for.</p>
                      <button
                        onClick={clearFilters}
                        className="mt-6 px-8 py-3 bg-purple-600 text-white font-bold rounded-xl shadow-lg shadow-purple-100 hover:bg-purple-700 transition"
                      >
                        Clear All Filters
                      </button>
                    </div>
                  ) : (
                    <div className={`grid ${viewMode === 'grid' ? 'grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6' : 'grid-cols-1 gap-6'}`}>
                      {paginatedClothes.map((item) => (
                        <div
                          key={item.id}
                          className={`group bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden hover:shadow-xl transition-all duration-300 transform hover:-translate-y-1 flex ${viewMode === 'grid' ? 'flex-col' : 'flex-row'}`}
                        >
                          <div className={`relative ${viewMode === 'grid' ? 'w-full' : 'w-72 flex-shrink-0'}`}>
                            {item.images && (
                              <img
                                src={item.images}
                                alt={item.item_name}
                                className={`w-full h-full object-cover cursor-pointer hover:opacity-95 transition-all duration-500 ${viewMode === 'grid' ? 'aspect-[4/5]' : 'h-full aspect-square'}`}
                                onClick={() => navigate(`/clothing/${item.id}`)}
                              />
                            )}
                            <div className="absolute top-4 left-4">
                              <span className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest shadow-lg backdrop-blur-md ${getStatusBadge(item.clothing_status)}`}>
                                {item.clothing_status}
                              </span>
                            </div>
                            <button
                              onClick={() => toggleFavorite(item.id)}
                              className="absolute top-4 right-4 p-3 bg-white/90 backdrop-blur-sm rounded-full shadow-sm hover:shadow-md transition-all duration-300 hover:scale-110"
                            >
                              {favorites.includes(item.id) ? (
                                <FaHeart className="text-red-500 transition-transform active:scale-125" />
                              ) : (
                                <FaRegHeart className="text-gray-600" />
                              )}
                            </button>
                          </div>

                          <div className="p-6 flex flex-col justify-between flex-1">
                            <div>
                              <div className="flex justify-between items-start mb-2">
                                <h3
                                  className="text-xl font-bold text-gray-900 leading-tight cursor-pointer hover:text-purple-600 transition-colors"
                                  onClick={() => navigate(`/clothing/${item.id}`)}
                                >
                                  {item.item_name}
                                </h3>
                                <div className="text-right">
                                  <p className="text-2xl font-black text-gray-900 leading-none">${item.rental_price}</p>
                                  <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mt-1">per day</p>
                                </div>
                              </div>
                              <p className="text-sm font-medium text-gray-500 mb-4 bg-gray-50 inline-block px-3 py-1 rounded-lg">
                                {item.category} ΓÇó {item.size}
                              </p>

                              <div className="flex items-center gap-1 mb-6">
                                {[...Array(5)].map((_, i) => (
                                  <FaStar key={i} className={`text-xs ${i < Math.round(item.average_rating || 0) ? 'text-yellow-400' : 'text-gray-200'}`} />
                                ))}
                                <span className="text-[10px] font-bold text-gray-400 ml-2">({item.review_count || 0} reviews)</span>
                              </div>
                            </div>

                            <button
                              onClick={() => navigate(`/clothing/${item.id}`)}
                              className="w-full py-4 bg-gray-900 text-white font-black rounded-xl hover:bg-purple-600 transition-all duration-300 shadow-lg shadow-gray-200 hover:shadow-purple-100 flex items-center justify-center gap-2 uppercase tracking-widest text-xs"
                            >
                              <span>Rent Now</span>
                              <FaChevronRight size={8} />
                            </button>
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              </div>

              {/* Pagination */}
              {filteredClothes.length > 0 && (
                <div className="mt-8 flex justify-center">
                  <div className="mt-8 flex justify-center">
                    <div className="flex items-center gap-2">
                      <button
                        onClick={prevPage}
                        disabled={currentPage === 1}
                        className={`px-3 py-2 border border-gray-300 rounded-lg hover:bg-gray-50 transition-colors ${currentPage === 1 ? 'opacity-50 cursor-not-allowed' : ''}`}
                      >
                        &lt;
                      </button>

                      {[...Array(totalPages)].map((_, i) => (
                        <button
                          key={i}
                          onClick={() => goToPage(i + 1)}
                          className={`px-4 py-2 rounded-lg transition-colors ${currentPage === i + 1
                            ? 'bg-purple-600 text-white shadow-md'
                            : 'border border-gray-300 hover:bg-gray-50'
                            }`}
                        >
                          {i + 1}
                        </button>
                      ))}

                      <button
                        onClick={nextPage}
                        disabled={currentPage === totalPages}
                        className={`px-3 py-2 border border-gray-300 rounded-lg hover:bg-gray-50 transition-colors ${currentPage === totalPages ? 'opacity-50 cursor-not-allowed' : ''}`}
                      >
                        &gt;
                      </button>
                    </div>
                  </div>
                </div>
              )}
            </div>
          </main>
        </div>
      ) : (
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
          <div className="flex flex-col lg:flex-row gap-8">
            {/* Sidebar Filters */}
            <aside className={`lg:w-80 flex-shrink-0 ${showFilters ? 'block' : 'hidden lg:block'}`}>
              <div className="bg-white rounded-3xl shadow-md border border-gray-100 p-8 h-fit">
                <div className="flex justify-between items-center mb-8">
                  <h3 className="text-xl font-black text-gray-900 uppercase tracking-tighter">Filters</h3>
                  <button
                    onClick={clearFilters}
                    className="text-xs font-bold text-purple-600 hover:text-purple-700 transition-colors uppercase tracking-widest"
                  >
                    Reset
                  </button>
                </div>

                <div className="space-y-8">
                  {/* Search */}
                  <div>
                    <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-3">Search</label>
                    <div className="relative">
                      <FaSearch className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
                      <input
                        type="text"
                        placeholder="Search items..."
                        value={filters.searchQuery}
                        onChange={(e) => handleFilterChange('searchQuery', e.target.value)}
                        className="w-full pl-12 pr-4 py-3 bg-gray-50 border border-gray-100 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500 transition-all text-sm font-medium"
                      />
                    </div>
                  </div>

                  {/* Category */}
                  <div>
                    <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-3">Category</label>
                    <div className="grid grid-cols-1 gap-2">
                      {categories.map(cat => (
                        <button
                          key={cat}
                          onClick={() => handleFilterChange('category', cat)}
                          className={`text-left px-4 py-2.5 rounded-xl text-sm font-bold transition-all ${filters.category === cat
                            ? 'bg-purple-600 text-white shadow-lg shadow-purple-100'
                            : 'bg-gray-50 text-gray-600 hover:bg-gray-100'
                            }`}
                        >
                          {cat}
                        </button>
                      ))}
                    </div>
                  </div>

                  {/* Size */}
                  <div>
                    <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-3">Size</label>
                    <div className="flex flex-wrap gap-2">
                      {['All', 'XS', 'S', 'M', 'L', 'XL', 'XXL'].map(size => (
                        <button
                          key={size}
                          onClick={() => handleFilterChange('size', size)}
                          className={`w-12 h-10 flex items-center justify-center rounded-xl text-xs font-bold transition-all ${(size === 'All' && !filters.size) || filters.size === size
                            ? 'bg-purple-600 text-white shadow-lg shadow-purple-100 scale-105'
                            : 'bg-gray-50 text-gray-600 hover:bg-gray-100'
                            }`}
                        >
                          {size}
                        </button>
                      ))}
                    </div>
                  </div>

                  {/* Price Range */}
                  <div>
                    <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-3">Price Range</label>
                    <div className="space-y-2">
                      {priceRanges.map(range => (
                        <label key={range.value} className="flex items-center gap-2 cursor-pointer group">
                          <input
                            type="radio"
                            name="priceRange"
                            checked={filters.priceRange === range.value}
                            onChange={() => handleFilterChange('priceRange', range.value)}
                            className="w-4 h-4 text-purple-600 border-gray-300 focus:ring-purple-500 cursor-pointer"
                          />
                          <span className={`text-sm transition-colors ${filters.priceRange === range.value ? 'text-purple-600 font-bold' : 'text-gray-600 group-hover:text-gray-900'}`}>
                            {range.label}
                          </span>
                        </label>
                      ))}
                    </div>
                  </div>

                  {/* Event Type */}
                  <div>
                    <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-3">Event Type</label>
                    <select
                      value={filters.eventType}
                      onChange={(e) => handleFilterChange('eventType', e.target.value)}
                      className="w-full px-4 py-2 bg-gray-50 border border-gray-100 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500 transition-all text-sm font-medium appearance-none"
                    >
                      <option>All Events</option>
                      <option>Wedding</option>
                      <option>Party</option>
                      <option>Formal</option>
                      <option>Casual</option>
                    </select>
                  </div>
                </div>
              </div>
            </aside>

            {/* Main Content */}
            <div className="flex-1">
              {/* Header */}
              <div className="mb-8 flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                  <h1 className="text-3xl font-bold text-gray-900 leading-tight">Browse Clothes</h1>
                  <p className="text-gray-500 mt-1">Discover your perfect outfit for any occasion</p>
                  <div className="flex items-center gap-2 mt-4">
                    <span className="px-3 py-1 bg-purple-50 text-purple-600 rounded-full text-xs font-bold border border-purple-100 uppercase tracking-wider">
                      {filteredClothes.length} Results
                    </span>
                    <span className="text-xs text-gray-400 font-medium">Out of {clothes.length} items</span>
                  </div>
                </div>
                <div className="flex flex-wrap items-center gap-3">
                  <div className="relative">
                    <select
                      value={sortBy}
                      onChange={(e) => setSortBy(e.target.value)}
                      className="pl-4 pr-10 py-2.5 bg-white border border-gray-100 rounded-xl shadow-sm focus:outline-none focus:ring-2 focus:ring-purple-500 text-sm font-medium transition-all cursor-pointer appearance-none"
                    >
                      <option value="popular">Sort by: Popular</option>
                      <option value="newest">Newest First</option>
                      <option value="price-low">Price: Low to High</option>
                      <option value="price-high">Price: High to Low</option>
                    </select>
                    <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-gray-400">
                      <FaChevronDown size={10} />
                    </div>
                  </div>
                  <div className="flex p-1 bg-white border border-gray-100 rounded-xl shadow-sm">
                    <button
                      onClick={() => setViewMode('grid')}
                      className={`p-2 rounded-lg transition-all ${viewMode === 'grid' ? 'bg-purple-600 text-white shadow-md' : 'text-gray-400 hover:text-gray-600'}`}
                      title="Grid View"
                    >
                      <FaTh size={14} />
                    </button>
                    <button
                      onClick={() => setViewMode('list')}
                      className={`p-2 rounded-lg transition-all ${viewMode === 'list' ? 'bg-purple-600 text-white shadow-md' : 'text-gray-400 hover:text-gray-600'}`}
                      title="List View"
                    >
                      <FaList size={14} />
                    </button>
                  </div>
                </div>
              </div>

              {/* Clothes Grid */}
              {filteredClothes.length === 0 ? (
                <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-20 text-center">
                  <div className="w-20 h-20 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-4">
                    <FaSearch className="text-gray-300 text-3xl" />
                  </div>
                  <h3 className="text-xl font-bold text-gray-900 mb-2">No clothes found</h3>
                  <p className="text-gray-500">Try adjusting your filters to find what you're looking for.</p>
                  <button
                    onClick={clearFilters}
                    className="mt-6 px-8 py-3 bg-purple-600 text-white font-bold rounded-xl shadow-lg shadow-purple-100 hover:bg-purple-700 transition"
                  >
                    Clear All Filters
                  </button>
                </div>
              ) : (
                <div className={`grid ${viewMode === 'grid' ? 'grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6' : 'grid-cols-1 gap-6'}`}>
                  {filteredClothes.map((item) => (
                    <div
                      key={item.id}
                      className={`group bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden hover:shadow-xl transition-all duration-300 transform hover:-translate-y-1 flex ${viewMode === 'grid' ? 'flex-col' : 'flex-row'}`}
                    >
                      <div className={`relative ${viewMode === 'grid' ? 'w-full' : 'w-72 flex-shrink-0'}`}>
                        {item.images && (
                          <img
                            src={item.images}
                            alt={item.item_name}
                            className={`w-full h-full object-cover cursor-pointer hover:opacity-95 transition-all duration-500 ${viewMode === 'grid' ? 'aspect-[4/5]' : 'h-full aspect-square'}`}
                            onClick={() => navigate(`/clothing/${item.id}`)}
                          />
                        )}
                        <div className="absolute top-4 left-4">
                          <span className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest shadow-lg backdrop-blur-md ${getStatusBadge(item.clothing_status)}`}>
                            {item.clothing_status}
                          </span>
                        </div>
                        <button
                          onClick={() => toggleFavorite(item.id)}
                          className="absolute top-4 right-4 p-3 bg-white/90 backdrop-blur-sm rounded-full shadow-sm hover:shadow-md transition-all duration-300 hover:scale-110"
                        >
                          {favorites.includes(item.id) ? (
                            <FaHeart className="text-red-500 transition-transform active:scale-125" />
                          ) : (
                            <FaRegHeart className="text-gray-600" />
                          )}
                        </button>
                      </div>

                      <div className="p-6 flex flex-col justify-between flex-1">
                        <div>
                          <div className="flex justify-between items-start mb-2">
                            <h3
                              className="text-xl font-bold text-gray-900 leading-tight cursor-pointer hover:text-purple-600 transition-colors"
                              onClick={() => navigate(`/clothing/${item.id}`)}
                            >
                              {item.item_name}
                            </h3>
                            <div className="text-right">
                              <p className="text-2xl font-black text-gray-900 leading-none">${item.rental_price}</p>
                              <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mt-1">per day</p>
                            </div>
                          </div>
                          <p className="text-sm font-medium text-gray-500 mb-4 bg-gray-50 inline-block px-3 py-1 rounded-lg">
                            {item.category} ΓÇó {item.size}
                          </p>

                          <div className="flex items-center gap-1 mb-6">
                            {[...Array(5)].map((_, i) => (
                              <FaStar key={i} className={`text-xs ${i < Math.round(item.average_rating || 0) ? 'text-yellow-400' : 'text-gray-200'}`} />
                            ))}
                            <span className="text-[10px] font-bold text-gray-400 ml-2">({item.review_count || 0} reviews)</span>
                          </div>
                        </div>

                        <button
                          onClick={() => navigate(`/clothing/${item.id}`)}
                          className="w-full py-4 bg-gray-900 text-white font-black rounded-xl hover:bg-purple-600 transition-all duration-300 shadow-lg shadow-gray-200 hover:shadow-purple-100 flex items-center justify-center gap-2 uppercase tracking-widest text-xs"
                        >
                          <span>Rent Now</span>
                          <FaChevronRight size={8} />
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>

          {/* Pagination */}
          {filteredClothes.length > 0 && (
            <div className="mt-8 flex justify-center">
              <div className="flex items-center gap-2">
                <button className="px-3 py-2 border border-gray-300 rounded-lg hover:bg-gray-50 transition-colors">
                  &lt;
                </button>
                <button className="px-4 py-2 bg-purple-600 text-white rounded-lg">1</button>
                <button className="px-4 py-2 border border-gray-300 rounded-lg hover:bg-gray-50 transition-colors">2</button>
                <button className="px-4 py-2 border border-gray-300 rounded-lg hover:bg-gray-50 transition-colors">3</button>
                <span className="px-3 py-2">...</span>
                <button className="px-4 py-2 border border-gray-300 rounded-lg hover:bg-gray-50 transition-colors">7</button>
                <button className="px-3 py-2 border border-gray-300 rounded-lg hover:bg-gray-50 transition-colors">
                  &gt;
                </button>
              </div>
            </div>
          )}
        </div>
      )}

      <Footer />

      <RentalModal
        isOpen={isRentalModalOpen}
        onClose={() => setIsRentalModalOpen(false)}
        clothing={selectedClothing || {}}
        onRentalCreated={showAlert}
      />

      <Alert
        message={alert.message}
        type={alert.type}
        onClose={() => setAlert({ message: '', type: '' })}
      />
    </div>
  );
};

export default BrowseClothes;

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import axiosInstance from '../services/axiosInstance';
import chatAxiosInstance from '../services/chatAxiosInstance';
import rentalAxiosInstance from '../services/rentalAxiosInstance';
import reviewAxiosInstance from '../services/reviewAxiosInstance';
import Navbar from '../Components/Navbar';
import Footer from '../Components/Footer';
import ReviewSection from '../Components/ReviewSection';
import ReviewForm from '../Components/ReviewForm';
import RentalModal from '../Components/RentalModal';
import StoreLocationMap from '../Components/StoreLocationMap';
import Alert from '../Components/Alert';
import { FaTag, FaRuler, FaCheckCircle, FaStore, FaArrowLeft, FaShoppingCart, FaStar, FaComments, FaDirections, FaMapMarkerAlt } from 'react-icons/fa';

const hasValidCoords = (lat, lng) =>
    lat !== null && lat !== undefined &&
    lng !== null && lng !== undefined;

const ClothingDetail = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const [clothing, setClothing] = useState(null);
    const [reviews, setReviews] = useState([]);
    const [stats, setStats] = useState({ average_rating: 0, count: 0 });
    const [isLoading, setIsLoading] = useState(true);
    const [isEligible, setIsEligible] = useState(false);
    const [eligibleRental, setEligibleRental] = useState(null);
    const [isRentalModalOpen, setIsRentalModalOpen] = useState(false);
    const [alert, setAlert] = useState({ message: '', type: '' });

    useEffect(() => {
        fetchClothingData();
        checkEligibility();
    }, [id]);

    const fetchClothingData = async () => {
        try {
            setIsLoading(true);
            const detailRes = await axiosInstance.get(`accounts/clothing/${id}/`);
            setClothing(detailRes.data);

            const reviewsRes = await reviewAxiosInstance.get(`reviews/clothing/${id}/`);
            setReviews(reviewsRes.data.results);
            setStats({
                average_rating: reviewsRes.data.average_rating,
                count: reviewsRes.data.count
            });
        } catch (error) {
            console.error('Error fetching clothing data:', error);
        } finally {
            setIsLoading(false);
        }
    };

    const checkEligibility = async () => {
        const token = localStorage.getItem('access_token');
        const role = localStorage.getItem('role');
        if (!token || role !== 'Customer') return;

        try {
            const response = await rentalAxiosInstance.get('rentals/my/');
            const userRentals = response.data.results || response.data;
            const eligible = userRentals.find(r => {
                const rentalClothingId = typeof r.clothing === 'object' ? r.clothing.id : r.clothing;
                return rentalClothingId === parseInt(id) &&
                    r.status === 'returned_confirmed' &&
                    !r.has_review;
            });
            if (eligible) {
                setIsEligible(true);
                setEligibleRental(eligible);
            }
        } catch (error) {
            console.error('Error checking eligibility:', error);
        }
    };

    const handleReviewSubmitted = () => {
        fetchClothingData();
        setIsEligible(false);
        setAlert({ message: 'Thank you for your review!', type: 'success' });
    };

    const handleChatWithStore = async () => {
        const token = localStorage.getItem('access_token');
        if (!token) {
            navigate('/login', { state: { message: "Please login to chat with the store" } });
            return;
        }

        const role = localStorage.getItem('role');
        if (role !== 'Customer') {
            showAlert('Only customers can start a chat with the store.', 'error');
            return;
        }

        try {
            const storeUserId = clothing.store || clothing.store_user_id;

            if (!storeUserId) {
                showAlert('Store information not available.', 'error');
                return;
            }

            console.log('Starting chat with store user ID:', storeUserId);
            const response = await chatAxiosInstance.post(`chat/start/${storeUserId}/`);

            if (response.data && response.data.id) {
                navigate(`/chat/${response.data.id}`);
            } else {
                console.error("Conversation not created properly", response);
                showAlert('Failed to start conversation.', 'error');
            }

        } catch (error) {
            console.error("Chat start failed:", error.response?.data || error.message);
            if (error.response?.status === 404) {
                const serverMsg = error.response.data?.error || 'Store not found.';
                showAlert(serverMsg, 'error');
            } else if (error.response?.status === 403) {
                showAlert('Permission denied.', 'error');
            } else {
                showAlert('Failed to start chat. Please try again.', 'error');
            }
        }
    };

    const scrollToMap = () => {
        document.getElementById("store-map-section")?.scrollIntoView({ behavior: "smooth" });
    };

    const showAlert = (message, type) => {
        setAlert({ message, type });
    };

    if (isLoading) {
        return (
            <div className="min-h-screen bg-gray-50 flex items-center justify-center">
                <div className="w-12 h-12 border-4 border-purple-500 border-t-transparent rounded-full animate-spin"></div>
            </div>
        );
    }

    if (!clothing) {
        return (
            <div className="min-h-screen bg-gray-50 flex items-center justify-center">
                <div className="text-center">
                    <h2 className="text-2xl font-bold text-gray-800">Item not found</h2>
                    <button onClick={() => navigate('/browseClothes')} className="mt-4 text-purple-600 font-medium flex items-center gap-2 justify-center mx-auto">
                        <FaArrowLeft /> Back to Browse
                    </button>
                </div>
            </div>
        );
    }

    return (
        <>
            <Navbar />
            <div className="min-h-screen bg-gray-50 pb-20">
                <div className="max-w-6xl mx-auto px-4 py-8">
                    <button
                        onClick={() => navigate('/browseClothes')}
                        className="flex items-center gap-2 text-gray-600 hover:text-purple-600 transition-colors mb-8 font-medium group"
                    >
                        <FaArrowLeft className="group-hover:-translate-x-1 transition-transform" />
                        Back to Collection
                    </button>

                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 bg-white rounded-3xl p-8 shadow-sm border border-gray-100">
                        <div className="space-y-4">
                            <div className="aspect-[3/4] rounded-2xl overflow-hidden bg-gray-100 group">
                                <img
                                    src={clothing.images || 'https://via.placeholder.com/600x800'}
                                    alt={clothing.item_name}
                                    className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
                                />
                            </div>
                        </div>

                        <div className="flex flex-col">
                            <div className="flex flex-wrap items-center gap-4 mb-6">
                                <div className="flex items-center gap-2 text-purple-600 text-sm font-bold uppercase tracking-wider">
                                    <FaTag size={12} />
                                    {clothing.category}
                                </div>
                                <div className="w-1.5 h-1.5 bg-gray-200 rounded-full"></div>
                                <div className="text-gray-500 text-sm font-bold uppercase tracking-wider">
                                    {clothing.event_type}
                                </div>
                            </div>

                            <h1 className="text-4xl font-extrabold text-gray-900 mb-4">{clothing.item_name}</h1>

                            <div className="flex items-center gap-4 mb-6">
                                <div className="flex items-center gap-1 text-yellow-400">
                                    {[...Array(5)].map((_, i) => (
                                        <FaStar key={i} className={i < Math.round(stats.average_rating) ? 'text-yellow-400' : 'text-gray-200'} />
                                    ))}
                                </div>
                                <span className="text-gray-500 font-medium">({stats.count} reviews)</span>
                            </div>

                            <div className="grid grid-cols-2 gap-4 mb-8">
                                <div className="bg-purple-50 rounded-2xl p-6 border border-purple-100 shadow-sm transition-all hover:shadow-md">
                                    <span className="text-xs text-purple-600 font-black uppercase tracking-widest block mb-1">Rental Price</span>
                                    <div className="flex items-baseline gap-1">
                                        <span className="text-3xl font-black text-purple-700">Γé╣{clothing.rental_price}</span>
                                        <span className="text-purple-600 font-bold text-xs">/day</span>
                                    </div>
                                </div>
                                <div className="bg-blue-50 rounded-2xl p-6 border border-blue-100 shadow-sm transition-all hover:shadow-md">
                                    <span className="text-xs text-blue-600 font-black uppercase tracking-widest block mb-1">Security Deposit</span>
                                    <div className="flex items-baseline gap-1">
                                        <span className="text-3xl font-black text-blue-700">Γé╣{clothing.security_deposit}</span>
                                        <span className="text-blue-600 font-bold text-xs">ref.</span>
                                    </div>
                                </div>
                            </div>

                            <div className="flex items-center justify-between mb-8 px-2">
                                <div className={`px-4 py-2 rounded-full text-xs font-black uppercase tracking-widest shadow-sm ${clothing.stock_quantity > 0
                                    ? 'bg-green-100 text-green-700 border border-green-200'
                                    : 'bg-red-100 text-red-700 border border-red-200'
                                    }`}>
                                    {clothing.stock_quantity > 0 ? 'Available' : 'Stock is over'}
                                </div>
                                <div className="text-sm font-bold text-gray-500 flex items-center gap-2">
                                    <span className="w-2 h-2 bg-gray-300 rounded-full"></span>
                                    In Stock: <span className="text-gray-900 font-black">{clothing.stock_quantity}</span>
                                </div>
                            </div>

                            <div className="space-y-6 mb-10">
                                <div className="flex items-start gap-4 p-4 rounded-xl hover:bg-gray-50 transition-colors">
                                    <div className="w-10 h-10 bg-gray-100 rounded-lg flex items-center justify-center text-gray-600">
                                        <FaRuler />
                                    </div>
                                    <div>
                                        <h4 className="font-bold text-gray-800">Available Sizes</h4>
                                        <div className="flex flex-wrap gap-2 mt-2">
                                            {clothing.size?.split(',').map(s => s.trim()).filter(Boolean).map(size => (
                                                <span key={size} className="px-3 py-1 bg-gray-100 text-gray-700 text-[10px] font-black uppercase tracking-widest rounded-lg border border-gray-200">
                                                    {size}
                                                </span>
                                            ))}
                                        </div>
                                    </div>
                                </div>
                                <div className="flex items-start gap-4 p-4 rounded-xl hover:bg-gray-50 transition-colors">
                                    <div className="w-10 h-10 bg-gray-100 rounded-lg flex items-center justify-center text-gray-600">
                                        <FaStore />
                                    </div>
                                    <div>
                                        <h4 className="font-bold text-gray-800">Store Partner</h4>
                                        <p className="text-gray-600">{clothing.store_name || 'RentFit Certified Store'}</p>
                                    </div>
                                </div>
                                <div className="flex items-start gap-4 p-4 rounded-xl hover:bg-gray-50 transition-colors">
                                    <div className="w-10 h-10 bg-gray-100 rounded-lg flex items-center justify-center text-gray-600">
                                        <FaMapMarkerAlt />
                                    </div>
                                    <div className="flex-1">
                                        <div className="flex items-center justify-between mb-1">
                                            <div className="flex items-center gap-2">
                                                <h4 className="font-bold text-gray-800">Store Location</h4>
                                                {hasValidCoords(clothing.store_latitude, clothing.store_longitude) && (
                                                    <span className="bg-green-100 text-green-700 text-[8px] px-1.5 py-0.5 rounded-md font-black uppercase tracking-tighter flex items-center gap-0.5">
                                                        <FaCheckCircle size={8} /> Verified
                                                    </span>
                                                )}
                                            </div>
                                            {hasValidCoords(clothing.store_latitude, clothing.store_longitude) ? (
                                                <button
                                                    onClick={scrollToMap}
                                                    className="text-[10px] text-purple-600 font-bold hover:underline flex items-center gap-1"
                                                >
                                                    <FaMapMarkerAlt size={10} /> View on Map
                                                </button>
                                            ) : (clothing.store_address || clothing.store_city) ? (
                                                <span className="text-[8px] text-gray-400 font-bold uppercase italic">Approx. Location</span>
                                            ) : null}
                                        </div>
                                        <div className="flex items-start justify-between gap-4">
                                            <p className="text-gray-600 text-sm leading-tight">
                                                {(clothing.store_address || clothing.store_city)
                                                    ? `${clothing.store_city || ''} ${clothing.store_address || ''}`
                                                    : 'Location not provided by store'}
                                            </p>
                                            {(clothing.store_address || clothing.store_city) && (
                                                <a
                                                    href={hasValidCoords(clothing.store_latitude, clothing.store_longitude)
                                                        ? `https://www.google.com/maps/dir/?api=1&destination=${clothing.store_latitude},${clothing.store_longitude}`
                                                        : `https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(`${clothing.store_address || ''} ${clothing.store_city || ''}`)}`}
                                                    target="_blank"
                                                    rel="noopener noreferrer"
                                                    className="shrink-0 bg-purple-600 text-white p-2 rounded-lg hover:bg-purple-700 transition shadow-md shadow-purple-100 flex items-center gap-1.5 text-xs font-bold"
                                                    title="Get Directions"
                                                >
                                                    <FaDirections size={14} /> get directions
                                                </a>
                                            )}
                                        </div>
                                    </div>
                                </div>
                                <div className="flex items-start gap-4 p-4 rounded-xl hover:bg-gray-50 transition-colors">
                                    <div className="w-10 h-10 bg-gray-100 rounded-lg flex items-center justify-center text-gray-600">
                                        <FaCheckCircle />
                                    </div>
                                    <div>
                                        <h4 className="font-bold text-gray-800">Description</h4>
                                        <p className="text-gray-600 leading-relaxed">
                                            {clothing.description || 'Premium quality clothing carefully inspected for your special occasion.'}
                                        </p>
                                    </div>
                                </div>
                            </div>

                            <button
                                onClick={() => setIsRentalModalOpen(true)}
                                disabled={clothing.stock_quantity === 0}
                                className="w-full bg-purple-600 text-white py-5 rounded-2xl font-black text-xl hover:bg-purple-700 shadow-xl shadow-purple-200 transition-all disabled:opacity-50 disabled:cursor-not-allowed transform hover:-translate-y-1 flex items-center justify-center gap-3"
                            >
                                <FaShoppingCart size={24} />
                                {clothing.stock_quantity > 0 ? 'Rent Now' : 'Stock Over'}
                            </button>

                            <button
                                onClick={handleChatWithStore}
                                className="w-full bg-white text-purple-600 border-2 border-purple-100 py-4 rounded-2xl font-bold text-lg hover:bg-purple-50 hover:border-purple-200 transition-all mt-4 flex items-center justify-center gap-2"
                            >
                                <FaComments size={20} />
                                Chat with Store
                            </button>
                        </div>
                    </div>

                    {isEligible && (
                        <div className="max-w-3xl mx-auto mt-12">
                            <ReviewForm
                                rental={eligibleRental}
                                onReviewSubmitted={handleReviewSubmitted}
                                onCancel={() => setIsEligible(false)}
                            />
                        </div>
                    )}

                    {/* Store Location Map */}
                    {hasValidCoords(clothing.store_latitude, clothing.store_longitude) && (
                        <div id="store-map-section" className="max-w-4xl mx-auto mt-12 bg-white p-6 rounded-2xl border border-gray-100 shadow-sm">
                            <div className="flex items-center justify-between mb-4">
                                <h3 className="font-bold text-gray-800 flex items-center gap-2">
                                    <FaMapMarkerAlt className="text-purple-500" /> Store Location
                                </h3>
                                <a
                                    href={`https://www.google.com/maps/dir/?api=1&destination=${clothing.store_latitude},${clothing.store_longitude}`}
                                    target="_blank"
                                    rel="noopener noreferrer"
                                    className="bg-purple-50 text-purple-600 px-4 py-2 rounded-lg text-xs font-bold hover:bg-purple-100 transition flex items-center gap-2"
                                >
                                    <FaDirections /> Get Directions
                                </a>
                            </div>
                            <StoreLocationMap
                                readonly={true}
                                initialLocation={{ lat: clothing.store_latitude, lng: clothing.store_longitude }}
                            />
                            <p className="text-xs text-gray-500 mt-2 italic">
                                {clothing.store_address}, {clothing.store_city}
                            </p>
                        </div>
                    )}

                    <div className="max-w-4xl mx-auto mt-12">
                        <ReviewSection
                            reviews={reviews}
                            averageRating={stats.average_rating}
                            totalReviews={stats.count}
                        />
                    </div>
                </div>
            </div>
            <Footer />

            {isRentalModalOpen && (
                <RentalModal
                    isOpen={isRentalModalOpen}
                    onClose={() => setIsRentalModalOpen(false)}
                    clothing={clothing}
                    onRentalCreated={showAlert}
                />
            )}

            <Alert
                message={alert.message}
                type={alert.type}
                onClose={() => setAlert({ message: '', type: '' })}
            />
        </>
    );
};

export default ClothingDetail;

import React, { useState, useEffect } from 'react';
import { getStoreDamageReports, takeActionOnDamageReport } from '../services/rentalAxiosInstance';
import Navbar from '../Components/Navbar';
import Footer from '../Components/Footer';
import Alert from '../Components/Alert';
import { FaExclamationTriangle, FaCheck, FaTimes, FaImage, FaUser, FaBox, FaDollarSign } from 'react-icons/fa';

const DamageReports = () => {
    const [reports, setReports] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [alert, setAlert] = useState({ message: '', type: '' });
    const [actionModal, setActionModal] = useState({ show: false, reportId: null, status: '', extraCharge: '0' });

    useEffect(() => {
        fetchReports();
    }, []);

    const fetchReports = async () => {
        try {
            setIsLoading(true);
            const response = await getStoreDamageReports();
            setReports(response.data);
        } catch (error) {
            console.error('Error fetching damage reports:', error);
            showAlert('Failed to load damage reports.', 'error');
        } finally {
            setIsLoading(false);
        }
    };

    const handleAction = async () => {
        try {
            await takeActionOnDamageReport(actionModal.reportId, {
                status: actionModal.status,
                extra_charge: actionModal.extraCharge
            });
            showAlert(`Report ${actionModal.status} successfully.`, 'success');
            setActionModal({ show: false, reportId: null, status: '', extraCharge: '0' });
            fetchReports();
        } catch (error) {
            showAlert('Failed to update report.', 'error');
        }
    };

    const showAlert = (message, type) => {
        setAlert({ message, type });
        setTimeout(() => setAlert({ message: '', type: '' }), 3000);
    };

    return (
        <div className="min-h-screen bg-gray-50">
            <Navbar />
            <div className="max-w-7xl mx-auto px-4 py-12">
                <div className="mb-10">
                    <h1 className="text-4xl font-black text-gray-900 flex items-center gap-4">
                        <FaExclamationTriangle className="text-amber-500" />
                        Damage Reports
                    </h1>
                    <p className="text-gray-500 mt-2 text-lg">Review and manage damage claims for your rental items.</p>
                </div>

                {isLoading ? (
                    <div className="flex justify-center py-20">
                        <div className="w-12 h-12 border-4 border-purple-600 border-t-transparent rounded-full animate-spin"></div>
                    </div>
                ) : reports.length === 0 ? (
                    <div className="bg-white rounded-3xl p-20 text-center shadow-sm border border-gray-100">
                        <div className="w-20 h-20 bg-green-50 rounded-full flex items-center justify-center mx-auto mb-6">
                            <FaCheck className="text-4xl text-green-500" />
                        </div>
                        <h3 className="text-2xl font-bold text-gray-900">No Pending Reports</h3>
                        <p className="text-gray-500 mt-2">All damage claims have been handled. Great job!</p>
                    </div>
                ) : (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                        {reports.map((report) => (
                            <div key={report.id} className="bg-white rounded-3xl overflow-hidden shadow-sm hover:shadow-xl transition-all border border-gray-100 flex flex-col">
                                <div className="h-56 bg-gray-200 relative group">
                                    {report.image ? (
                                        <img src={report.image} alt="Damage" className="w-full h-full object-cover" />
                                    ) : (
                                        <div className="flex flex-col items-center justify-center h-full text-gray-400 bg-gray-50">
                                            <FaImage className="text-4xl mb-2" />
                                            <span className="text-sm font-medium">No Image Uploaded</span>
                                        </div>
                                    )}
                                    <div className="absolute top-4 right-4 capitalize px-4 py-1.5 rounded-full text-xs font-black shadow-lg bg-white/90 backdrop-blur-sm border border-gray-100">
                                        {report.status}
                                    </div>
                                </div>
                                <div className="p-6 flex-1 flex flex-col">
                                    <div className="mb-4">
                                        <h3 className="text-xl font-bold text-gray-900 mb-1">{report.clothing_name}</h3>
                                        <div className="flex items-center gap-2 text-sm text-gray-500 font-medium">
                                            <FaUser className="text-purple-500" />
                                            <span>{report.user_email}</span>
                                        </div>
                                    </div>

                                    <div className="flex-1 bg-gray-50 rounded-2xl p-4 mb-6 border border-gray-100">
                                        <p className="text-sm text-gray-400 font-bold uppercase tracking-wider mb-2">Customer Description</p>
                                        <p className="text-gray-700 text-sm leading-relaxed">{report.description}</p>
                                    </div>

                                    {report.status === 'pending' && (
                                        <div className="grid grid-cols-2 gap-3 mt-auto">
                                            <button
                                                onClick={() => setActionModal({ show: true, reportId: report.id, status: 'accepted', extraCharge: '0' })}
                                                className="px-4 py-3 bg-purple-600 text-white rounded-2xl font-bold text-sm hover:bg-purple-700 transition shadow-lg shadow-purple-200 flex items-center justify-center gap-2"
                                            >
                                                <FaCheck /> Accept
                                            </button>
                                            <button
                                                onClick={() => setActionModal({ show: true, reportId: report.id, status: 'rejected', extraCharge: '0' })}
                                                className="px-4 py-3 bg-white border-2 border-gray-100 text-gray-600 rounded-2xl font-bold text-sm hover:bg-gray-50 transition flex items-center justify-center gap-2"
                                            >
                                                <FaTimes /> Reject
                                            </button>
                                        </div>
                                    )}

                                    {report.status !== 'pending' && (
                                        <div className="mt-auto py-3 px-4 bg-gray-50 rounded-2xl border border-dashed border-gray-200 flex items-center justify-between">
                                            <span className="text-sm font-bold text-gray-500">Extra Charge:</span>
                                            <span className="text-lg font-black text-purple-600">${report.extra_charge}</span>
                                        </div>
                                    )}
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </div>

            {/* Action Modal */}
            {actionModal.show && (
                <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
                    <div className="bg-white rounded-3xl p-8 max-w-md w-full shadow-2xl animate-in fade-in zoom-in duration-300">
                        <h2 className="text-2xl font-black text-gray-900 mb-2 capitalize">
                            {actionModal.status} Report
                        </h2>
                        <p className="text-gray-500 mb-6">You are marking this damage report as <span className="font-bold text-purple-600">{actionModal.status}</span>.</p>

                        {actionModal.status === 'accepted' && (
                            <div className="mb-6">
                                <label className="block text-sm font-black text-gray-700 mb-2">Extra Charge ($)</label>
                                <div className="relative">
                                    <FaDollarSign className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
                                    <input
                                        type="number"
                                        className="w-full pl-10 pr-4 py-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-purple-500 focus:outline-none font-bold text-lg"
                                        value={actionModal.extraCharge}
                                        onChange={(e) => setActionModal({ ...actionModal, extraCharge: e.target.value })}
                                        min="0"
                                    />
                                </div>
                                <p className="text-xs text-gray-400 mt-2">Enter the amount the customer needs to pay for the damage.</p>
                            </div>
                        )}

                        <div className="flex gap-4">
                            <button
                                onClick={handleAction}
                                className="flex-1 py-4 bg-purple-600 text-white rounded-2xl font-black text-lg hover:bg-purple-700 transition shadow-xl shadow-purple-200"
                            >
                                Confirm
                            </button>
                            <button
                                onClick={() => setActionModal({ show: false, reportId: null, status: '', extraCharge: '0' })}
                                className="flex-1 py-4 bg-gray-100 text-gray-600 rounded-2xl font-black text-lg hover:bg-gray-200 transition"
                            >
                                Cancel
                            </button>
                        </div>
                    </div>
                </div>
            )}

            <Footer />
            <Alert message={alert.message} type={alert.type} onClose={() => setAlert({ message: '', type: '' })} />
        </div>
    );
};

export default DamageReports;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axiosInstance from '../services/axiosInstance';
import donationAxios from '../services/donationAxios';
import rentalAxiosInstance from '../services/rentalAxiosInstance';
import Navbar from '../Components/Navbar';
import Footer from '../Components/Footer';
import DashboardSidebar from '../Components/DashboardSidebar';
import {
  FaHeart,
  FaHandHoldingHeart,
  FaMapMarkerAlt,
  FaDollarSign,
  FaShoppingBag,
  FaBox,
  FaBell,
  FaClock,
  FaUndo
} from 'react-icons/fa';

const Dashboard = () => {
  const navigate = useNavigate();
  const [userInfo, setUserInfo] = useState(() => {
    try {
      const savedUser = JSON.parse(localStorage.getItem('user') || '{}');
      return {
        fullName: savedUser.name || "User",
        email: savedUser.email || "",
        phone: savedUser.phone || "",
        profileImage: savedUser.profile_image_url || savedUser.profile_image || "",
        role: localStorage.getItem('role') || "Customer"
      };
    } catch (e) {
      return { fullName: "User", email: "", phone: "", profileImage: "", role: "Customer" };
    }
  });
  const [userName, setUserName] = useState(userInfo.fullName);
  const [isLoading, setIsLoading] = useState(true);
  const [dashboardData, setDashboardData] = useState({
    activeRentals: 0,
    wishlistItems: 0,
    totalSpent: 0,
    itemsDonated: 0,
    suggestedItems: [],
    rentalHistory: [],
    upcomingRentals: []
  });

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      const token = localStorage.getItem("access_token");
      if (!token) {
        navigate('/login');
        return;
      }

      // Fetch user profile
      const profileResponse = await axiosInstance.get("accounts/customers/profile/");
      const profileData = profileResponse.data?.data || profileResponse.data;
      if (profileData) {
        const name = profileData.full_name || profileData.name || "User";
        setUserName(name);
        setUserInfo({
          fullName: name,
          email: profileData.email || "",
          phone: profileData.phone_number || profileData.phone || "",
          profileImage: profileData.profile_image_url || profileData.profile_image || "",
          role: profileData.role || "Customer"
        });
      }

      // Fetch dashboard statistics
      try {
        const statsResponse = await axiosInstance.get("accounts/dashboard/stats/");
        console.log("RAW STATS RESPONSE:", statsResponse.data); // debug - remove after fix confirmed
        const stats = statsResponse.data?.data || statsResponse.data;
        if (stats) {
          setDashboardData(prev => ({
            ...prev,
            activeRentals: stats.active_rentals || 0,
            wishlistItems: stats.wishlist_items || 0,
            totalSpent: stats.total_spent || 0,
            itemsDonated: stats.items_donated || 0
          }));
        }
      } catch (error) {
        console.error("Error fetching dashboard stats:", error);
      }

      // Fetch current rentals & recent activity
      let allUserRentals = [];
      try {
        const rentalsResponse = await rentalAxiosInstance.get("rentals/my/");
        const rentalsData = rentalsResponse.data?.data || rentalsResponse.data;
        if (rentalsData) {
          allUserRentals = Array.isArray(rentalsData) ? rentalsData : (rentalsData.results || []);

          // Recent Activity: Sort by updated_at (or created_at) DESC and take 5
          const history = [...allUserRentals].sort((a, b) =>
            new Date(b.updated_at || b.created_at) - new Date(a.updated_at || a.created_at)
          ).slice(0, 5);


          // Upcoming Returns: status 'rented' ONLY, sort by rent_end_date ASC
          const upcoming = [...allUserRentals]
            .filter(r => r.status === 'rented')
            .sort((a, b) => new Date(a.rent_end_date) - new Date(b.rent_end_date))
            .slice(0, 3);

          setDashboardData(prev => ({
            ...prev,
            rentalHistory: history,
            upcomingRentals: upcoming
          }));
        }
      } catch (error) {
        console.log("Rentals endpoint error:", error);
      }

      // Fetch suggested clothes
      try {
        const clothesResponse = await axiosInstance.get("accounts/clothing/all/");
        const clothesData = clothesResponse.data?.data || clothesResponse.data;
        if (clothesData) {
          const clothes = Array.isArray(clothesData) ? clothesData : (clothesData.results || []);

          // Get IDs of items already rented/requested by user
          const rentedClothingIds = new Set(allUserRentals.map(r => r.clothing?.id || r.clothing_id));

          // Suggested: Newest first (created_at DESC), excluding already rented, take 5
          const suggestions = clothes
            .filter(item => !rentedClothingIds.has(item.id))
            .sort((a, b) => new Date(b.created_at) - new Date(a.created_at))
            .slice(0, 5);

          setDashboardData(prev => ({
            ...prev,
            suggestedItems: suggestions
          }));
        }
      } catch (error) {
        console.log("Clothes endpoint error:", error);
      }

    } catch (error) {
      console.error("Error fetching dashboard data:", error);
      if (error.response?.status === 401) {
        localStorage.clear();
        navigate('/login');
      }
    } finally {
      setIsLoading(false);
    }
  };

  const formatTime = (timestamp) => {
    if (!timestamp) return 'Recently';

    const date = new Date(timestamp);
    const now = new Date();
    const diffMs = now - date;
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMs / 3600000);
    const diffDays = Math.floor(diffMs / 86400000);

    if (diffMins < 60) return `${diffMins} mins ago`;
    if (diffHours < 24) return `${diffHours} hours ago`;
    if (diffDays < 7) return `${diffDays} days ago`;
    return date.toLocaleDateString();
  };

  // Helper to format date nicely
  const formatDate = (dateStr) => {
    if (!dateStr) return 'N/A';
    const date = new Date(dateStr);
    return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
  };

  // Helper to get status badge styles
  const getStatusStyle = (status) => {
    switch (status) {
      case 'pending':
        return 'bg-yellow-100 text-yellow-600';
      case 'approved':
        return 'bg-green-100 text-green-600';
      case 'rented':
        return 'bg-orange-100 text-orange-600';
      case 'returned_pending':
        return 'bg-blue-100 text-blue-600';
      case 'returned_confirmed':
        return 'bg-gray-100 text-gray-600';
      default:
        return 'bg-blue-100 text-blue-600';
    }
  };

  // Helper to format status label
  const getStatusLabel = (status) => {
    switch (status) {
      case 'pending': return 'Pending';
      case 'approved': return 'Approved';
      case 'rented': return 'Rented';
      case 'returned_pending': return 'Return Pending';
      case 'returned_confirmed': return 'Returned';
      default: return status || 'Active';
    }
  };

  const getUpcomingStatus = (dateStr) => {
    if (!dateStr) return { label: 'Active', style: 'bg-gray-100 text-gray-600' };
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const endDate = new Date(dateStr);
    endDate.setHours(0, 0, 0, 0);
    const diffDays = Math.ceil((endDate - today) / (1000 * 60 * 60 * 24));

    if (diffDays < 0) return { label: 'Overdue', style: 'bg-red-50 text-red-600 border-red-100 shadow-sm shadow-red-50' };
    if (diffDays === 0) return { label: 'Due Today', style: 'bg-blue-50 text-blue-600 border-blue-100' };
    if (diffDays === 1) return { label: 'Due Tomorrow', style: 'bg-orange-50 text-orange-600 border-orange-100' };
    return { label: 'Upcoming', style: 'bg-gray-50 text-gray-500 border-gray-100' };
  };

  if (isLoading) {
    return (
      <div className="flex justify-center items-center min-h-screen bg-gradient-to-r from-purple-500 via-pink-500 to-blue-500">
        <div className="text-center text-white">
          <div className="w-12 h-12 border-4 border-white border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
          <p>Loading dashboard...</p>
        </div>
      </div>
    );
  }

  return (
    <>
      <Navbar />
      <div className="flex min-h-screen bg-gray-50 text-gray-800">
        <DashboardSidebar />

        {/* Main Content */}
        <div className="flex-1 flex flex-col min-h-screen">
          {/* Header */}
          <div className="bg-white border-b border-gray-200 sticky top-0 z-10">
            <div className="px-8 py-5 flex items-center justify-between">
              <div className="flex-1">
                <h2 className="text-2xl font-bold text-gray-800">User Dashboard</h2>
                <p className="text-sm text-gray-500 mt-1">
                  Welcome back, {userInfo.fullName || 'User'}. Manage your rentals and explore new outfits.
                </p>
              </div>
              <div className="flex items-center gap-4">
                <div className="flex items-center gap-3 pl-4 border-l border-gray-200">
                  <div className="relative w-10 h-10 rounded-full overflow-hidden bg-gray-200 group cursor-pointer border border-gray-100 shadow-sm">
                    <div className="absolute inset-0 flex items-center justify-center text-gray-600 text-lg font-bold z-0">
                      {(userInfo.fullName || 'User').charAt(0).toUpperCase()}
                    </div>
                    {userInfo.profileImage && (
                      <img
                        src={userInfo.profileImage}
                        alt="Profile"
                        className="absolute inset-0 w-full h-full object-cover z-10"
                        onError={(e) => { e.target.style.display = 'none'; }}
                      />
                    )}
                  </div>
                  <div className="flex flex-col items-start">
                    <p className="text-sm font-medium text-gray-800">{userInfo.fullName || 'User'}</p>
                    <p className="text-xs text-gray-500">{userInfo.role || 'Customer'}</p>
                  </div>
                </div>
              </div>
            </div>
          </div>
          <main className="flex-1 p-8 pt-0 overflow-y-auto">

            {/* Stats Cards */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
              <div className="bg-white p-6 rounded-xl shadow-lg flex flex-col justify-between h-full">
                <div className="flex justify-between items-start mb-2">
                  <div>
                    <p className="text-sm text-gray-600 mb-1">Active Rentals</p>
                    <p className="text-3xl font-bold text-gray-800">{dashboardData.activeRentals}</p>
                  </div>
                  <div className="w-10 h-10 bg-blue-50 rounded-lg flex items-center justify-center flex-shrink-0">
                    <FaShoppingBag className="text-blue-600 text-lg" />
                  </div>
                </div>
              </div>

              <div className="bg-white p-6 rounded-xl shadow-lg flex flex-col justify-between h-full">
                <div className="flex justify-between items-start mb-2">
                  <div>
                    <p className="text-sm text-gray-600 mb-1">Wishlist Items</p>
                    <p className="text-3xl font-bold text-gray-800">{dashboardData.wishlistItems}</p>
                  </div>
                  <div className="w-10 h-10 bg-pink-50 rounded-lg flex items-center justify-center flex-shrink-0">
                    <FaHeart className="text-pink-600 text-lg" />
                  </div>
                </div>
              </div>

              <div className="bg-white p-6 rounded-xl shadow-lg flex flex-col justify-between h-full">
                <div className="flex justify-between items-start mb-2">
                  <div>
                    <p className="text-sm text-gray-600 mb-1">Total Spent</p>
                    <p className="text-3xl font-bold text-gray-800">${dashboardData.totalSpent}</p>
                  </div>
                  <div className="w-10 h-10 bg-green-50 rounded-lg flex items-center justify-center flex-shrink-0">
                    <FaDollarSign className="text-green-600 text-lg" />
                  </div>
                </div>
              </div>

              <div className="bg-white p-6 rounded-xl shadow-lg flex flex-col justify-between h-full">
                <div className="flex justify-between items-start mb-2">
                  <div>
                    <p className="text-sm text-gray-600 mb-1">Items Donated</p>
                    <p className="text-3xl font-bold text-gray-800">{dashboardData.itemsDonated}</p>
                  </div>
                  <div className="w-10 h-10 bg-purple-50 rounded-lg flex items-center justify-center flex-shrink-0">
                    <FaHandHoldingHeart className="text-purple-600 text-lg" />
                  </div>
                </div>
              </div>
            </div>

            {/* Upcoming Returns Section */}
            {dashboardData.upcomingRentals.length > 0 && (
              <div className="mb-8">
                <div className="flex items-center justify-between mb-4">
                  <h2 className="text-xl font-black text-gray-900 flex items-center gap-2">
                    <FaClock className="text-orange-500" />
                    Upcoming Returns
                  </h2>
                  <button onClick={() => navigate('/myrentals')} className="text-sm font-bold text-indigo-600 hover:underline">
                    Manage All
                  </button>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  {dashboardData.upcomingRentals.map((rental) => {
                    const status = getUpcomingStatus(rental.rent_end_date);
                    const isOverdue = status.label === 'Overdue';
                    return (
                      <div
                        key={rental.id}
                        className={`bg-white rounded-2xl p-4 border border-gray-100 shadow-sm hover:shadow-md transition-all duration-300 flex items-center gap-4 ${isOverdue ? 'bg-red-50/30 border-red-100 ring-1 ring-red-100' : ''
                          }`}
                      >
                        <div className="w-16 h-20 bg-gray-100 rounded-xl overflow-hidden flex-shrink-0">
                          {rental.clothing?.images && (
                            <img src={rental.clothing.images} alt="" className="w-full h-full object-cover" />
                          )}
                        </div>
                        <div className="flex-1 min-w-0">
                          <h3 className="font-bold text-gray-900 truncate text-sm">{rental.clothing_name}</h3>
                          <p className="text-[10px] text-gray-400 font-bold uppercase tracking-wider mt-0.5">
                            Due: {formatDate(rental.rent_end_date)}
                          </p>
                          <div className={`mt-2 inline-block px-2 py-0.5 rounded-lg text-[9px] font-black uppercase tracking-widest border ${status.style}`}>
                            {status.label}
                          </div>
                        </div>
                        <button
                          onClick={() => navigate('/myrentals')}
                          className="bg-indigo-600 text-white p-2 rounded-lg hover:bg-indigo-700 transition shadow-lg shadow-indigo-100"
                        >
                          <FaUndo className="text-xs" />
                        </button>
                      </div>
                    );
                  })}
                </div>
              </div>
            )}

            {/* Content Grid */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
              {/* Suggested For You */}
              <div className="lg:col-span-2 bg-white rounded-xl shadow-lg p-6">
                <div className="flex justify-between items-center mb-6">
                  <div>
                    <h2 className="text-xl font-bold text-gray-800">Suggested For You</h2>
                    <p className="text-sm text-gray-500">Discover newly added outfits you might like.</p>
                  </div>
                  <button
                    onClick={() => navigate('/browseClothes')}
                    className="text-sm font-bold text-purple-600 hover:text-purple-700"
                  >
                    View All
                  </button>
                </div>

                {dashboardData.suggestedItems.length === 0 ? (
                  <div className="text-center py-12 bg-gray-50 rounded-xl border border-dashed border-gray-200">
                    <FaShoppingBag className="text-4xl mx-auto mb-3 text-gray-300" />
                    <p className="text-gray-500 font-medium">No new outfits available right now.</p>
                    <button
                      onClick={() => navigate('/browseClothes')}
                      className="mt-4 px-6 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 transition shadow-md"
                    >
                      Explore Collection
                    </button>
                  </div>
                ) : (
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {dashboardData.suggestedItems.map((item) => (
                      <div
                        key={item.id}
                        onClick={() => navigate(`/clothing/${item.id}`)}
                        className="group flex items-center gap-4 p-3 bg-gray-50 rounded-xl border border-transparent hover:border-purple-200 hover:bg-white hover:shadow-md transition-all cursor-pointer"
                      >
                        <div className="w-20 h-24 bg-gray-200 rounded-lg overflow-hidden flex-shrink-0">
                          {item.images && (
                            <img
                              src={item.images}
                              alt={item.item_name}
                              className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500"
                            />
                          )}
                        </div>
                        <div className="flex-1 min-w-0">
                          <h3 className="font-bold text-gray-800 truncate group-hover:text-purple-600 transition-colors">
                            {item.item_name}
                          </h3>
                          <p className="text-xs text-gray-500 mb-2">{item.category}</p>
                          <div className="flex items-center justify-between">
                            <span className="text-sm font-black text-gray-900">${item.rental_price}</span>
                            <span className="text-[10px] font-bold text-purple-600 bg-purple-50 px-2 py-0.5 rounded uppercase">New</span>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>

              {/* Quick Actions & Recent Activity */}
              <div className="space-y-6">
                {/* Quick Actions */}
                <div className="bg-white rounded-xl shadow-lg p-6">
                  <h2 className="text-lg font-bold text-gray-800 mb-4">Quick Actions</h2>
                  <div className="space-y-3">
                    <button onClick={() => navigate('/donate')} className="w-full flex items-center gap-3 px-4 py-3 bg-purple-50 text-purple-600 rounded-lg hover:bg-purple-100 transition">
                      <FaHandHoldingHeart />
                      <span className="text-sm font-medium">Donate Items</span>
                    </button>
                    <button onClick={() => navigate('/mydonations')} className="w-full flex items-center gap-3 px-4 py-3 bg-blue-50 text-blue-600 rounded-lg hover:bg-blue-100 transition">
                      <FaBox />
                      <span className="text-sm font-medium">View My Donations</span>
                    </button>
                    <button className="w-full flex items-center gap-3 px-4 py-3 bg-gray-50 text-gray-600 rounded-lg hover:bg-gray-100 transition">
                      <FaMapMarkerAlt />
                      <span className="text-sm font-medium">Find Nearby Shops</span>
                    </button>
                  </div>
                </div>

                {/* Recent Activity */}
                <div className="bg-white rounded-xl shadow-lg p-6">
                  <h2 className="text-lg font-bold text-gray-800 mb-4">Recent Activity</h2>
                  {dashboardData.rentalHistory.length === 0 ? (
                    <p className="text-sm text-gray-500 text-center py-4">No recent activity</p>
                  ) : (
                    <div className="space-y-4">
                      {dashboardData.rentalHistory.map((rental, index) => (
                        <div key={rental.id || index} className="flex gap-3 pb-4 border-b border-gray-50 last:border-0 last:pb-0">
                          <div className="w-12 h-14 bg-gray-100 rounded-md overflow-hidden flex-shrink-0">
                            {rental.clothing?.images && (
                              <img
                                src={rental.clothing.images}
                                alt={rental.clothing_name}
                                className="w-full h-full object-cover"
                              />
                            )}
                          </div>
                          <div className="flex-1 min-w-0">
                            <div className="flex items-center justify-between mb-1">
                              <p className="text-sm font-bold text-gray-800 truncate">{rental.clothing_name}</p>
                              <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold ${getStatusStyle(rental.status)}`}>
                                {getStatusLabel(rental.status)}
                              </span>
                            </div>
                            <p className="text-[10px] text-gray-500">
                              {formatTime(rental.updated_at || rental.created_at)}
                            </p>
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              </div>
            </div>
          </main>
        </div>
      </div>
      <Footer />
    </>
  );
};

export default Dashboard;

import React, { useState, useEffect } from "react";
import { useNavigate, Link } from "react-router-dom";
import donationAxios from "../services/donationAxios";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import DashboardSidebar from '../Components/DashboardSidebar';
import DonationSteps from "../Components/DonationSteps";
import { FaTshirt, FaStore, FaImage, FaLock, FaUserPlus, FaSignInAlt } from "react-icons/fa";

const DonateClothing = () => {
  const navigate = useNavigate();
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [stores, setStores] = useState([]);
  const [formData, setFormData] = useState({
    store_id: "",
    item_name: "",
    category: "",
    gender: "",
    size: "",
    condition: "",
    description: "",
    images: null,
  });
  const [errors, setErrors] = useState({});
  const [message, setMessage] = useState({ type: "", text: "" });
  const [isLoading, setIsLoading] = useState(false);
  const [isLoadingStores, setIsLoadingStores] = useState(false);

  useEffect(() => {
    const token = localStorage.getItem("access_token");
    const role = localStorage.getItem("role");

    if (token) {
      setIsAuthenticated(true);
      if (role === "Store") {
        // Store accounts shouldn't be donating, but we'll show them steps
        // Maybe redirect them if they try to access the form section specifically
      } else {
        fetchStores();
      }
    }
  }, []);

  const fetchStores = async () => {
    try {
      setIsLoadingStores(true);
      const response = await donationAxios.get("donations/stores/");
      if (response.data && response.data.stores) {
        setStores(response.data.stores);
      }
    } catch (error) {
      console.error("Error fetching stores:", error);
      // Only show error message if user is authenticated and not a store
      const role = localStorage.getItem("role");
      if (role !== "Store") {
        if (error.response && (error.response.status === 401 || error.response.status === 403)) {
          // Token might be expired
          setIsAuthenticated(false);
        } else {
          setMessage({ type: "error", text: "Failed to load stores. Please try again." });
        }
      }
    } finally {
      setIsLoadingStores(false);
    }
  };

  const handleChange = (e) => {
    const { name, value, files } = e.target;
    setFormData({
      ...formData,
      [name]: files ? files[0] : value,
    });
    // Clear error for this field
    if (errors[name]) {
      setErrors({ ...errors, [name]: "" });
    }
    if (message.text) {
      setMessage({ type: "", text: "" });
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    // Safety check for role
    const role = localStorage.getItem("role");
    if (role === "Store") {
      alert("Store accounts cannot make donations.");
      return;
    }

    setErrors({});
    setMessage({ type: "", text: "" });

    // Validation
    const validationErrors = {};
    if (!formData.store_id) validationErrors.store_id = "Please select a store";
    if (!formData.item_name) validationErrors.item_name = "Item name is required";
    if (!formData.category) validationErrors.category = "Category is required";
    if (!formData.gender) validationErrors.gender = "Gender is required";
    if (!formData.size) validationErrors.size = "Size is required";
    if (!formData.condition) validationErrors.condition = "Condition is required";

    if (Object.keys(validationErrors).length > 0) {
      setErrors(validationErrors);
      return;
    }

    setIsLoading(true);

    try {
      const formDataToSend = new FormData();
      formDataToSend.append("store_id", formData.store_id);
      formDataToSend.append("item_name", formData.item_name);
      formDataToSend.append("category", formData.category);
      formDataToSend.append("gender", formData.gender);
      formDataToSend.append("size", formData.size);
      formDataToSend.append("condition", formData.condition);
      if (formData.description) formDataToSend.append("description", formData.description);
      if (formData.images) formDataToSend.append("images", formData.images);

      const response = await donationAxios.post("donations/create/", formDataToSend, {
        headers: {
          "Content-Type": "multipart/form-data",
        },
      });

      setMessage({ type: "success", text: "Donation submitted successfully! The store will review it." });
      setTimeout(() => {
        navigate("/mydonations");
      }, 2000);
    } catch (error) {
      console.error("Donation submission error:", error);
      let errorMessage = "Failed to submit donation. Please try again.";
      if (error.response?.data) {
        const errorData = error.response.data;
        if (errorData.store_id) {
          errorMessage = Array.isArray(errorData.store_id) ? errorData.store_id[0] : errorData.store_id;
        } else if (errorData.item_name) {
          errorMessage = Array.isArray(errorData.item_name) ? errorData.item_name[0] : errorData.item_name;
        } else if (errorData.message) {
          errorMessage = errorData.message;
        } else if (errorData.error) {
          errorMessage = errorData.error;
        }
      }
      setMessage({ type: "error", text: errorMessage });
    } finally {
      setIsLoading(false);
    }
  };

  const isLoggedIn = !!localStorage.getItem("access_token");
  const userRole = localStorage.getItem("role");

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col">
      <Navbar />

      {isLoggedIn ? (
        <div className="flex flex-1 min-h-screen">
          <DashboardSidebar />
          <main className="flex-1 p-6 md:p-8 space-y-8">
            <div className="max-w-7xl mx-auto">
              <div className="text-center">
                <h1 className="text-4xl md:text-5xl font-extrabold text-gray-900 mb-4">
                  Give Your Clothes a <span className="text-purple-600">New Life</span>
                </h1>
                <p className="text-lg text-gray-600 max-w-2xl mx-auto">
                  Join RentFit's sustainable fashion movement. Donate your gently used clothes
                  and help us reduce textile waste while supporting others.
                </p>
              </div>

              {/* Donation Steps Component - Always Visible */}
              <DonationSteps />

              <div className="max-w-3xl mx-auto w-full">
                {/* Conditional Rendering: Form or CTA */}
                {isAuthenticated && userRole === "Customer" ? (
                  <div className="bg-white rounded-2xl shadow-xl overflow-hidden border border-gray-100">
                    <div className="bg-purple-600 p-6 text-white">
                      <div className="flex items-center gap-3">
                        <FaTshirt className="text-2xl" />
                        <h2 className="text-2xl font-bold">Donation Form</h2>
                      </div>
                      <p className="text-purple-100 mt-1">Provide details of the item you wish to donate.</p>
                    </div>

                    <div className="p-8">
                      {/* Message Display */}
                      {message.text && (
                        <div
                          className={`mb-6 p-4 rounded-xl flex items-center gap-3 ${message.type === "success"
                            ? "bg-green-50 text-green-800 border border-green-200"
                            : "bg-red-50 text-red-800 border border-red-200"
                            }`}
                        >
                          <div className={`w-2 h-2 rounded-full ${message.type === "success" ? "bg-green-500" : "bg-red-500"}`} />
                          {message.text}
                        </div>
                      )}

                      <form onSubmit={handleSubmit} className="space-y-6">
                        {/* Store Selection */}
                        <div>
                          <label className="block text-sm font-semibold text-gray-700 mb-2">
                            <FaStore className="inline mr-2 text-purple-600" />
                            Select Store *
                          </label>
                          {isLoadingStores ? (
                            <div className="p-4 border border-dashed rounded-xl bg-gray-50 text-gray-500 animate-pulse">
                              Finding available stores...
                            </div>
                          ) : (
                            <select
                              name="store_id"
                              value={formData.store_id}
                              onChange={handleChange}
                              className={`w-full p-3 bg-gray-50 border rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500 transition-all ${errors.store_id ? "border-red-500" : "border-gray-200"
                                }`}
                            >
                              <option value="">-- Select a store near you --</option>
                              {stores.map((store) => (
                                <option key={store.id} value={store.id}>
                                  {store.store_name} {store.city ? `- ${store.city}` : ""}
                                </option>
                              ))}
                            </select>
                          )}
                          {errors.store_id && (
                            <p className="text-red-500 text-xs mt-1 font-medium">{errors.store_id}</p>
                          )}
                        </div>

                        {/* Item Name */}
                        <div>
                          <label className="block text-sm font-semibold text-gray-700 mb-2">
                            Item Name *
                          </label>
                          <input
                            type="text"
                            name="item_name"
                            placeholder="e.g., Vintage Silk Dress"
                            value={formData.item_name}
                            onChange={handleChange}
                            className={`w-full p-3 bg-gray-50 border rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500 transition-all ${errors.item_name ? "border-red-500" : "border-gray-200"
                              }`}
                          />
                          {errors.item_name && (
                            <p className="text-red-500 text-xs mt-1 font-medium">{errors.item_name}</p>
                          )}
                        </div>

                        {/* Category and Gender */}
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                          <div>
                            <label className="block text-sm font-semibold text-gray-700 mb-2">
                              Category *
                            </label>
                            <select
                              name="category"
                              value={formData.category}
                              onChange={handleChange}
                              className={`w-full p-3 bg-gray-50 border rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500 transition-all ${errors.category ? "border-red-500" : "border-gray-200"
                                }`}
                            >
                              <option value="">-- Select category --</option>
                              <option value="Shirt">Shirt</option>
                              <option value="Pants">Pants</option>
                              <option value="Dress">Dress</option>
                              <option value="Jacket">Jacket</option>
                              <option value="Skirt">Skirt</option>
                              <option value="Shoes">Shoes</option>
                              <option value="Accessories">Accessories</option>
                              <option value="Other">Other</option>
                            </select>
                            {errors.category && (
                              <p className="text-red-500 text-xs mt-1 font-medium">{errors.category}</p>
                            )}
                          </div>

                          <div>
                            <label className="block text-sm font-semibold text-gray-700 mb-2">
                              Gender *
                            </label>
                            <select
                              name="gender"
                              value={formData.gender}
                              onChange={handleChange}
                              className={`w-full p-3 bg-gray-50 border rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500 transition-all ${errors.gender ? "border-red-500" : "border-gray-200"
                                }`}
                            >
                              <option value="">-- Select gender --</option>
                              <option value="Male">Male</option>
                              <option value="Female">Female</option>
                              <option value="Unisex">Unisex</option>
                              <option value="Other">Other</option>
                            </select>
                            {errors.gender && (
                              <p className="text-red-500 text-xs mt-1 font-medium">{errors.gender}</p>
                            )}
                          </div>
                        </div>

                        {/* Size and Condition */}
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                          <div>
                            <label className="block text-sm font-semibold text-gray-700 mb-2">
                              Size *
                            </label>
                            <input
                              type="text"
                              name="size"
                              placeholder="e.g., M, L, 40 etc."
                              value={formData.size}
                              onChange={handleChange}
                              className={`w-full p-3 bg-gray-50 border rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500 transition-all ${errors.size ? "border-red-500" : "border-gray-200"
                                }`}
                            />
                            {errors.size && (
                              <p className="text-red-500 text-xs mt-1 font-medium">{errors.size}</p>
                            )}
                          </div>

                          <div>
                            <label className="block text-sm font-semibold text-gray-700 mb-2">
                              Condition *
                            </label>
                            <select
                              name="condition"
                              value={formData.condition}
                              onChange={handleChange}
                              className={`w-full p-3 bg-gray-50 border rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500 transition-all ${errors.condition ? "border-red-500" : "border-gray-200"
                                }`}
                            >
                              <option value="">-- Select condition --</option>
                              <option value="New">New</option>
                              <option value="Like New">Like New</option>
                              <option value="Good">Good</option>
                              <option value="Used">Used</option>
                            </select>
                            {errors.condition && (
                              <p className="text-red-500 text-xs mt-1 font-medium">{errors.condition}</p>
                            )}
                          </div>
                        </div>

                        {/* Description */}
                        <div>
                          <label className="block text-sm font-semibold text-gray-700 mb-2">
                            Description (Optional)
                          </label>
                          <textarea
                            name="description"
                            placeholder="Briefly describe the item (brand, fabric, etc.)..."
                            value={formData.description}
                            onChange={handleChange}
                            rows="4"
                            className="w-full p-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500 transition-all"
                          />
                        </div>

                        {/* Image Upload */}
                        <div>
                          <label className="block text-sm font-semibold text-gray-700 mb-2">
                            <FaImage className="inline mr-2 text-purple-600" />
                            Item Photo
                          </label>
                          <div className="flex items-center justify-center w-full">
                            <label className="flex flex-col items-center justify-center w-full h-32 border-2 border-gray-300 border-dashed rounded-xl cursor-pointer bg-gray-50 hover:bg-gray-100 transition-all">
                              <div className="flex flex-col items-center justify-center pt-5 pb-6">
                                <FaImage className="w-8 h-8 mb-3 text-gray-400" />
                                <p className="mb-2 text-sm text-gray-500 font-medium">
                                  {formData.images ? formData.images.name : "Click to upload garment photo"}
                                </p>
                              </div>
                              <input
                                type="file"
                                name="images"
                                accept="image/*"
                                onChange={handleChange}
                                className="hidden"
                              />
                            </label>
                          </div>
                        </div>

                        {/* Submit Buttons */}
                        <div className="flex flex-col sm:flex-row gap-4 pt-4">
                          <button
                            type="submit"
                            disabled={isLoading || isLoadingStores}
                            className="flex-1 bg-purple-600 text-white p-4 rounded-xl font-bold hover:bg-purple-700 shadow-lg shadow-purple-200 transition-all disabled:opacity-50 disabled:cursor-not-allowed transform hover:-translate-y-1"
                          >
                            {isLoading ? "Submitting Request..." : "Submit Donation Pledge"}
                          </button>
                          <button
                            type="button"
                            onClick={() => navigate("/mydonations")}
                            className="px-8 bg-gray-100 text-gray-700 p-4 rounded-xl font-bold hover:bg-gray-200 transition-all"
                          >
                            Cancel
                          </button>
                        </div>
                      </form>
                    </div>
                  </div>
                ) : userRole === "Store" ? (
                  <div className="bg-amber-50 border border-amber-200 rounded-2xl p-8 text-center shadow-sm">
                    <div className="w-16 h-16 bg-amber-100 text-amber-600 rounded-full flex items-center justify-center mx-auto mb-4">
                      <FaLock className="text-2xl" />
                    </div>
                    <h2 className="text-2xl font-bold text-gray-800 mb-2">Store Account Restricted</h2>
                    <p className="text-gray-600 mb-6">
                      Only Customer accounts can pledge donations. If you'd like to donate, please use a customer account.
                    </p>
                    <button
                      onClick={() => navigate("/storeDashboard")}
                      className="bg-amber-600 text-white px-8 py-3 rounded-xl font-bold hover:bg-amber-700 transition"
                    >
                      Back to Dashboard
                    </button>
                  </div>
                ) : (
                  <div className="bg-white border-2 border-dashed border-gray-200 rounded-2xl p-12 text-center shadow-lg">
                    <div className="w-20 h-20 bg-purple-100 text-purple-600 rounded-full flex items-center justify-center mx-auto mb-6">
                      <FaLock className="text-3xl" />
                    </div>
                    <h2 className="text-2xl font-bold text-gray-800 mb-2">Want to donate your clothes?</h2>
                    <p className="text-gray-600 mb-8 max-w-md mx-auto">
                      Please login or create an account to start your donation journey and help build a sustainable future.
                    </p>
                    <div className="flex flex-col sm:flex-row gap-4 justify-center">
                      <Link
                        to="/login"
                        className="flex items-center justify-center gap-2 bg-purple-600 text-white px-8 py-3 rounded-xl font-bold hover:bg-purple-700 transition transform hover:-translate-y-1 shadow-md shadow-purple-200"
                      >
                        <FaSignInAlt /> Login
                      </Link>
                      <Link
                        to="/register"
                        className="flex items-center justify-center gap-2 bg-white text-purple-600 border-2 border-purple-600 px-8 py-3 rounded-xl font-bold hover:bg-purple-50 transition transform hover:-translate-y-1 shadow-sm"
                      >
                        <FaUserPlus /> Join RentFit
                      </Link>
                    </div>
                  </div>
                )}
              </div>
            </div>
          </main>
        </div>
      ) : (
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 w-full space-y-8">
          <div className="text-center">
            <h1 className="text-4xl md:text-5xl font-extrabold text-gray-900 mb-4">
              Give Your Clothes a <span className="text-purple-600">New Life</span>
            </h1>
