import React, { useState, useEffect } from "react";
import axiosInstance from "../services/axiosInstance";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import DashboardSidebar from '../Components/DashboardSidebar';
import { FaLock, FaUserShield, FaMapMarkerAlt, FaBell, FaSignOutAlt, FaTrashAlt, FaCheckCircle, FaExclamationTriangle } from "react-icons/fa";
import { useNavigate } from "react-router-dom";

const PrivacySecurity = () => {
    const navigate = useNavigate();
    const [isLoading, setIsLoading] = useState(false);
    const [isSaving, setIsSaving] = useState(false);
    const [alert, setAlert] = useState({ message: "", type: "" });
    const [showDeleteModal, setShowDeleteModal] = useState(false);

    // Password State
    const [passwordData, setPasswordData] = useState({
        old_password: "",
        new_password: "",
        confirm_password: ""
    });

    // Privacy Settings State
    const [privacySettings, setPrivacySettings] = useState({
        profile_visibility: true,
        location_sharing: true,
        recommendations_enabled: true
    });

    useEffect(() => {
        fetchSettings();
    }, []);

    const fetchSettings = async () => {
        try {
            setIsLoading(true);
            const response = await axiosInstance.get("user/profile/");
            const data = response.data?.data || response.data;
            setPrivacySettings({
                profile_visibility: data.profile_visibility ?? true,
                location_sharing: data.location_sharing ?? true,
                recommendations_enabled: data.recommendations_enabled ?? true
            });
        } catch (error) {
            console.error("Error fetching settings:", error);
        } finally {
            setIsLoading(false);
        }
    };

    const handlePasswordChange = async (e) => {
        e.preventDefault();
        if (passwordData.new_password !== passwordData.confirm_password) {
            setAlert({ message: "New passwords do not match", type: "error" });
            return;
        }

        setIsSaving(true);
        try {
            await axiosInstance.post("user/change-password/", passwordData);
            setAlert({ message: "Password updated successfully!", type: "success" });
            setPasswordData({ old_password: "", new_password: "", confirm_password: "" });
        } catch (error) {
            const errorMsg = error.response?.data?.error || "Failed to update password";
            setAlert({ message: errorMsg, type: "error" });
        } finally {
            setIsSaving(false);
        }
    };

    const handlePrivacyToggle = async (key) => {
        const updatedSettings = { ...privacySettings, [key]: !privacySettings[key] };
        setPrivacySettings(updatedSettings);

        try {
            await axiosInstance.put("user/privacy/", updatedSettings);
            // Subtle feedback could be added here
        } catch (error) {
            console.error("Error updating privacy:", error);
            // Rollback on error
            setPrivacySettings(privacySettings);
            setAlert({ message: "Failed to update privacy settings", type: "error" });
        }
    };

    const handleDeleteAccount = async () => {
        try {
            await axiosInstance.delete("user/delete-account/");
            localStorage.clear();
            navigate("/login");
        } catch (error) {
            setAlert({ message: "Failed to delete account", type: "error" });
            setShowDeleteModal(false);
        }
    };

    const handleLogoutAll = async () => {
        // Implement logout all if supported by backend, otherwise just local logout
        localStorage.clear();
        navigate("/login");
    };

    return (
        <div className="min-h-screen bg-gray-50">
            <Navbar />
            <div className="flex">
                <DashboardSidebar />
                <main className="flex-1 p-4 md:p-8">
                    <div className="max-w-4xl mx-auto">
                        <header className="mb-8">
                            <h1 className="text-3xl font-bold text-gray-900 mb-2">Privacy & Security</h1>
                            <p className="text-gray-500">Manage your account security and control your privacy preferences.</p>
                        </header>

                        {alert.message && (
                            <div className={`mb-6 p-4 rounded-2xl flex items-center gap-3 animate-slideDown ${alert.type === 'success' ? 'bg-green-50 text-green-700 border border-green-100' : 'bg-red-50 text-red-700 border border-red-100'}`}>
                                {alert.type === 'success' ? <FaCheckCircle /> : <FaExclamationTriangle />}
                                <span className="font-medium">{alert.message}</span>
                                <button onClick={() => setAlert({ message: "", type: "" })} className="ml-auto hover:opacity-70">&times;</button>
                            </div>
                        )}

                        <div className="grid grid-cols-1 lg:grid-cols-1 gap-8">
                            {/* Change Password Card */}
                            <section className="bg-white rounded-3xl p-8 shadow-sm border border-gray-100 transition-all hover:shadow-md">
                                <div className="flex items-center gap-3 mb-6">
                                    <div className="w-12 h-12 bg-purple-100 rounded-2xl flex items-center justify-center text-purple-600 shadow-sm shadow-purple-50">
                                        <FaLock size={20} />
                                    </div>
                                    <div>
                                        <h2 className="text-xl font-bold text-gray-900">Security Credentials</h2>
                                        <p className="text-sm text-gray-500">Update your account password regularly to stay safe.</p>
                                    </div>
                                </div>

                                <form onSubmit={handlePasswordChange} className="space-y-6">
                                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                                        <div className="space-y-2">
                                            <label className="text-sm font-semibold text-gray-700">Current Password</label>
                                            <input
                                                type="password"
                                                required
                                                className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl focus:ring-2 focus:ring-purple-500 focus:bg-white outline-none transition-all placeholder:text-gray-400"
                                                placeholder="ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó"
                                                value={passwordData.old_password}
                                                onChange={(e) => setPasswordData({ ...passwordData, old_password: e.target.value })}
                                            />
                                        </div>
                                        <div className="space-y-2">
                                            <label className="text-sm font-semibold text-gray-700">New Password</label>
                                            <input
                                                type="password"
                                                required
                                                className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl focus:ring-2 focus:ring-purple-500 focus:bg-white outline-none transition-all placeholder:text-gray-400"
                                                placeholder="ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó"
                                                value={passwordData.new_password}
                                                onChange={(e) => setPasswordData({ ...passwordData, new_password: e.target.value })}
                                            />
                                        </div>
                                        <div className="space-y-2">
                                            <label className="text-sm font-semibold text-gray-700">Confirm Password</label>
                                            <input
                                                type="password"
                                                required
                                                className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl focus:ring-2 focus:ring-purple-500 focus:bg-white outline-none transition-all placeholder:text-gray-400"
                                                placeholder="ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó"
                                                value={passwordData.confirm_password}
                                                onChange={(e) => setPasswordData({ ...passwordData, confirm_password: e.target.value })}
                                            />
                                        </div>
                                    </div>
                                    <div className="flex justify-end pt-2">
                                        <button
                                            type="submit"
                                            disabled={isSaving}
                                            className="px-8 py-3 bg-purple-600 text-white font-bold rounded-2xl hover:bg-purple-700 transition-all shadow-lg shadow-purple-200 disabled:opacity-50"
                                        >
                                            {isSaving ? "Updating..." : "Update Password"}
                                        </button>
                                    </div>
                                </form>
                            </section>

                            {/* Privacy Controls Card */}
                            <section className="bg-white rounded-3xl p-8 shadow-sm border border-gray-100 transition-all hover:shadow-md">
                                <div className="flex items-center gap-3 mb-8">
                                    <div className="w-12 h-12 bg-blue-100 rounded-2xl flex items-center justify-center text-blue-600 shadow-sm shadow-blue-50">
                                        <FaUserShield size={20} />
                                    </div>
                                    <div>
                                        <h2 className="text-xl font-bold text-gray-900">Privacy Preferences</h2>
                                        <p className="text-sm text-gray-500">Control how your information is shared and used.</p>
                                    </div>
                                </div>

                                <div className="space-y-8">
                                    <div className="flex items-center justify-between group">
                                        <div className="flex items-center gap-4">
                                            <div className="w-10 h-10 bg-gray-50 rounded-xl flex items-center justify-center text-gray-400 group-hover:text-blue-500 transition-colors">
                                                <FaUserShield />
                                            </div>
                                            <div>
                                                <h3 className="font-bold text-gray-800">Profile Visibility</h3>
                                                <p className="text-xs text-gray-500">Make your profile discoverable to other users and stores.</p>
                                            </div>
                                        </div>
                                        <button
                                            onClick={() => handlePrivacyToggle('profile_visibility')}
                                            className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors duration-300 focus:outline-none ${privacySettings.profile_visibility ? 'bg-purple-600' : 'bg-gray-200'}`}
                                        >
                                            <span className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform duration-300 ${privacySettings.profile_visibility ? 'translate-x-6' : 'translate-x-1'}`} />
                                        </button>
                                    </div>

                                    <div className="flex items-center justify-between group">
                                        <div className="flex items-center gap-4">
                                            <div className="w-10 h-10 bg-gray-50 rounded-xl flex items-center justify-center text-gray-400 group-hover:text-purple-500 transition-colors">
                                                <FaMapMarkerAlt />
                                            </div>
                                            <div>
                                                <h3 className="font-bold text-gray-800">Location Sharing</h3>
                                                <p className="text-xs text-gray-500">Allow location access to show stores near you in the "Nearby Shops" map.</p>
                                            </div>
                                        </div>
                                        <button
                                            onClick={() => handlePrivacyToggle('location_sharing')}
                                            className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors duration-300 focus:outline-none ${privacySettings.location_sharing ? 'bg-purple-600' : 'bg-gray-200'}`}
                                        >
                                            <span className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform duration-300 ${privacySettings.location_sharing ? 'translate-x-6' : 'translate-x-1'}`} />
                                        </button>
                                    </div>

                                    <div className="flex items-center justify-between group">
                                        <div className="flex items-center gap-4">
                                            <div className="w-10 h-10 bg-gray-50 rounded-xl flex items-center justify-center text-gray-400 group-hover:text-amber-500 transition-colors">
                                                <FaBell />
                                            </div>
                                            <div>
                                                <h3 className="font-bold text-gray-800">Store Recommendations</h3>
                                                <p className="text-xs text-gray-500">Receive personalized clothing and store recommendations based on your activity.</p>
                                            </div>
                                        </div>
                                        <button
                                            onClick={() => handlePrivacyToggle('recommendations_enabled')}
                                            className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors duration-300 focus:outline-none ${privacySettings.recommendations_enabled ? 'bg-purple-600' : 'bg-gray-200'}`}
                                        >
                                            <span className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform duration-300 ${privacySettings.recommendations_enabled ? 'translate-x-6' : 'translate-x-1'}`} />
                                        </button>
                                    </div>
                                </div>
                            </section>

                            {/* Account Actions Section */}
                            <section className="bg-red-50/30 rounded-3xl p-8 border border-red-50 transition-all hover:bg-red-50/50">
                                <div className="flex items-center gap-3 mb-6 font-bold text-red-600">
                                    <FaExclamationTriangle />
                                    <h2>Advanced Account Actions</h2>
                                </div>
                                <div className="flex flex-wrap gap-4">
                                    <button
                                        onClick={handleLogoutAll}
                                        className="flex items-center gap-2 px-6 py-3 bg-white border border-red-100 text-red-600 font-bold rounded-2xl hover:bg-red-50 transition-all shadow-sm"
                                    >
                                        <FaSignOutAlt /> Logout from all devices
                                    </button>
                                    <button
                                        onClick={() => setShowDeleteModal(true)}
                                        className="flex items-center gap-2 px-6 py-3 bg-red-600 text-white font-bold rounded-2xl hover:bg-red-700 transition-all shadow-lg shadow-red-100"
                                    >
                                        <FaTrashAlt /> Delete Account
                                    </button>
                                </div>
                            </section>
                        </div>
                    </div>
                </main>
            </div>
            <Footer />

            {/* Delete Modal */}
            {showDeleteModal && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 animate-fadeIn">
                    <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setShowDeleteModal(false)}></div>
                    <div className="relative bg-white rounded-[2rem] p-8 max-w-md w-full shadow-2xl animate-scaleIn">
                        <div className="flex flex-col items-center text-center">
                            <div className="w-16 h-16 bg-red-100 rounded-2xl flex items-center justify-center text-red-600 mb-6 drop-shadow-sm">
                                <FaExclamationTriangle size={28} />
                            </div>
                            <h3 className="text-2xl font-black text-gray-900 mb-2">Are you sure?</h3>
                            <p className="text-gray-500 mb-8 leading-relaxed">
                                This action is permanent and cannot be undone. All your data, rentals, and profile information will be deleted.
                            </p>
                            <div className="flex w-full gap-4">
                                <button
                                    onClick={() => setShowDeleteModal(false)}
                                    className="flex-1 py-4 bg-gray-100 text-gray-700 font-bold rounded-2xl hover:bg-gray-200 transition-all"
                                >
                                    Cancel
                                </button>
                                <button
                                    onClick={handleDeleteAccount}
                                    className="flex-1 py-4 bg-red-600 text-white font-bold rounded-2xl hover:bg-red-700 transition-all shadow-lg shadow-red-200"
                                >
                                    Delete
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            <style dangerouslySetInnerHTML={{
                __html: `
                @keyframes slideDown {
                    from { transform: translateY(-20px); opacity: 0; }
                    to { transform: translateY(0); opacity: 1; }
                }
                @keyframes fadeIn {
                    from { opacity: 0; }
                    to { opacity: 1; }
                }
                @keyframes scaleIn {
                    from { transform: scale(0.95); opacity: 0; }
                    to { transform: scale(1); opacity: 1; }
                }
                .animate-slideDown { animation: slideDown 0.4s ease-out; }
                .animate-fadeIn { animation: fadeIn 0.3s ease-out; }
                .animate-scaleIn { animation: scaleIn 0.3s cubic-bezier(0.34, 1.56, 0.64, 1); }
            `}} />
        </div>
    );
};

export default PrivacySecurity;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axiosInstance from '../services/axiosInstance';
import rentalAxiosInstance from '../services/rentalAxiosInstance';
import Navbar from '../Components/Navbar';
import Footer from '../Components/Footer';
import StoreSidebar from '../Components/StoreSidebar';
import { FaCheck, FaTimes, FaUser, FaTshirt, FaCalendarAlt, FaHistory, FaExclamationTriangle, FaInfoCircle, FaDollarSign } from 'react-icons/fa';

const RentManagement = () => {
    const navigate = useNavigate();
    const [rentals, setRentals] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [alert, setAlert] = useState({ message: '', type: '' });
    const [selectedRental, setSelectedRental] = useState(null);
    const [isModalOpen, setIsModalOpen] = useState(false);

    useEffect(() => {
        const role = localStorage.getItem('role');
        const token = localStorage.getItem('access_token');

        if (!token || role !== 'Store') {
            navigate('/login');
            return;
        }

        fetchRentals();
    }, [navigate]);

    const fetchRentals = async () => {
        try {
            setIsLoading(true);
            const response = await rentalAxiosInstance.get('rentals/store/');
            console.log('Rental Requests Response:', response.data);
            setRentals(response.data);
        } catch (error) {
            console.error('Error fetching rentals:', error);
            showAlert('Failed to load rental requests.', 'error');
        } finally {
            setIsLoading(false);
        }
    };

    const handleAction = async (id, action) => {
        try {
            await rentalAxiosInstance.patch(`rentals/${id}/${action}/`);
            showAlert(`Rental request ${action}ed successfully!`, 'success');
            fetchRentals();
        } catch (error) {
            console.error(`Error during rental ${action}:`, error);
            showAlert(`Failed to ${action} rental request.`, 'error');
        }
    };

    const showAlert = (message, type) => {
        setAlert({ message, type });
        setTimeout(() => setAlert({ message: '', type: '' }), 3000);
    };

    const getStatusStyle = (status) => {
        switch (status) {
            case 'pending': return 'bg-yellow-100 text-yellow-800 border-yellow-200';
            case 'approved': return 'bg-green-100 text-green-800 border-green-200';
            case 'rejected': return 'bg-red-100 text-red-800 border-red-200';
            case 'rented': return 'bg-blue-100 text-blue-800 border-blue-200';
            case 'returned_pending': return 'bg-purple-100 text-purple-800 border-purple-200';
            case 'returned_confirmed': return 'bg-gray-100 text-gray-800 border-gray-200';
            default: return 'bg-gray-50 text-gray-600 border-gray-100';
        }
    };

    return (
        <div className="min-h-screen bg-gray-50 flex flex-col uppercase-none">
            <Navbar />

            <div className="flex flex-1">
                <StoreSidebar />

                <div className="flex-1 overflow-auto p-8">
                    <div className="max-w-7xl mx-auto">
                        <div className="flex items-center justify-between mb-8">
                            <div>
                                <h1 className="text-3xl font-extrabold text-gray-900 tracking-tight">Rental Management</h1>
                                <p className="text-gray-500 mt-2">Manage incoming rental invitations and track active bookings.</p>
                            </div>
                            <button
                                onClick={fetchRentals}
                                className="flex items-center gap-2 px-4 py-2 bg-white border border-gray-300 rounded-lg text-sm font-medium text-gray-700 hover:bg-gray-50 transition-all shadow-sm"
                            >
                                <FaHistory className={isLoading ? 'animate-spin' : ''} />
                                Refresh List
                            </button>
                        </div>

                        {alert.message && (
                            <div className={`mb-6 p-4 rounded-xl border flex items-center justify-between animate-in fade-in slide-in-from-top-4 ${alert.type === 'success' ? 'bg-green-50 border-green-200 text-green-800' : 'bg-red-50 border-red-200 text-red-800'
                                }`}>
                                <span className="font-semibold">{alert.message}</span>
                                <button onClick={() => setAlert({ message: '', type: '' })} className="hover:opacity-70">
                                    <FaTimes />
                                </button>
                            </div>
                        )}

                        <div className="bg-white rounded-2xl shadow-xl border border-gray-100 overflow-hidden">
                            <div className="overflow-x-auto">
                                <table className="w-full text-left border-collapse">
                                    <thead>
                                        <tr className="bg-purple-600">
                                            <th className="px-6 py-4 text-sm font-bold text-white uppercase tracking-wider">Customer</th>
                                            <th className="px-6 py-4 text-sm font-bold text-white uppercase tracking-wider">Item Details</th>
                                            <th className="px-6 py-4 text-sm font-bold text-white uppercase tracking-wider">Rental Period</th>
                                            <th className="px-6 py-4 text-sm font-bold text-white uppercase tracking-wider text-center">Payment</th>
                                            <th className="px-6 py-4 text-sm font-bold text-white uppercase tracking-wider text-center">Status</th>
                                            <th className="px-6 py-4 text-sm font-bold text-white uppercase tracking-wider text-right">Actions</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-gray-100">
                                        {isLoading ? (
                                            <tr>
                                                <td colSpan="6" className="px-6 py-12 text-center">
                                                    <div className="w-10 h-10 border-4 border-purple-500 border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
                                                    <p className="text-gray-500 font-medium">Fetching your rentals...</p>
                                                </td>
                                            </tr>
                                        ) : rentals.length === 0 ? (
                                            <tr>
                                                <td colSpan="6" className="px-6 py-12 text-center">
                                                    <div className="bg-gray-50 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
                                                        <FaTshirt className="text-gray-300 text-2xl" />
                                                    </div>
                                                    <h3 className="text-lg font-bold text-gray-900">No requests found</h3>
                                                    <p className="text-gray-500">You don't have any rental requests at the moment.</p>
                                                </td>
                                            </tr>
                                        ) : (
                                            rentals.map((rental) => (
                                                <tr key={rental.id} className="hover:bg-gray-50/50 transition-colors border-b border-gray-100 last:border-0 uppercase-none">
                                                    {/* Customer Column */}
                                                    <td className="px-6 py-4">
                                                        <div className="flex items-center gap-3">
                                                            <div className="w-12 h-12 rounded-full bg-purple-100 flex items-center justify-center text-purple-600 border-2 border-white shadow-sm overflow-hidden flex-shrink-0">
                                                                {rental.customer_profile_image ? (
                                                                    <img src={rental.customer_profile_image} alt={rental.customer_name} className="w-full h-full object-cover" />
                                                                ) : (
                                                                    <FaUser className="text-sm" />
                                                                )}
                                                            </div>
                                                            <div className="min-w-0">
                                                                <p className="font-bold text-gray-900 text-sm truncate">{rental.customer_name || 'Customer'}</p>
                                                                <p className="text-[10px] text-gray-400 truncate">{rental.customer_email}</p>
                                                            </div>
                                                        </div>
                                                    </td>

                                                    {/* Item Details Column */}
                                                    <td className="px-6 py-4">
                                                        <div className="flex items-center gap-3">
                                                            <div className="w-11 h-11 rounded-lg bg-gray-50 flex items-center justify-center overflow-hidden border border-gray-100 flex-shrink-0">
                                                                {rental.clothing_image ? (
                                                                    <img src={rental.clothing_image} alt={rental.clothing_name} className="w-full h-full object-cover" />
                                                                ) : (
                                                                    <FaTshirt className="text-gray-300" />
                                                                )}
                                                            </div>
                                                            <div className="min-w-0">
                                                                <p className="font-bold text-gray-800 text-sm truncate">{rental.clothing_name}</p>
                                                                <div className="mt-0.5">
                                                                    <span className="px-1.5 py-0.5 bg-purple-50 text-purple-600 rounded text-[9px] font-black uppercase tracking-widest border border-purple-100">
                                                                        Size: {rental.selected_size || 'N/A'}
                                                                    </span>
                                                                </div>
                                                            </div>
                                                        </div>
                                                    </td>

                                                    {/* Rental Period Column */}
                                                    <td className="px-6 py-4">
                                                        <div className="flex flex-col">
                                                            <div className="flex items-center gap-1.5 text-xs font-bold text-gray-600">
                                                                <FaCalendarAlt className="text-purple-400 text-[10px]" />
                                                                <span>{rental.rent_start_date}</span>
                                                            </div>
                                                            <div className="flex items-center gap-1.5 text-xs font-bold text-gray-600">
                                                                <div className="w-[10px] h-[1px] bg-gray-300 ml-[1px]"></div>
                                                                <span>{rental.rent_end_date}</span>
                                                            </div>
                                                            <p className="text-[11px] font-black text-green-600 mt-1 uppercase tracking-tight">Rs. {rental.total_price}</p>
                                                        </div>
                                                    </td>

                                                    {/* Payment Status Column */}
                                                    <td className="px-6 py-4 text-center">
                                                        <div className="inline-flex flex-col items-center gap-1">
                                                            <span className={`px-2.5 py-1 rounded-full text-[9px] font-black border uppercase tracking-widest ${rental.payment_status === 'paid'
                                                                ? 'bg-green-50 text-green-700 border-green-200'
                                                                : 'bg-amber-50 text-amber-700 border-amber-200'
                                                                }`}>
                                                                {rental.payment_status || 'PENDING'}
                                                            </span>
                                                            {rental.payment_status === 'paid' && (
                                                                <button
                                                                    onClick={() => {
                                                                        setSelectedRental(rental);
                                                                        setIsModalOpen(true);
                                                                    }}
                                                                    className="text-purple-500 hover:text-purple-700 font-bold text-[9px] uppercase tracking-tighter"
                                                                >
                                                                    Details
                                                                </button>
                                                            )}
                                                        </div>
                                                    </td>

                                                    {/* Status Column */}
                                                    <td className="px-6 py-4 text-center">
                                                        <div className="flex flex-col items-center gap-1.5">
                                                            <span className={`px-2.5 py-1 rounded-full text-[9px] font-black border uppercase tracking-widest ${getStatusStyle(rental.status)}`}>
                                                                {rental.status.replace('_', ' ')}
                                                            </span>
                                                            {rental.has_damage_report && (
                                                                <span
                                                                    onClick={() => navigate('/damaged-items')}
                                                                    className="flex items-center gap-1 px-2 py-0.5 rounded bg-red-50 text-red-600 border border-red-100 cursor-pointer hover:bg-red-100 transition-colors text-[8px] font-black uppercase tracking-tighter"
                                                                >
                                                                    <FaExclamationTriangle />
                                                                    Damaged
                                                                </span>
                                                            )}
                                                        </div>
                                                    </td>

                                                    {/* Actions Column */}
                                                    <td className="px-6 py-4 text-right">
                                                        {rental.status === 'pending' ? (
                                                            <div className="flex justify-end gap-2">
                                                                <button
                                                                    onClick={() => handleAction(rental.id, 'approve')}
                                                                    className="h-8 w-8 bg-green-500 text-white rounded-lg hover:bg-green-600 transition-all flex items-center justify-center shadow-sm"
                                                                    title="Approve"
                                                                >
                                                                    <FaCheck />
                                                                </button>
                                                                <button
                                                                    onClick={() => handleAction(rental.id, 'reject')}
                                                                    className="h-8 w-8 bg-red-500 text-white rounded-lg hover:bg-red-600 transition-all flex items-center justify-center shadow-sm"
                                                                    title="Reject"
                                                                >
                                                                    <FaTimes />
                                                                </button>
                                                            </div>
                                                        ) : rental.status === 'returned_pending' ? (
                                                            <button
                                                                onClick={() => handleAction(rental.id, 'confirm-return')}
                                                                className="px-3 py-1.5 bg-purple-600 text-white rounded-lg hover:bg-purple-700 transition-all font-bold text-[10px] uppercase tracking-wider shadow-sm"
                                                            >
                                                                Confirm Return
                                                            </button>
                                                        ) : (
                                                            <span className="text-[10px] font-bold text-gray-300 uppercase italic">No Actions</span>
                                                        )}
                                                    </td>
                                                </tr>
                                            ))
                                        )}
                                    </tbody>
                                </table>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* Payment Details Modal */}
            {isModalOpen && selectedRental && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-in fade-in duration-200">
                    <div className="bg-white rounded-3xl shadow-2xl w-full max-w-lg overflow-hidden animate-in zoom-in-95 duration-200">
                        <div className="bg-purple-600 p-6 flex justify-between items-center text-white">
                            <h3 className="text-xl font-bold flex items-center gap-2">
                                <FaDollarSign /> Payment Details
                            </h3>
                            <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-white/10 rounded-full transition-colors">
                                <FaTimes />
                            </button>
                        </div>
                        <div className="p-8">
                            <div className="space-y-6">
                                <div className="flex justify-between items-start border-b border-gray-100 pb-4">
                                    <div>
                                        <p className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-1">Customer</p>
                                        <p className="text-lg font-bold text-gray-900">{selectedRental.customer_name}</p>
                                        <p className="text-sm text-gray-500">{selectedRental.customer_email}</p>
                                    </div>
                                    <div className="text-right">
                                        <p className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-1">Amount Paid</p>
                                        <p className="text-2xl font-black text-green-600">Rs. {selectedRental.payment_details?.amount}</p>
                                    </div>
                                </div>

                                <div className="grid grid-cols-2 gap-6">
                                    <div>
                                        <p className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-1">Item Details</p>
                                        <p className="text-sm font-bold text-gray-800">{selectedRental.clothing_name}</p>
                                    </div>
                                    <div>
                                        <p className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-1">Rental Period</p>
                                        <p className="text-sm font-bold text-gray-800">{selectedRental.rent_start_date}</p>
                                        <p className="text-sm font-bold text-gray-800">{selectedRental.rent_end_date}</p>
                                    </div>
                                </div>

                                <div className="bg-gray-50 rounded-2xl p-5 border border-gray-100">
                                    <div className="flex justify-between items-center mb-4">
                                        <p className="text-xs font-bold text-gray-500 uppercase tracking-widest">Transaction Info</p>
                                        <span className="px-2 py-0.5 bg-green-100 text-green-700 text-[10px] font-black uppercase rounded border border-green-200">
                                            Verified
                                        </span>
                                    </div>
                                    <div className="space-y-3">
                                        <div className="flex justify-between text-sm">
                                            <span className="text-gray-500">Transaction ID</span>
                                            <span className="font-mono font-bold text-gray-800">{selectedRental.payment_details?.transaction_id}</span>
                                        </div>
                                        <div className="flex justify-between text-sm">
                                            <span className="text-gray-500">Payment Date</span>
                                            <span className="font-bold text-gray-800">{selectedRental.payment_details?.date}</span>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                        <div className="p-4 bg-gray-50 border-t border-gray-100 flex justify-end">
                            <button
                                onClick={() => setIsModalOpen(false)}
                                className="px-6 py-2 bg-white border border-gray-200 rounded-xl text-sm font-bold text-gray-700 hover:bg-gray-100 transition-all shadow-sm"
                            >
                                Close
                            </button>
                        </div>
                    </div>
                </div>
            )}

            <Footer />
        </div>
    );
};

export default RentManagement;

import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axiosInstance from "../services/axiosInstance";
import donationAxios from "../services/donationAxios";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import StoreSidebar from "../Components/StoreSidebar";
import {
  FaBell, FaHome, FaBox, FaHeart, FaMapMarkerAlt, FaQuestionCircle,
  FaFileAlt, FaChevronRight, FaCheckCircle, FaClock, FaExclamationCircle,
  FaStore, FaTshirt, FaSignOutAlt, FaCog, FaDollarSign, FaCalendarAlt, FaUser, FaTshirt as FaShirt, FaCheck, FaTimes, FaInfoCircle, FaExclamationTriangle
} from 'react-icons/fa';

const InfoCard = ({ icon: Icon, label, value, color = "gray", trend }) => (
  <div className="bg-white rounded-lg p-6 shadow-sm border border-gray-100 hover:shadow-md transition-shadow">
    <div className="flex items-center justify-between mb-2">
      <span className="text-sm text-gray-600 font-medium">{label}</span>
      <div className={`w-10 h-10 rounded-full bg-${color}-50 flex items-center justify-center`}>
        <Icon className={`text-${color}-500 text-lg`} />
      </div>
    </div>
    <div className="text-3xl font-bold text-gray-800 mb-1">{value}</div>
    {trend && <div className="text-xs text-gray-500">{trend}</div>}
  </div>
);

const ActivityItem = ({ icon: Icon, color, title, desc, time }) => (
  <div className="flex items-start gap-3 p-3 rounded-lg hover:bg-gray-50 transition-colors">
    <div className={`w-8 h-8 rounded-full ${color} flex items-center justify-center flex-shrink-0 mt-1`}>
      <Icon className="text-sm" />
    </div>
    <div className="flex-1 min-w-0">
      <p className="text-sm font-medium text-gray-800">{title}</p>
      <p className="text-xs text-gray-500 mt-0.5">{desc}</p>
      <p className="text-xs text-gray-400 mt-1">{time}</p>
    </div>
  </div>
);

const QuickActionButton = ({ label, color, onClick }) => (
  <button
    onClick={onClick}
    className={`w-full py-3 px-4 bg-${color}-500 hover:bg-${color}-600 text-white rounded-lg font-medium transition-colors flex items-center justify-between`}
  >
    <span>{label}</span>
    <FaChevronRight className="text-sm" />
  </button>
);

const StoreDashboard = () => {
  const navigate = useNavigate();
  const [isLoading, setIsLoading] = useState(true);

  const [storeInfo, setStoreInfo] = useState({
    storeName: "",
    ownerName: "",
    email: "",
    phone: "",
    location: "",
    description: "",
    storeImage: "",
  });

  const [recentActivities, setRecentActivities] = useState([]);

  const [stats, setStats] = useState({
    approvedDonations: 0,
    pendingDonations: 0,
    rejectedDonations: 0,
    collectedDonations: 0,
    availableClothes: 0,
    unavailableClothes: 0,
    totalClothes: 0,
    totalEarnings: 0,
  });

  const [recentTransactions, setRecentTransactions] = useState([]);

  useEffect(() => {
    fetchDashboardData();
    fetchDonationsData();
    fetchClothingItemsData();
    fetchEarningsData();
  }, []);

  const fetchEarningsData = async () => {
    try {
      const response = await axiosInstance.get("accounts/dashboard/store/stats/");
      const data = response.data.data;
      setStats(prev => ({
        ...prev,
        totalEarnings: data.total_earnings,
      }));
      setRecentTransactions(data.recent_transactions || []);
    } catch (error) {
      console.error("Error fetching earnings data:", error);
    }
  };

  const fetchDashboardData = async () => {
    try {
      setIsLoading(true);

      const token = localStorage.getItem("access_token");
      if (!token) {
        navigate('/login');
        return;
      }

      const response = await axiosInstance.get("accounts/stores/profile/");
      const profileData = response.data?.data || response.data;

      if (profileData) {
        const storeName = profileData.store_name || "My Store";
        const ownerName = profileData.owner_name || profileData.name || "Store Owner";
        const location = profileData.store_address || "";
        const description = profileData.store_description || "No description available";
        const storeImage = profileData.store_logo_url || profileData.store_logo || "";

        setStoreInfo({
          storeName,
          ownerName,
          email: profileData.email || "",
          phone: profileData.phone_number || profileData.phone || "",
          location,
          description,
          storeImage,
        });
      }

    } catch (error) {
      console.error("Error fetching data:", error);

      if (error.response?.status === 401) {
        localStorage.clear();
        navigate('/login');
      }
    } finally {
      setIsLoading(false);
    }
  };

  const fetchDonationsData = async () => {
    try {
      const response = await donationAxios.get("donations/store/");
      const donations = response.data || [];

      const approved = donations.filter(d => d.donation_status === 'Approved').length;
      const pending = donations.filter(d => d.donation_status === 'Pending').length;
      const rejected = donations.filter(d => d.donation_status === 'Rejected').length;
      const collected = donations.filter(d => d.donation_status === 'Collected').length;

      setStats(prev => ({
        ...prev,
        approvedDonations: approved,
        pendingDonations: pending,
        rejectedDonations: rejected,
        collectedDonations: collected,
      }));

      const recentDonations = donations
        .filter(d => d.donation_status === 'Approved' || d.donation_status === 'Collected')
        .slice(0, 3)
        .map(d => ({
          icon: FaHeart,
          color: 'bg-blue-100 text-blue-600',
          title: `Donation ${d.donation_status}`,
          desc: `${d.item_name || 'Item'} from ${d.customer_name || 'Donor'}`,
          time: formatTime(d.created_at),
          type: 'donation'
        }));

      setRecentActivities(prev => [...prev, ...recentDonations]);
    } catch (error) {
      console.error("Error fetching donations:", error);
    }
  };

  const fetchClothingItemsData = async () => {
    try {
      const response = await axiosInstance.get("accounts/clothing/my/");
      let items = [];
      if (Array.isArray(response.data)) {
        items = response.data;
      } else if (response.data?.results) {
        items = response.data.results;
      } else if (response.data?.data) {
        items = response.data.data;
      }

      const available = items.filter(item =>
        item.clothing_status?.toLowerCase() === 'available'
      ).length;
      const unavailable = items.filter(item =>
        item.clothing_status?.toLowerCase() === 'unavailable'
      ).length;

      setStats(prev => ({
        ...prev,
        availableClothes: available,
        unavailableClothes: unavailable,
        totalClothes: items.length,
      }));

      const recentItems = items
        .slice(0, 3)
        .map(item => ({
          icon: FaTshirt,
          color: 'bg-purple-100 text-purple-600',
          title: `${item.item_name || 'Item'} - ${item.clothing_status || 'Listed'}`,
          desc: `${item.category || 'Category'} - Size ${item.size || 'N/A'}`,
          time: formatTime(item.created_at),
          type: 'rental'
        }));

      setRecentActivities(prev => [...prev, ...recentItems]);
    } catch (error) {
      console.error("Error fetching clothing items:", error);
    }
  };

  const formatTime = (timestamp) => {
    if (!timestamp) return 'Recently';
    const date = new Date(timestamp);
    const now = new Date();
    const diffMs = now - date;
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMs / 3600000);
    const diffDays = Math.floor(diffMs / 86400000);
    if (diffMins < 60) return `${diffMins} mins ago`;
    if (diffHours < 24) return `${diffHours} hours ago`;
    if (diffDays < 7) return `${diffDays} days ago`;
    return date.toLocaleDateString();
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-gray-50 flex flex-col">
        <Navbar />
        <div className="flex-1 flex justify-center items-center">
          <div className="text-center">
            <div className="w-12 h-12 border-4 border-purple-500 border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
            <p className="text-gray-600">Loading dashboard...</p>
          </div>
        </div>
        <Footer />
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col bg-gray-50">
      <Navbar />

      <div className="flex flex-1">
        <StoreSidebar />

        {/* Main Content */}
        <div className="flex-1 overflow-auto">
          {/* Header */}
          <div className="bg-white border-b border-gray-200">
            <div className="px-8 py-5 flex items-center justify-between">
              <div className="flex-1">
                <h2 className="text-2xl font-bold text-gray-800">{storeInfo.storeName || "Store Dashboard"}</h2>
                <p className="text-sm text-gray-500 mt-1">
                  {storeInfo.description || "Monitor and manage rental operations"}
                </p>
              </div>
              <div className="flex items-center gap-4">
                <div className="flex items-center gap-3">
                  <div className="relative w-10 h-10 rounded-full overflow-hidden bg-gray-200 group cursor-pointer">
                    {storeInfo.storeImage ? (
                      <img src={storeInfo.storeImage} alt="Store Logo" className="w-full h-full object-cover" />
                    ) : (
                      <div className="w-full h-full flex items-center justify-center text-gray-500 text-sm font-bold">
                        {storeInfo.ownerName?.charAt(0)?.toUpperCase() || 'S'}
                      </div>
                    )}
                  </div>
                  <div>
                    <p className="text-sm font-medium text-gray-800">{storeInfo.ownerName || "Store Owner"}</p>
                    <p className="text-xs text-gray-500">Sub-Admin</p>
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* Dashboard Content */}
          <div className="p-8">
            {/* Metrics Grid */}
            <div className="grid grid-cols-1 lg:grid-cols-4 gap-6 mb-8">
              <InfoCard icon={FaTshirt} label="Total Listings" value={stats.totalClothes} color="purple" trend={`${stats.availableClothes} available`} />
              <InfoCard icon={FaBox} label="Currently Rented" value={stats.unavailableClothes} color="orange" trend={`${stats.totalClothes - stats.unavailableClothes} ready to rent`} />
              <InfoCard icon={FaHeart} label="Total Donations" value={stats.approvedDonations + stats.collectedDonations} color="blue" trend={`${stats.collectedDonations} collected`} />
              <div className="bg-white rounded-lg p-6 shadow-sm border border-gray-100 flex flex-col justify-center">
                <div className="flex items-center justify-between mb-2">
                  <span className="text-sm text-gray-600 font-medium">Total Earnings</span>
                  <div className="w-10 h-10 rounded-full bg-green-50 flex items-center justify-center">
                    <FaDollarSign className="text-green-500 text-lg" />
                  </div>
                </div>
                <div className="text-3xl font-bold text-gray-800 mb-1">Rs. {stats.totalEarnings}</div>
                <div className="text-xs text-gray-500">Verified revenue</div>
              </div>
            </div>


            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-8">
              <div className="bg-white rounded-lg p-6 shadow-sm border border-gray-100">
                <h3 className="text-sm font-semibold text-gray-700 mb-4 flex items-center gap-2"><FaTshirt className="text-purple-500" />Clothing Breakdown</h3>
                <div className="space-y-3">
                  <div className="flex justify-between items-center"><span className="text-sm text-gray-600">Available</span><span className="text-lg font-bold text-green-600">{stats.availableClothes}</span></div>
                  <div className="w-full bg-gray-100 rounded-full h-2"><div className="bg-green-500 h-2 rounded-full" style={{ width: `${stats.totalClothes > 0 ? (stats.availableClothes / stats.totalClothes) * 100 : 0}%` }}></div></div>
                  <div className="flex justify-between items-center"><span className="text-sm text-gray-600">Rented</span><span className="text-lg font-bold text-orange-600">{stats.unavailableClothes}</span></div>
                  <div className="w-full bg-gray-100 rounded-full h-2"><div className="bg-orange-500 h-2 rounded-full" style={{ width: `${stats.totalClothes > 0 ? (stats.unavailableClothes / stats.totalClothes) * 100 : 0}%` }}></div></div>
                </div>
              </div>

              <div className="bg-white rounded-lg p-6 shadow-sm border border-gray-100">
                <h3 className="text-sm font-semibold text-gray-700 mb-4 flex items-center gap-2"><FaHeart className="text-blue-500" />Donations status</h3>
                <div className="space-y-3 font-semibold text-sm">
                  <div className="flex justify-between"><span>Approved</span><span className="text-green-600">{stats.approvedDonations}</span></div>
                  <div className="flex justify-between"><span>Collected</span><span className="text-blue-600">{stats.collectedDonations}</span></div>
                  <div className="flex justify-between"><span>Pending</span><span className="text-yellow-600">{stats.pendingDonations}</span></div>
                  <div className="flex justify-between"><span>Rejected</span><span className="text-red-600">{stats.rejectedDonations}</span></div>
                </div>
              </div>

              <div className="bg-white rounded-lg p-6 shadow-sm border border-gray-100">
                <h3 className="text-sm font-semibold text-gray-700 mb-4 flex items-center gap-2"><FaCheckCircle className="text-green-500" />Summary</h3>
                <div className="space-y-3 text-sm">
                  <div className="flex justify-between"><span>Total Items</span><span className="font-bold">{stats.totalClothes}</span></div>
                  <div className="flex justify-between"><span>Utilization</span><span className="font-bold text-purple-600">{stats.totalClothes > 0 ? Math.round((stats.unavailableClothes / stats.totalClothes) * 100) : 0}%</span></div>
                </div>
              </div>
            </div>

            {/* Bottom Section */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
              {/* Donation Status Chart */}
              <div className="bg-white rounded-lg p-6 shadow-sm border border-gray-100">
                <h3 className="text-lg font-semibold text-gray-800 mb-6">Donation Status</h3>
                <div className="relative w-48 h-48 mx-auto mb-6">
                  <svg viewBox="0 0 100 100" className="transform -rotate-90">
                    <circle cx="50" cy="50" r="35" fill="none" stroke="#e5e7eb" strokeWidth="10" />
                    {(() => {
                      const total = Math.max(stats.approvedDonations + stats.pendingDonations + stats.rejectedDonations + stats.collectedDonations, 1);
                      const circumference = 2 * Math.PI * 35;
                      const approvedPercent = stats.approvedDonations / total;
                      const collectedPercent = stats.collectedDonations / total;
                      const pendingPercent = stats.pendingDonations / total;

                      return (
                        <>
                          <circle
                            cx="50"
                            cy="50"
                            r="35"
                            fill="none"
                            stroke="#10b981"
                            strokeWidth="10"
                            strokeDasharray={circumference}
                            strokeDashoffset={circumference - (circumference * approvedPercent)}
                            strokeLinecap="round"
                          />
                          <circle
                            cx="50"
                            cy="50"
                            r="35"
                            fill="none"
                            stroke="#3b82f6"
                            strokeWidth="10"
                            strokeDasharray={circumference}
                            strokeDashoffset={circumference - (circumference * (approvedPercent + collectedPercent))}
                            strokeLinecap="round"
                          />
                          <circle
                            cx="50"
                            cy="50"
                            r="35"
                            fill="none"
                            stroke="#f59e0b"
                            strokeWidth="10"
                            strokeDasharray={circumference}
                            strokeDashoffset={circumference - (circumference * (approvedPercent + collectedPercent + pendingPercent))}
                            strokeLinecap="round"
                          />
                        </>
                      );
                    })()}
                  </svg>
                  <div className="absolute inset-0 flex items-center justify-center text-center">
                    <div>
                      <div className="text-3xl font-bold text-gray-800">
                        {stats.approvedDonations + stats.collectedDonations + stats.pendingDonations + stats.rejectedDonations}
                      </div>
                      <div className="text-xs text-gray-500 mt-1">Total Donations</div>
                    </div>
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-2 text-xs">
                  <div className="flex items-center gap-2">
                    <div className="w-3 h-3 rounded-full bg-green-500"></div>
                    <span className="text-gray-600">Approved ({stats.approvedDonations})</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <div className="w-3 h-3 rounded-full bg-blue-500"></div>
                    <span className="text-gray-600">Collected ({stats.collectedDonations})</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <div className="w-3 h-3 rounded-full bg-yellow-500"></div>
                    <span className="text-gray-600">Pending ({stats.pendingDonations})</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <div className="w-3 h-3 rounded-full bg-red-500"></div>
                    <span className="text-gray-600">Rejected ({stats.rejectedDonations})</span>
                  </div>
                </div>
              </div>

              {/* Recent Transactions */}
              <div className="bg-white rounded-lg p-6 shadow-sm border border-gray-100">
                <h3 className="text-lg font-semibold text-gray-800 mb-4">Recent Transactions</h3>
                <div className="space-y-2 max-h-80 overflow-y-auto">
                  {recentTransactions.length > 0 ? (
                    recentTransactions.map((tx, index) => (
                      <ActivityItem
                        key={index}
                        icon={FaDollarSign}
                        color="bg-green-100 text-green-600"
                        title={`Received Rs. ${tx.amount}`}
                        desc={`${tx.item_name} - ${tx.customer_name}`}
                        time={formatTime(tx.date)}
                      />
                    ))
                  ) : (
                    <p className="text-gray-400 text-sm">No recent transactions</p>
                  )}
                </div>
              </div>

              {/* Recent Activities */}
              <div className="bg-white rounded-lg p-6 shadow-sm border border-gray-100">
                <h3 className="text-lg font-semibold text-gray-800 mb-4">Recent Activities</h3>
                <div className="space-y-2 max-h-80 overflow-y-auto">
                  {recentActivities.length > 0 ? (
                    recentActivities.map((activity, index) => (
                      <ActivityItem key={index} {...activity} />
                    ))
                  ) : (
                    <p className="text-gray-400 text-sm">No recent activities</p>
                  )}
                </div>
              </div>

              {/* Quick Actions */}
              <div className="bg-white rounded-lg p-6 shadow-sm border border-gray-100">
                <h3 className="text-lg font-semibold text-gray-800 mb-4">Quick Actions</h3>
                <div className="space-y-3 text-sm">
                  <QuickActionButton label="Verify Listings" color="purple" onClick={() => navigate('/myClothingItems')} />
                  <QuickActionButton label="List Clothes" color="green" onClick={() => navigate('/addClothingItem')} />
                  <QuickActionButton label="Handle Donations" color="blue" onClick={() => navigate('/storedonations')} />
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      <Footer />
    </div>
  );
};

export default StoreDashboard;

import React, { useState, useEffect } from "react";
import { useNavigate, useLocation } from "react-router-dom";
import axiosInstance from "../services/axiosInstance";
import StoreSidebar from "../Components/StoreSidebar";
import StoreLocationMap, { searchAddressAndCenter } from "../Components/StoreLocationMap";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import Alert from "../Components/Alert";
import { FaStore, FaMapMarkerAlt, FaSave, FaCamera, FaClock, FaBuilding } from "react-icons/fa";

const StoreProfile = () => {
    const navigate = useNavigate();
    const location = useLocation();
    const isLocationMode = location.pathname === "/storeLocation";

    const [isLoading, setIsLoading] = useState(true);
    const [isSaving, setIsSaving] = useState(false);
    const [alert, setAlert] = useState({ message: "", type: "" });
    const [locationChanged, setLocationChanged] = useState(false);

    const [formData, setFormData] = useState({
        store_name: "",
        owner_name: "",
        phone_number: "",
        store_address: "",
        city: "",
        store_description: "",
        latitude: null,
        longitude: null,
        open_time: "",
        close_time: "",
        store_logo: null,
        store_logo_url: ""
    });

    useEffect(() => {
        fetchProfile();
    }, []);

    const fetchProfile = async () => {
        try {
            setIsLoading(true);
            const response = await axiosInstance.get("accounts/stores/profile/");
            const data = response.data?.data || response.data;
            setFormData({
                store_name: data.store_name || "",
                owner_name: data.owner_name || "",
                phone_number: data.phone_number || "",
                store_address: data.store_address || "",
                city: data.city || "",
                store_description: data.store_description || "",
                latitude: data.latitude,
                longitude: data.longitude,
                open_time: data.open_time || "",
                close_time: data.close_time || "",
                store_logo_url: data.store_logo_url || data.store_logo || "",
                store_logo: null
            });
        } catch (error) {
            console.error("Error fetching profile:", error);
            setAlert({ message: "Failed to load profile", type: "error" });
        } finally {
            setIsLoading(false);
        }
    };

    const handleChange = (e) => {
        const { name, value, files } = e.target;
        if (files) {
            setFormData(prev => ({ ...prev, [name]: files[0] }));
        } else {
            setFormData(prev => ({ ...prev, [name]: value }));
        }
    };

    const handleLocationSelect = (lat, lng) => {
        setFormData(prev => ({ ...prev, latitude: lat, longitude: lng }));
        setLocationChanged(true);
    };

    const handleLocateAddress = () => {
        const address = `${formData.city}, ${formData.store_address}`;
        searchAddressAndCenter(address, (coords) => {
            setFormData(prev => ({
                ...prev,
                latitude: coords.lat,
                longitude: coords.lng
            }));
            setLocationChanged(true);
            setAlert({ message: "Location found and marked on map! Remember to Save Changes.", type: "success" });
        }, setAlert);
    };

    const handleSave = async (e) => {
        e.preventDefault();
        setIsSaving(true);
        try {
            const data = new FormData();
            Object.keys(formData).forEach(key => {
                if (key === 'store_logo') {
                    if (formData[key]) data.append(key, formData[key]);
                } else if (formData[key] !== null && formData[key] !== undefined) {
                    data.append(key, formData[key]);
                }
            });

            await axiosInstance.patch("accounts/stores/profile/", data, {
                headers: { "Content-Type": "multipart/form-data" }
            });

            setAlert({ message: "Profile updated successfully!", type: "success" });
            setLocationChanged(false);
            fetchProfile(); // Refresh
        } catch (error) {
            console.error("Error saving profile:", error);
            setAlert({ message: "Failed to save profile", type: "error" });
        } finally {
            setIsSaving(false);
        }
    };

    if (isLoading) {
        return (
            <div className="min-h-screen bg-gray-50 flex flex-col">
                <Navbar />
                <div className="flex-1 flex justify-center items-center">
                    <div className="w-12 h-12 border-4 border-purple-500 border-t-transparent rounded-full animate-spin"></div>
                </div>
                <Footer />
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-gray-50 flex flex-col">
            <Navbar />

            <div className="flex flex-1">
                <StoreSidebar />

                <div className="flex-1 p-8 overflow-auto">
                    <div className="max-w-5xl mx-auto">
                        <div className="flex items-center justify-between mb-8">
                            <div>
                                <h1 className="text-3xl font-bold text-gray-800">
                                    {isLocationMode ? "Shop Location" : "Store Settings"}
                                </h1>
                                <p className="text-gray-500 mt-1">
                                    {isLocationMode ? "Manage your shop's physical location on the map" : "Manage your shop brand and location"}
                                </p>
                            </div>
                            <button
                                onClick={handleSave}
                                disabled={isSaving}
                                className={`px-6 py-3 rounded-xl font-bold transition flex items-center gap-2 shadow-lg disabled:opacity-50 ${locationChanged
                                    ? "bg-orange-500 hover:bg-orange-600 text-white shadow-orange-100 border-2 border-orange-200 animate-pulse highlight-save"
                                    : "bg-purple-600 hover:bg-purple-700 text-white shadow-purple-100"
                                    }`}
                            >
                                {isSaving ? <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div> : <FaSave />}
                                {locationChanged ? "Save Location Changes" : "Save Changes"}
                            </button>
                        </div>

                        {locationChanged && (
                            <div className="bg-orange-50 border border-orange-100 p-4 rounded-xl mb-6 flex items-center gap-3 animate-fade-in">
                                <div className="w-2 h-2 bg-orange-500 rounded-full animate-ping"></div>
                                <p className="text-orange-700 text-sm font-bold">
                                    Location updated! Click "Save Location Changes" above to persist your new shop position.
                                </p>
                            </div>
                        )}

                        <div className={`grid grid-cols-1 ${isLocationMode ? 'lg:grid-cols-1' : 'lg:grid-cols-3'} gap-8`}>
                            {/* Left Column: Profile Info (Hidden in Location Mode) */}
                            {!isLocationMode && (
                                <div className="lg:col-span-1 space-y-6">
                                    <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm text-center">
                                        <div className="relative w-32 h-32 mx-auto mb-4 group">
                                            <div className="w-full h-full rounded-2xl bg-gray-100 overflow-hidden border-2 border-white shadow-md">
                                                {formData.store_logo_url || formData.store_logo ? (
                                                    <img
                                                        src={formData.store_logo ? URL.createObjectURL(formData.store_logo) : formData.store_logo_url}
                                                        alt="Store Logo"
                                                        className="w-full h-full object-cover"
                                                    />
                                                ) : (
                                                    <div className="w-full h-full flex items-center justify-center text-gray-400">
                                                        <FaStore size={40} />
                                                    </div>
                                                )}
                                            </div>
                                            <label className="absolute bottom-2 right-2 p-2 bg-purple-600 text-white rounded-lg cursor-pointer hover:bg-purple-700 shadow-lg transition-transform hover:scale-110">
                                                <FaCamera size={14} />
                                                <input type="file" name="store_logo" className="hidden" onChange={handleChange} accept="image/*" />
                                            </label>
                                        </div>
                                        <h2 className="font-bold text-gray-800 text-lg">{formData.store_name || "My Store"}</h2>
                                        <p className="text-xs text-gray-500 uppercase font-black tracking-widest mt-1">Shop Admin</p>
                                    </div>

                                    <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm space-y-4">
                                        <h3 className="font-bold text-gray-800 border-b border-gray-50 pb-2 flex items-center gap-2">
                                            <FaBuilding className="text-purple-500" /> Business Details
                                        </h3>
                                        <div>
                                            <label className="text-xs font-bold text-gray-400 uppercase mb-1 block">Store Name</label>
                                            <input
                                                type="text"
                                                name="store_name"
                                                value={formData.store_name}
                                                onChange={handleChange}
                                                className="w-full p-3 bg-gray-50 border border-gray-100 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500 text-sm"
                                            />
                                        </div>
                                        <div>
                                            <label className="text-xs font-bold text-gray-400 uppercase mb-1 block">Store Description</label>
                                            <textarea
                                                name="store_description"
                                                value={formData.store_description}
                                                onChange={handleChange}
                                                rows="4"
                                                className="w-full p-3 bg-gray-50 border border-gray-100 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500 text-sm"
                                            />
                                        </div>
                                    </div>

                                    <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm space-y-4">
                                        <h3 className="font-bold text-gray-800 border-b border-gray-50 pb-2 flex items-center gap-2">
                                            <FaClock className="text-purple-500" /> Operating Hours
                                        </h3>
                                        <div className="grid grid-cols-2 gap-4">
                                            <div>
                                                <label className="text-xs font-bold text-gray-400 uppercase mb-1 block">Opening Time</label>
                                                <input
                                                    type="time"
                                                    name="open_time"
                                                    value={formData.open_time}
                                                    onChange={handleChange}
                                                    className="w-full p-3 bg-gray-50 border border-gray-100 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500 text-sm"
                                                />
                                            </div>
                                            <div>
                                                <label className="text-xs font-bold text-gray-400 uppercase mb-1 block">Closing Time</label>
                                                <input
                                                    type="time"
                                                    name="close_time"
                                                    value={formData.close_time}
                                                    onChange={handleChange}
                                                    className="w-full p-3 bg-gray-50 border border-gray-100 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500 text-sm"
                                                />
                                            </div>
                                        </div>
                                        <p className="text-[10px] text-gray-500 italic">Customers will see your store as "Open" or "Closed" based on these hours.</p>
                                    </div>
                                </div>
                            )}

                            {/* Right Column: Location & Contact */}
                            <div className={`${isLocationMode ? 'lg:col-span-3 max-w-4xl mx-auto w-full' : 'lg:col-span-2'} space-y-6`}>
                                <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm">
                                    <h3 className="font-bold text-gray-800 border-b border-gray-50 pb-4 mb-6 flex items-center gap-2">
                                        <FaMapMarkerAlt className="text-purple-500" /> Shop Location
                                    </h3>

                                    <div className="grid grid-cols-2 gap-4 mb-6">
                                        <div>
                                            <label className="text-xs font-bold text-gray-400 uppercase mb-1 block">City</label>
                                            <input
                                                type="text"
                                                name="city"
                                                value={formData.city}
                                                onChange={handleChange}
                                                className="w-full p-3 bg-gray-50 border border-gray-100 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500 text-sm"
                                                placeholder="e.g. Kathmandu"
                                            />
                                        </div>
                                        <div>
                                            <label className="text-xs font-bold text-gray-400 uppercase mb-1 block">Address</label>
                                            <input
                                                type="text"
                                                name="store_address"
                                                value={formData.store_address}
                                                onChange={handleChange}
                                                className="w-full p-3 bg-gray-50 border border-gray-100 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500 text-sm"
                                                placeholder="e.g. New Road"
                                            />
                                        </div>
                                    </div>

                                    <div className="mb-6">
                                        <button
                                            type="button"
                                            onClick={handleLocateAddress}
                                            className="w-full bg-purple-600 text-white px-4 py-3 rounded-xl font-bold hover:bg-purple-700 transition flex items-center justify-center gap-2 shadow-lg shadow-purple-200"
                                        >
                                            <FaMapMarkerAlt size={16} />
                                            Locate Shop on Map
                                        </button>
                                        <p className="text-[10px] text-gray-500 mt-2 text-center italic">
                                            ≡ƒÆí Click this after typing your city/address to automatically find it on the map.
                                        </p>
                                    </div>

                                    <StoreLocationMap
                                        onLocationSelect={handleLocationSelect}
                                        initialLocation={{ lat: formData.latitude, lng: formData.longitude }}
                                        city={formData.city}
                                    />

                                    <div className="mt-4 grid grid-cols-2 gap-4">
                                        <div className="bg-gray-50 p-3 rounded-xl border border-gray-100">
                                            <span className="text-[10px] font-bold text-gray-400 uppercase block">Latitude</span>
                                            <span className="text-sm font-mono text-gray-600">{formData.latitude !== null && formData.latitude !== undefined ? formData.latitude : "Not set"}</span>
                                        </div>
                                        <div className="bg-gray-50 p-3 rounded-xl border border-gray-100">
                                            <span className="text-[10px] font-bold text-gray-400 uppercase block">Longitude</span>
                                            <span className="text-sm font-mono text-gray-600">{formData.longitude !== null && formData.longitude !== undefined ? formData.longitude : "Not set"}</span>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            <Footer />

            <Alert
                message={alert.message}
                type={alert.type}
                onClose={() => setAlert({ message: "", type: "" })}
            />
        </div>
    );
};

