    if (!formData.email) {
      setError("Email is required");
      return;
    }
    if (!formData.password) {
      setError("Password is required");
      return;
    }
    if (formData.password.length < 8) {
      setError("Password must be at least 8 characters");
      return;
    }
    if (formData.password !== formData.confirmPassword) {
      setError("Passwords do not match");
      return;
    }

    setIsLoading(true);
    setError("");
    setMessage("");

    try {
      const formDataToSend = new FormData();
      formDataToSend.append("store_name", formData.store_name);
      formDataToSend.append("owner_name", formData.owner_name);
      formDataToSend.append("email", formData.email);
      formDataToSend.append("password", formData.password);
      formDataToSend.append("phone_number", formData.phone_number || "");
      formDataToSend.append("store_address", formData.store_address);
      formDataToSend.append("city", formData.city);
      formDataToSend.append("store_description", formData.store_description || "");
      if (formData.store_logo) {
        formDataToSend.append("store_logo", formData.store_logo);
      }

      const response = await axiosInstance.post("accounts/register/store/", formDataToSend, {
        headers: {
          "Content-Type": "multipart/form-data",
        },
      });

      const successMsg = "Store registered! Please verify OTP.";
      setMessage(successMsg);
      setStep(3); // Move to OTP verification step
    } catch (error) {
      console.error("Network Error:", error);
      let errorMsg = "Registration failed. Please try again.";
      const errorData = error.response?.data;

      if (errorData) {
        if (errorData.email) {
          errorMsg = Array.isArray(errorData.email) ? errorData.email[0] : errorData.email;
        } else if (errorData.phone_number) {
          errorMsg = Array.isArray(errorData.phone_number) ? errorData.phone_number[0] : errorData.phone_number;
        } else if (errorData.store_name) {
          errorMsg = Array.isArray(errorData.store_name) ? errorData.store_name[0] : errorData.store_name;
        } else if (errorData.password) {
          errorMsg = Array.isArray(errorData.password) ? errorData.password[0] : errorData.password;
        } else if (errorData.message) {
          errorMsg = errorData.message;
        } else if (errorData.error) {
          errorMsg = errorData.error;
        } else if (typeof errorData === 'string') {
          errorMsg = errorData;
        }
      }

      setError(errorMsg);
    } finally {
      setIsLoading(false);
    }
  };

  // Step 3: Verify OTP
  const handleVerifyOTP = async () => {
    if (!otp || otp.length !== 6) {
      setError("Please enter a valid 6-digit OTP");
      return;
    }

    setIsLoading(true);
    setError("");
    setMessage("");

    try {
      const response = await axiosInstance.post("accounts/verify-otp/", {
        email: formData.email,
        otp: otp,
      });

      // Add authentication for navbar
      if (response.data.access_token) {
        localStorage.setItem("authToken", response.data.access_token);
        localStorage.setItem("userType", "store");
        window.dispatchEvent(new Event('authChange'));
      }

      setMessage("Account verified successfully! Redirecting to login...");
      // Redirect to login page
      setTimeout(() => {
        navigate("/login");
      }, 2000);
    } catch (error) {
      console.error("OTP Verification Error:", error);
      const errorMsg = error.response?.data?.message || error.response?.data?.error || "Invalid OTP. Please try again.";
      setError(errorMsg);
    } finally {
      setIsLoading(false);
    }
  };

  const handleResendOtp = async () => {
    // Note: Resend OTP endpoint may need to be implemented in backend
    setError("Please use the OTP sent to your email. If you didn't receive it, try registering again.");
    setOtp("");
  };

  return (
    <>
      <Navbar />
      <div className="min-h-screen grid grid-cols-1 lg:grid-cols-2">
        {/* Left Section */}
        <div className="hidden lg:flex flex-col justify-center px-20 bg-gradient-to-br from-purple-600 via-purple-500 to-pink-500 text-white">
          <h1 className="text-4xl font-bold mb-4">Join the Fashion Revolution</h1>
          <p className="text-purple-100 mb-8 max-w-md">
            {step === 1 || step === 2
              ? "Create your store account, list outfits, and reach customers nearby."
              : "We've sent a verification code to your email. Please enter it below to complete your registration."}
          </p>
        </div>

        {/* Right Section */}
        <div className="flex items-center justify-center bg-gray-50 px-6 py-8">
          <div className="bg-white w-full max-w-md rounded-2xl shadow-lg p-10">
            <h2 className="text-2xl font-bold mb-4 text-center">Register as Store</h2>

            {message && (
              <p className="text-green-600 text-center mb-4 bg-green-50 p-3 rounded-lg">
                {message}
              </p>
            )}

            {error && (
              <p className="text-red-500 text-center mb-4 bg-red-50 p-3 rounded-lg">
                {error}
              </p>
            )}

            {/* Step 1: Basic Info */}
            {step === 1 && (
              <div className="space-y-4">
                <div className="relative">
                  <FaUser className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                  <input
                    type="text"
                    name="owner_name"
                    placeholder="Owner Name"
                    value={formData.owner_name}
                    onChange={handleChange}
                    className="w-full p-3 border rounded-lg pl-10 focus:outline-none focus:ring-2 focus:ring-purple-500"
                    required
                  />
                </div>

                <div className="relative">
                  <FaEnvelope className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                  <input
                    type="email"
                    name="email"
                    placeholder="Email"
                    value={formData.email}
                    onChange={handleChange}
                    className="w-full p-3 border rounded-lg pl-10 focus:outline-none focus:ring-2 focus:ring-purple-500"
                    required
                  />
                </div>

                <div className="relative">
                  <FaPhone className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                  <input
                    type="tel"
                    name="phone_number"
                    placeholder="Phone Number"
                    value={formData.phone_number}
                    onChange={handleChange}
                    className="w-full p-3 border rounded-lg pl-10 focus:outline-none focus:ring-2 focus:ring-purple-500"
                  />
                </div>

                <input
                  type="text"
                  name="store_name"
                  placeholder="Store Name"
                  value={formData.store_name}
                  onChange={handleChange}
                  className="w-full p-3 border rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500"
                  required
                />

                <input
                  type="text"
                  name="store_address"
                  placeholder="Store Address"
                  value={formData.store_address}
                  onChange={handleChange}
                  className="w-full p-3 border rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500"
                  required
                />

                <input
                  type="text"
                  name="city"
                  placeholder="City"
                  value={formData.city}
                  onChange={handleChange}
                  className="w-full p-3 border rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500"
                  required
                />

                <textarea
                  name="store_description"
                  placeholder="Store Description"
                  value={formData.store_description}
                  onChange={handleChange}
                  className="w-full p-3 border rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500"
                  rows="3"
                />

                <input
                  type="text"
                  name="business_registration_number"
                  placeholder="Business Registration Number (Optional)"
                  value={formData.business_registration_number}
                  onChange={handleChange}
                  className="w-full p-3 border rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500"
                />
                <p className="text-xs text-gray-500">Note: This field is for reference only and is not stored in the backend yet.</p>

                <div className="border-2 border-dashed border-gray-300 rounded-lg p-4 text-center hover:border-purple-400 transition">
                  <input
                    type="file"
                    name="store_logo"
                    accept="image/*"
                    onChange={handleChange}
                    className="w-full"
                    id="store_logo"
                  />
                  <label htmlFor="store_logo" className="text-sm text-gray-500 cursor-pointer">
                    Upload Store Logo (Optional)
                  </label>
                </div>

                <button
                  onClick={() => setStep(2)}
                  className="w-full bg-purple-600 text-white p-3 rounded-lg font-semibold hover:bg-purple-700 transition"
                >
                  Continue
                </button>

                <p className="text-sm text-center text-gray-600 mt-4">
                  Already have an account?{" "}
                  <span
                    onClick={() => navigate("/login")}
                    className="text-purple-600 font-semibold cursor-pointer hover:underline"
                  >
                    Login here
                  </span>
                </p>
              </div>
            )}

            {/* Step 2: Password */}
            {step === 2 && (
              <div className="space-y-4">
                <div className="relative">
                  <FaLock className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                  <input
                    type="password"
                    name="password"
                    placeholder="Password"
                    value={formData.password}
                    onChange={handleChange}
                    className="w-full p-3 border rounded-lg pl-10 focus:outline-none focus:ring-2 focus:ring-purple-500"
                    required
                  />
                </div>

                <div className="relative">
                  <FaLock className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                  <input
                    type="password"
                    name="confirmPassword"
                    placeholder="Confirm Password"
                    value={formData.confirmPassword}
                    onChange={handleChange}
                    className="w-full p-3 border rounded-lg pl-10 focus:outline-none focus:ring-2 focus:ring-purple-500"
                    required
                  />
                </div>

                <button
                  onClick={handleRegister}
                  disabled={isLoading}
                  className="w-full bg-purple-600 text-white p-3 rounded-lg font-semibold hover:bg-purple-700 transition disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {isLoading ? "Creating Account..." : "Create Account"}
                </button>

                <button
                  onClick={() => setStep(1)}
                  disabled={isLoading}
                  className="w-full bg-gray-200 text-gray-700 p-3 rounded-lg font-semibold hover:bg-gray-300 transition disabled:opacity-50"
                >
                  Back
                </button>
              </div>
            )}

            {/* Step 3: OTP Verification */}
            {step === 3 && (
              <div className="space-y-4">
                <div className="text-center mb-4">
                  <h3 className="text-xl font-semibold mb-2">Verify Your Email</h3>
                  <p className="text-sm text-gray-600">
                    Enter the 6-digit code sent to{" "}
                    <span className="font-semibold">{formData.email}</span>
                  </p>
                </div>

                <div className="relative">
                  <input
                    type="text"
                    name="otp"
                    placeholder="Enter 6-digit OTP"
                    value={otp}
                    onChange={(e) => {
                      const value = e.target.value.replace(/\D/g, "").slice(0, 6);
                      setOtp(value);
                      setError("");
                    }}
                    maxLength="6"
                    className="w-full p-3 border rounded-lg text-center text-2xl tracking-widest focus:outline-none focus:ring-2 focus:ring-purple-500"
                    required
                  />
                </div>

                <button
                  onClick={handleVerifyOTP}
                  disabled={isLoading}
                  className="w-full bg-purple-600 text-white p-3 rounded-lg font-semibold hover:bg-purple-700 transition disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {isLoading ? "Verifying..." : "Verify OTP"}
                </button>

                <div className="text-center">
                  <p className="text-sm text-gray-600">
                    Didn't receive the code?{" "}
                    <button
                      onClick={handleResendOtp}
                      disabled={isLoading}
                      className="text-purple-600 font-semibold hover:underline disabled:opacity-50"
                    >
                      Resend OTP
                    </button>
                  </p>
                </div>

                <button
                  onClick={() => setStep(2)}
                  disabled={isLoading}
                  className="w-full bg-gray-200 text-gray-700 p-3 rounded-lg font-semibold hover:bg-gray-300 transition disabled:opacity-50"
                >
                  Back
                </button>
              </div>
            )}
          </div>
        </div>
      </div>
      <Footer />
    </>
  );
};

export default StoreRegister;

import React, { useState, useEffect } from 'react';
import axiosInstance from '../services/axiosInstance';
import Navbar from '../Components/Navbar';
import Footer from '../Components/Footer';
import Alert from '../Components/Alert';
import { FaCheck, FaTimes, FaBox, FaUser, FaCalendarAlt, FaDollarSign, FaUndo } from 'react-icons/fa';

const StoreRentals = () => {
    const [rentals, setRentals] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [alert, setAlert] = useState({ message: '', type: '' });

    useEffect(() => {
        fetchStoreRentals();
    }, []);

    const fetchStoreRentals = async () => {
        try {
            setIsLoading(true);
            const response = await axiosInstance.get('rent/store/');
            setRentals(response.data);
        } catch (error) {
            console.error('Error fetching store rentals:', error);
            showAlert('Failed to load rental requests.', 'error');
        } finally {
            setIsLoading(false);
        }
    };

    const handleApprove = async (id) => {
        try {
            await axiosInstance.patch(`rent/${id}/approve/`);
            showAlert('Rental approved successfully.', 'success');
            fetchStoreRentals();
        } catch (error) {
            showAlert(error.response?.data?.error || 'Failed to approve rental.', 'error');
        }
    };

    const handleReject = async (id) => {
        try {
            await axiosInstance.patch(`rent/${id}/reject/`);
            showAlert('Rental request rejected.', 'info');
            fetchStoreRentals();
        } catch (error) {
            showAlert(error.response?.data?.error || 'Failed to reject rental.', 'error');
        }
    };

    const handleConfirmReturn = async (id) => {
        try {
            await axiosInstance.patch(`rent/${id}/confirm-return/`);
            showAlert('Return confirmed and stock updated.', 'success');
            fetchStoreRentals();
        } catch (error) {
            showAlert(error.response?.data?.error || 'Failed to confirm return.', 'error');
        }
    };

    const showAlert = (message, type) => {
        setAlert({ message, type });
    };

    const getStatusBadge = (status) => {
        const styles = {
            pending: 'bg-yellow-100 text-yellow-800',
            approved: 'bg-green-100 text-green-800',
            rejected: 'bg-red-100 text-red-800',
            rented: 'bg-blue-100 text-blue-800',
            returned_pending: 'bg-purple-100 text-purple-800',
            returned_confirmed: 'bg-gray-100 text-gray-800',
        };
        return styles[status] || 'bg-gray-100 text-gray-800';
    };

    return (
        <>
            <Navbar />
            <div className="min-h-screen bg-gray-50 py-12 px-4">
                <div className="max-w-7xl mx-auto">
                    <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
                        <div>
                            <h1 className="text-3xl font-bold text-gray-900">Rental Invitations</h1>
                            <p className="text-gray-600 mt-2">Manage incoming rental requests and confirm completions</p>
                        </div>
                        <button
                            onClick={fetchStoreRentals}
                            className="px-4 py-2 bg-white border border-gray-300 rounded-lg shadow-sm hover:bg-gray-50 transition-colors flex items-center gap-2"
                        >
                            <FaUndo className={isLoading ? 'animate-spin' : ''} />
                            Reload Requests
                        </button>
                    </div>

                    {isLoading ? (
                        <div className="flex justify-center py-20">
                            <div className="w-12 h-12 border-4 border-purple-500 border-t-transparent rounded-full animate-spin"></div>
                        </div>
                    ) : rentals.length === 0 ? (
                        <div className="bg-white rounded-2xl shadow-sm p-20 text-center border border-dashed border-gray-300">
                            <FaBox className="text-5xl text-gray-300 mx-auto mb-6" />
                            <h3 className="text-xl font-bold text-gray-900">No rental requests yet</h3>
                            <p className="text-gray-600 mt-2">When customers request to rent your items, they will appear here.</p>
                        </div>
                    ) : (
                        <div className="bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
                            <table className="w-full text-left border-collapse">
                                <thead>
                                    <tr className="bg-gray-50 border-b border-gray-100">
                                        <th className="px-6 py-4 text-sm font-bold text-gray-700 uppercase tracking-wider text-center">Rental Info</th>
                                        <th className="px-6 py-4 text-sm font-bold text-gray-700 uppercase tracking-wider text-center">Customer</th>
                                        <th className="px-6 py-4 text-sm font-bold text-gray-700 uppercase tracking-wider text-center">Dates & Price</th>
                                        <th className="px-6 py-4 text-sm font-bold text-gray-700 uppercase tracking-wider text-center">Status</th>
                                        <th className="px-6 py-4 text-sm font-bold text-gray-700 uppercase tracking-wider text-center">Actions</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-gray-100">
                                    {rentals.map((rental) => (
                                        <tr key={rental.id} className="hover:bg-gray-50/50 transition-colors">
                                            <td className="px-6 py-6 text-center">
                                                <p className="font-bold text-gray-900">{rental.clothing_name}</p>
                                                <p className="text-xs text-gray-500 mt-1">ID: #{rental.id}</p>
                                            </td>
                                            <td className="px-6 py-6 text-center">
                                                <div className="flex items-center gap-2 justify-center">
                                                    <div className="w-8 h-8 bg-purple-100 rounded-full flex items-center justify-center">
                                                        <FaUser className="text-purple-600 text-xs" />
                                                    </div>
                                                    <div>
                                                        <p className="text-sm font-medium text-gray-900">{rental.customer_email}</p>
                                                    </div>
                                                </div>
                                            </td>
                                            <td className="px-6 py-6 text-center">
                                                <div className="flex flex-col items-center gap-1">
                                                    <div className="flex items-center gap-2 text-xs text-gray-600">
                                                        <FaCalendarAlt className="text-purple-400" />
                                                        <span>{rental.rent_start_date} ΓåÆ {rental.rent_end_date}</span>
                                                    </div>
                                                    <div className="flex items-center gap-1 text-sm font-bold text-green-600">
                                                        <FaDollarSign />
                                                        <span>{rental.total_price}</span>
                                                    </div>
                                                </div>
                                            </td>
                                            <td className="px-6 py-6 text-center">
                                                <span className={`px-3 py-1 rounded-full text-xs font-bold ${getStatusBadge(rental.status)}`}>
                                                    {rental.status.replace('_', ' ').toUpperCase()}
                                                </span>
                                            </td>
                                            <td className="px-6 py-6 text-center">
                                                <div className="flex justify-center gap-2">
                                                    {rental.status === 'pending' && (
                                                        <>
                                                            <button
                                                                onClick={() => handleApprove(rental.id)}
                                                                className="p-2 bg-green-500 text-white rounded-lg hover:bg-green-600 transition-colors shadow-sm title='Approve'"
                                                            >
                                                                <FaCheck />
                                                            </button>
                                                            <button
                                                                onClick={() => handleReject(rental.id)}
                                                                className="p-2 bg-red-500 text-white rounded-lg hover:bg-red-600 transition-colors shadow-sm title='Reject'"
                                                            >
                                                                <FaTimes />
                                                            </button>
                                                        </>
                                                    )}
                                                    {rental.status === 'returned_pending' && (
                                                        <button
                                                            onClick={() => handleConfirmReturn(rental.id)}
                                                            className="px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 transition-colors shadow-sm font-bold text-xs"
                                                        >
                                                            Confirm Return
                                                        </button>
                                                    )}
                                                    {['approved', 'rented'].includes(rental.status) && (
                                                        <span className="text-xs italic text-gray-400">Waiting for Return</span>
                                                    )}
                                                    {['returned_confirmed', 'rejected'].includes(rental.status) && (
                                                        <span className="text-xs text-gray-400">-</span>
                                                    )}
                                                </div>
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    )}
                </div>
            </div>
            <Footer />
            <Alert
                message={alert.message}
                type={alert.type}
                onClose={() => setAlert({ message: '', type: '' })}
            />
        </>
    );
};

export default StoreRentals;

import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axiosInstance from "../services/axiosInstance";
import rentalAxiosInstance from "../services/rentalAxiosInstance";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import StoreSidebar from "../Components/StoreSidebar";
import {
    FaDollarSign,
    FaShoppingBag,
    FaCheckCircle,
    FaBox,
    FaTimesCircle,
    FaCalendarAlt,
    FaTshirt,
    FaUser,
    FaInfoCircle
} from "react-icons/fa";
import {
    AreaChart,
    Area,
    XAxis,
    YAxis,
    CartesianGrid,
    Tooltip,
    ResponsiveContainer
} from "recharts";

const StatCard = ({ icon: Icon, label, value, color, description }) => (
    <div className="bg-white rounded-2xl p-6 shadow-sm border border-gray-100">
        <div className="flex items-center justify-between mb-4">
            <div className={`w-12 h-12 rounded-xl bg-${color}-50 flex items-center justify-center`}>
                <Icon className={`text-${color}-500 text-xl`} />
            </div>
        </div>
        <div className="flex flex-col">
            <span className="text-sm font-medium text-gray-500">{label}</span>
            <span className="text-2xl font-black text-gray-900 mt-1">{value}</span>
            {description && <span className="text-xs text-gray-400 mt-1">{description}</span>}
        </div>
    </div>
);

const StoreReports = () => {
    const navigate = useNavigate();
    const [isLoading, setIsLoading] = useState(true);
    const [stats, setStats] = useState({
        totalEarnings: 0,
        earningsHistory: [],
        recentTransactions: []
    });
    const [rentals, setRentals] = useState([]);

    useEffect(() => {
        fetchData();
    }, []);

    const fetchData = async () => {
        try {
            setIsLoading(true);
            const [statsRes, rentalsRes] = await Promise.all([
                axiosInstance.get("accounts/dashboard/store/stats/"),
                rentalAxiosInstance.get("rentals/store/")
            ]);

            const statsData = statsRes.data.data;
            setStats({
                totalEarnings: statsData.total_earnings,
                earningsHistory: statsData.earnings_history,
                recentTransactions: statsData.recent_transactions
            });
            setRentals(rentalsRes.data);
        } catch (error) {
            console.error("Error fetching report data:", error);
        } finally {
            setIsLoading(false);
        }
    };

    const getRentalCounts = () => {
        const total = rentals.length;
        const active = rentals.filter(r => r.status === 'rented').length;
        const returned = rentals.filter(r => r.status === 'returned_confirmed').length;
        const cancelled = rentals.filter(r => r.status === 'rejected').length;
        return { total, active, returned, cancelled };
    };

    const counts = getRentalCounts();

    if (isLoading) {
        return (
            <div className="min-h-screen bg-gray-50 flex flex-col">
                <Navbar />
                <div className="flex-1 flex justify-center items-center">
                    <div className="text-center">
                        <div className="w-12 h-12 border-4 border-purple-500 border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
                        <p className="text-gray-600 font-bold uppercase tracking-widest text-xs">Generating Reports...</p>
                    </div>
                </div>
                <Footer />
            </div>
        );
    }

    return (
        <div className="min-h-screen flex flex-col bg-gray-50">
            <Navbar />
            <div className="flex flex-1">
                <StoreSidebar />
                <main className="flex-1 overflow-auto p-8">
                    <div className="max-w-7xl mx-auto">
                        {/* Header */}
                        <div className="mb-8">
                            <h1 className="text-3xl font-black text-gray-900 tracking-tight">Financial Reports</h1>
                            <p className="text-gray-500 mt-1">Detailed analytics and transaction history for your store.</p>
                        </div>

                        {/* KPI Cards */}
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-6 mb-8">
                            <StatCard
                                icon={FaDollarSign}
                                label="Total Revenue"
                                value={`Rs. ${stats.totalEarnings}`}
                                color="green"
                                description="Verified eSewa earnings"
                            />
                            <StatCard
                                icon={FaShoppingBag}
                                label="Total Rentals"
                                value={counts.total}
                                color="purple"
                                description="Total bookings made"
                            />
                            <StatCard
                                icon={FaBox}
                                label="Active Rentals"
                                value={counts.active}
                                color="blue"
                                description="Currently out with customers"
                            />
                            <StatCard
                                icon={FaCheckCircle}
                                label="Returned Items"
                                value={counts.returned}
                                color="emerald"
                                description="Successfully completed"
                            />
                            <StatCard
                                icon={FaTimesCircle}
                                label="Cancelled"
                                value={counts.cancelled}
                                color="red"
                                description="Rejected or failed"
                            />
                        </div>

                        {/* Charts Section */}
                        <div className="bg-white rounded-3xl p-8 shadow-sm border border-gray-100 mb-8">
                            <div className="flex items-center justify-between mb-6">
                                <div>
                                    <h2 className="text-xl font-bold text-gray-900">Earnings Trend</h2>
                                    <p className="text-sm text-gray-500">Revenue history for the last 30 days</p>
                                </div>
                                <div className="bg-green-50 px-4 py-2 rounded-xl border border-green-100">
