                                                                <img src={tx.item_image} alt={tx.item_name} className="w-full h-full object-cover" />
                                                            ) : (
                                                                <FaTshirt className="text-gray-300" />
                                                            )}
                                                        </div>
                                                        <span className="font-medium text-gray-800">{tx.item_name}</span>
                                                    </div>
                                                </td>
                                                <td className="px-6 py-4 text-center">
                                                    <span className="font-black text-green-600">Rs. {tx.amount}</span>
                                                </td>
                                                <td className="px-6 py-4 text-center">
                                                    <div className="flex items-center justify-center gap-2 text-xs text-gray-500 font-medium">
                                                        <FaCalendarAlt className="text-gray-300" />
                                                        {new Date(tx.date).toLocaleDateString()}
                                                    </div>
                                                </td>
                                                <td className="px-6 py-4 text-right">
                                                    <span className="px-3 py-1 bg-green-50 text-green-700 text-[10px] font-black uppercase rounded-full border border-green-200">
                                                        {tx.status}
                                                    </span>
                                                </td>
                                            </tr>
                                        ))}
                                        {stats.recentTransactions.length === 0 && (
                                            <tr>
                                                <td colSpan="5" className="px-6 py-12 text-center">
                                                    <div className="w-12 h-12 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4">
                                                        <FaInfoCircle className="text-gray-300 text-xl" />
                                                    </div>
                                                    <p className="text-gray-500 font-bold">No transactions recorded yet.</p>
                                                </td>
                                            </tr>
                                        )}
                                    </tbody>
                                </table>
                            </div>
                        </div>
                    </div>
                </main>
            </div>
            <Footer />
        </div>
    );
};

export default StoreReports;

import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axiosInstance from "../services/axiosInstance";
import DashboardSidebar from "../Components/DashboardSidebar";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import Alert from "../Components/Alert";
import { FaUser, FaEnvelope, FaPhone, FaMapMarkerAlt, FaSave, FaCamera, FaRulerCombined, FaVenusMars } from "react-icons/fa";

const UserProfile = () => {
    const navigate = useNavigate();
    const [isLoading, setIsLoading] = useState(true);
    const [isSaving, setIsSaving] = useState(false);
    const [alert, setAlert] = useState({ message: "", type: "" });

    const [formData, setFormData] = useState({
        full_name: "",
        email: "",
        phone_number: "",
        address: "",
        city: "",
        gender: "",
        preferred_clothing_size: "",
        profile_image: null,
        profile_image_url: ""
    });

    useEffect(() => {
        fetchProfile();
    }, []);

    const fetchProfile = async () => {
        try {
            setIsLoading(true);
            const response = await axiosInstance.get("accounts/customers/profile/");
            const data = response.data?.data || response.data;
            setFormData({
                full_name: data.full_name || "",
                email: data.email || "",
                phone_number: data.phone_number || "",
                address: data.address || "",
                city: data.city || "",
                gender: data.gender || "",
                preferred_clothing_size: data.preferred_clothing_size || "",
                profile_image_url: data.profile_image_url || data.profile_image || "",
                profile_image: null
            });
        } catch (error) {
            console.error("Error fetching profile:", error);
            setAlert({ message: "Failed to load profile", type: "error" });
        } finally {
            setIsLoading(false);
        }
    };

    const handleChange = (e) => {
        const { name, value, files } = e.target;
        if (files) {
            setFormData(prev => ({ ...prev, [name]: files[0] }));
        } else {
            setFormData(prev => ({ ...prev, [name]: value }));
        }
    };

    const handleSave = async (e) => {
        e.preventDefault();
        setIsSaving(true);
        try {
            const data = new FormData();
            // We only send fields that are allowed in CustomerUpdateSerializer
            const updateFields = ['full_name', 'phone_number', 'address', 'city', 'gender', 'preferred_clothing_size'];

            updateFields.forEach(key => {
                if (formData[key] !== null && formData[key] !== undefined) {
                    data.append(key, formData[key]);
                }
            });

            if (formData.profile_image) {
                data.append('profile_image', formData.profile_image);
            }

            await axiosInstance.patch("accounts/customers/profile/", data, {
                headers: { "Content-Type": "multipart/form-data" }
            });

            setAlert({ message: "Profile updated successfully!", type: "success" });
            fetchProfile(); // Refresh to get the latest data and reset the file input
        } catch (error) {
            console.error("Error saving profile:", error);
            setAlert({ message: error.response?.data?.message || "Failed to save profile", type: "error" });
        } finally {
            setIsSaving(false);
        }
    };

    if (isLoading) {
        return (
            <div className="flex justify-center items-center min-h-screen">
                <div className="w-12 h-12 border-4 border-purple-500 border-t-transparent rounded-full animate-spin"></div>
            </div>
        );
    }

    return (
        <>
            <Navbar />
            <div className="min-h-screen bg-gray-50 flex">
                <DashboardSidebar />
                <div className="flex-1 p-8">
                    <div className="max-w-4xl mx-auto">
                        <div className="flex items-center justify-between mb-8">
                            <div>
                                <h1 className="text-3xl font-bold text-gray-800">My Profile</h1>
                                <p className="text-gray-500 mt-1">Manage your personal information and preferences</p>
                            </div>
                            <button
                                onClick={handleSave}
                                disabled={isSaving}
                                className="px-6 py-3 bg-purple-600 hover:bg-purple-700 text-white rounded-xl font-bold transition flex items-center gap-2 shadow-lg shadow-purple-100 disabled:opacity-50"
                            >
                                {isSaving ? <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div> : <FaSave />}
                                Save Changes
                            </button>
                        </div>

                        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                            {/* Left Column: Avatar & Summary */}
                            <div className="lg:col-span-1 space-y-6">
                                <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm text-center">
                                    <div className="relative w-32 h-32 mx-auto mb-4 group">
                                        <div className="w-full h-full rounded-full bg-gray-100 overflow-hidden border-4 border-white shadow-md relative">
                                            {formData.profile_image_url || formData.profile_image ? (
                                                <img
                                                    src={formData.profile_image ? URL.createObjectURL(formData.profile_image) : formData.profile_image_url}
                                                    alt="Profile"
                                                    className="w-full h-full object-cover"
                                                />
                                            ) : (
                                                <div className="w-full h-full flex items-center justify-center text-gray-400 bg-purple-50">
                                                    <FaUser size={48} className="text-purple-200" />
                                                </div>
                                            )}
                                        </div>
                                        <label className="absolute bottom-1 right-1 p-2 bg-purple-600 text-white rounded-full cursor-pointer hover:bg-purple-700 shadow-lg transition-transform hover:scale-110 border-2 border-white">
                                            <FaCamera size={14} />
                                            <input type="file" name="profile_image" className="hidden" onChange={handleChange} accept="image/*" />
                                        </label>
                                    </div>
                                    <h2 className="font-bold text-gray-800 text-xl">{formData.full_name || "User"}</h2>
                                    <div className="flex items-center justify-center gap-2 text-gray-500 text-sm mt-1">
                                        <FaEnvelope className="text-xs" />
                                        <span>{formData.email}</span>
                                    </div>
                                    <div className="mt-4 inline-block px-3 py-1 bg-purple-50 text-purple-600 rounded-full text-xs font-bold uppercase tracking-wider">
                                        Customer
                                    </div>
                                </div>

                                {/* Quick view of preferences */}
                                <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm space-y-4">
                                    <h3 className="font-bold text-gray-800 border-b border-gray-50 pb-2 flex items-center gap-2">
                                        <FaRulerCombined className="text-purple-500 text-sm" /> Preferences
                                    </h3>
                                    <div className="grid grid-cols-2 gap-4">
                                        <div className="bg-gray-50 p-3 rounded-xl text-center">
                                            <p className="text-[10px] font-bold text-gray-400 uppercase">Size</p>
                                            <p className="text-sm font-bold text-gray-700">{formData.preferred_clothing_size || "N/A"}</p>
                                        </div>
                                        <div className="bg-gray-50 p-3 rounded-xl text-center">
                                            <p className="text-[10px] font-bold text-gray-400 uppercase">Gender</p>
                                            <p className="text-sm font-bold text-gray-700">{formData.gender || "N/A"}</p>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            {/* Right Column: Detailed Info Form */}
                            <div className="lg:col-span-2">
                                <div className="bg-white p-8 rounded-2xl border border-gray-100 shadow-sm">
                                    <form onSubmit={handleSave} className="space-y-6">
                                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                            <div className="space-y-2">
                                                <label className="text-sm font-bold text-gray-700 flex items-center gap-2">
                                                    <FaUser className="text-purple-500" /> Full Name
                                                </label>
                                                <input
                                                    type="text"
                                                    name="full_name"
                                                    value={formData.full_name}
                                                    onChange={handleChange}
                                                    className="w-full p-3 bg-gray-50 border border-gray-100 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500 transition"
                                                    required
                                                />
                                            </div>
                                            <div className="space-y-2">
                                                <label className="text-sm font-bold text-gray-700 flex items-center gap-2">
                                                    <FaPhone className="text-purple-500" /> Phone Number
                                                </label>
                                                <input
                                                    type="text"
                                                    name="phone_number"
                                                    value={formData.phone_number}
                                                    onChange={handleChange}
                                                    className="w-full p-3 bg-gray-50 border border-gray-100 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500 transition"
                                                />
                                            </div>
                                        </div>

                                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                            <div className="space-y-2">
                                                <label className="text-sm font-bold text-gray-700 flex items-center gap-2">
                                                    <FaVenusMars className="text-purple-500" /> Gender
                                                </label>
                                                <select
                                                    name="gender"
                                                    value={formData.gender}
                                                    onChange={handleChange}
                                                    className="w-full p-3 bg-gray-50 border border-gray-100 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500 transition appearance-none"
                                                >
                                                    <option value="">Select Gender</option>
                                                    <option value="Male">Male</option>
                                                    <option value="Female">Female</option>
                                                    <option value="Other">Other</option>
                                                </select>
                                            </div>
                                            <div className="space-y-2">
                                                <label className="text-sm font-bold text-gray-700 flex items-center gap-2">
                                                    <FaRulerCombined className="text-purple-500" /> Preferred Size
                                                </label>
                                                <select
                                                    name="preferred_clothing_size"
                                                    value={formData.preferred_clothing_size}
                                                    onChange={handleChange}
                                                    className="w-full p-3 bg-gray-50 border border-gray-100 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500 transition appearance-none"
                                                >
                                                    <option value="">Select Size</option>
                                                    <option value="XS">XS</option>
                                                    <option value="S">S</option>
                                                    <option value="M">M</option>
                                                    <option value="L">L</option>
                                                    <option value="XL">XL</option>
                                                    <option value="XXL">XXL</option>
                                                </select>
                                            </div>
                                        </div>

                                        <div className="space-y-2">
                                            <label className="text-sm font-bold text-gray-700 flex items-center gap-2">
                                                <FaMapMarkerAlt className="text-purple-500" /> City
                                            </label>
                                            <input
                                                type="text"
                                                name="city"
                                                value={formData.city}
                                                onChange={handleChange}
                                                className="w-full p-3 bg-gray-50 border border-gray-100 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500 transition"
                                                placeholder="e.g. Kathmandu"
                                            />
                                        </div>

                                        <div className="space-y-2">
                                            <label className="text-sm font-bold text-gray-700 flex items-center gap-2">
                                                <FaMapMarkerAlt className="text-purple-500" /> Full Address
                                            </label>
                                            <textarea
                                                name="address"
                                                value={formData.address}
                                                onChange={handleChange}
                                                rows="3"
                                                className="w-full p-3 bg-gray-50 border border-gray-100 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500 transition"
                                                placeholder="e.g. New Road, Sector 4"
                                            />
                                        </div>

                                        <div className="pt-4 border-t border-gray-50 text-xs text-gray-400 italic">
                                            * Email address cannot be changed for security reasons.
                                        </div>
                                    </form>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
            <Footer />
            <Alert
                message={alert.message}
                type={alert.type}
                onClose={() => setAlert({ message: "", type: "" })}
            />
        </>
    );
};

export default UserProfile;

import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import axiosInstance from "../services/axiosInstance";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import { FaEnvelope, FaLock, FaUser, FaPhone, FaMapMarkerAlt } from "react-icons/fa";

const UserRegister = () => {
  const navigate = useNavigate();
  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState({
    full_name: "",
    email: "",
    phone_number: "",
    password: "",
    confirmPassword: "",
    address: "",
    city: "",
    gender: "",
    preferred_clothing_size: "",
    profile_image: null,
  });
  const [otp, setOtp] = useState("");
  const [errors, setErrors] = useState({});
  const [serverError, setServerError] = useState("");
  const [isLoading, setIsLoading] = useState(false);

  const handleChange = (e) => {
    if (e.target.name === "profile_image") {
      setFormData({ ...formData, profile_image: e.target.files[0] });
    } else {
      setFormData({ ...formData, [e.target.name]: e.target.value });
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setServerError("");
    setErrors({});

    // Client-side validation
    const validationErrors = {};
    if (!formData.full_name) validationErrors.full_name = "Full name is required";
    if (!formData.email) validationErrors.email = "Email is required";
    if (!formData.phone_number) validationErrors.phone_number = "Phone number is required";
    if (!formData.password) validationErrors.password = "Password is required";
    if (formData.password.length < 8) validationErrors.password = "Password must be at least 8 characters";
    if (formData.password !== formData.confirmPassword)
      validationErrors.confirmPassword = "Passwords do not match";

    if (Object.keys(validationErrors).length > 0) {
      setErrors(validationErrors);
      return;
    }

    setIsLoading(true);

    try {
      const data = new FormData();
      Object.keys(formData).forEach((key) => {
        if (formData[key] !== null && key !== "confirmPassword") {
          data.append(key, formData[key]);
        }
      });

      const response = await axiosInstance.post("accounts/register/customer/", data, {
        headers: {
          "Content-Type": "multipart/form-data",
        },
      });

      setServerError("");
      setStep(2);
    } catch (error) {
      console.error("Registration Error:", error);
      let message = "Registration failed. Please try again.";
      const errorData = error.response?.data;

      if (errorData) {
        if (errorData.email) {
          message = Array.isArray(errorData.email) ? errorData.email[0] : errorData.email;
        } else if (errorData.phone_number) {
          message = Array.isArray(errorData.phone_number) ? errorData.phone_number[0] : errorData.phone_number;
        } else if (errorData.full_name) {
          message = Array.isArray(errorData.full_name) ? errorData.full_name[0] : errorData.full_name;
        } else if (errorData.password) {
          message = Array.isArray(errorData.password) ? errorData.password[0] : errorData.password;
        } else if (errorData.message) {
          message = errorData.message;
        } else if (errorData.error) {
          message = errorData.error;
        } else if (typeof errorData === 'string') {
          message = errorData;
        }
      }

      setServerError(message);
    } finally {
      setIsLoading(false);
    }
  };

  const handleOtpSubmit = async (e) => {
    e.preventDefault();
    setServerError("");

    if (!otp || otp.length !== 6) {
      setServerError("Please enter a valid 6-digit OTP");
      return;
    }

    setIsLoading(true);

    try {
      const response = await axiosInstance.post("accounts/verify-otp/", {
        email: formData.email,
        otp: otp,
      });

      // Add authentication for navbar
      if (response.data.access_token) {
        localStorage.setItem("authToken", response.data.access_token);
        localStorage.setItem("userType", "user");
        window.dispatchEvent(new Event('authChange'));
      }

      setServerError("");
      setTimeout(() => navigate("/login"), 2000);
    } catch (error) {
      console.error("OTP Verification Error:", error);
      const message = error.response?.data?.message || error.response?.data?.error || "Invalid or expired OTP. Please try again.";
      setServerError(message);
    } finally {
      setIsLoading(false);
    }
  };

  const handleResendOtp = async () => {
    // Note: Resend OTP endpoint may need to be implemented in backend
    setServerError("Please use the OTP sent to your email. If you didn't receive it, try registering again.");
    setOtp("");
  };

  return (
    <>
      <Navbar />
      <div className="min-h-screen grid grid-cols-1 lg:grid-cols-2">
        {/* Left Section */}
        <div className="hidden lg:flex flex-col justify-center px-20 bg-gradient-to-br from-purple-600 via-purple-500 to-pink-500 text-white">
          <h1 className="text-4xl font-bold mb-4">Join RentFit Today</h1>
          <p className="text-purple-100 mb-8 max-w-md">
            {step === 1
              ? "Register as a customer to explore online clothes rental, browse outfits, and rent your favorite fashion easily."
              : "We've sent a verification code to your email. Please enter it below to complete your registration."}
          </p>
        </div>

        {/* Right Section */}
        <div className="flex items-center justify-center bg-gray-50 px-6 py-8">
          <div className="bg-white w-full max-w-md rounded-2xl shadow-lg p-10">
            {step === 1 ? (
              <>
                <h2 className="text-2xl font-bold mb-4 text-center">
                  Register as Customer
                </h2>

                {serverError && (
                  <p className="text-red-500 text-center mb-4 bg-red-50 p-3 rounded-lg">{serverError}</p>
                )}

                <form onSubmit={handleSubmit} className="space-y-4">
                  <div className="relative">
                    <FaUser className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                    <input
                      type="text"
                      name="full_name"
                      placeholder="Full Name"
                      value={formData.full_name}
                      onChange={handleChange}
                      className="w-full p-3 border rounded-lg pl-10 focus:outline-none focus:ring-2 focus:ring-purple-500"
                    />
                    {errors.full_name && (
                      <p className="text-red-500 text-xs mt-1">{errors.full_name}</p>
                    )}
                  </div>

                  <div className="relative">
                    <FaEnvelope className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                    <input
                      type="email"
                      name="email"
                      placeholder="Email"
                      value={formData.email}
                      onChange={handleChange}
                      className="w-full p-3 border rounded-lg pl-10 focus:outline-none focus:ring-2 focus:ring-purple-500"
                      autoComplete="email"
                    />
                    {errors.email && (
                      <p className="text-red-500 text-xs mt-1">{errors.email}</p>
                    )}
                  </div>

                  <div className="relative">
                    <FaPhone className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                    <input
                      type="tel"
                      name="phone_number"
                      placeholder="Phone Number"
                      value={formData.phone_number}
                      onChange={handleChange}
                      className="w-full p-3 border rounded-lg pl-10 focus:outline-none focus:ring-2 focus:ring-purple-500"
                      autoComplete="tel"
                    />
                    {errors.phone_number && (
                      <p className="text-red-500 text-xs mt-1">{errors.phone_number}</p>
                    )}
                  </div>

                  <div className="relative">
                    <FaMapMarkerAlt className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                    <input
                      type="text"
                      name="address"
                      placeholder="Address"
                      value={formData.address}
                      onChange={handleChange}
                      className="w-full p-3 border rounded-lg pl-10 focus:outline-none focus:ring-2 focus:ring-purple-500"
                    />
                    {errors.address && (
                      <p className="text-red-500 text-xs mt-1">{errors.address}</p>
                    )}
                  </div>

                  <div className="relative">
                    <FaMapMarkerAlt className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                    <input
                      type="text"
                      name="city"
                      placeholder="City"
                      value={formData.city}
                      onChange={handleChange}
                      className="w-full p-3 border rounded-lg pl-10 focus:outline-none focus:ring-2 focus:ring-purple-500"
                    />
                    {errors.city && (
                      <p className="text-red-500 text-xs mt-1">{errors.city}</p>
                    )}
                  </div>

                  <div>
                    <select
                      name="gender"
                      value={formData.gender}
                      onChange={handleChange}
                      className="w-full p-3 border rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500"
                    >
                      <option value="">Select Gender</option>
                      <option value="Male">Male</option>
                      <option value="Female">Female</option>
                      <option value="Other">Other</option>
                      <option value="Prefer not to say">Prefer not to say</option>
                    </select>
                    {errors.gender && (
                      <p className="text-red-500 text-xs mt-1">{errors.gender}</p>
                    )}
                  </div>

                  <div>
                    <select
                      name="preferred_clothing_size"
                      value={formData.preferred_clothing_size}
                      onChange={handleChange}
                      className="w-full p-3 border rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500"
                    >
                      <option value="">Select Preferred Clothing Size</option>
                      <option value="XS">XS</option>
                      <option value="S">S</option>
                      <option value="M">M</option>
                      <option value="L">L</option>
                      <option value="XL">XL</option>
                      <option value="XXL">XXL</option>
                    </select>
                    {errors.preferred_clothing_size && (
                      <p className="text-red-500 text-xs mt-1">{errors.preferred_clothing_size}</p>
                    )}
                  </div>

                  <div className="space-y-1">
                    <label className="block text-sm font-medium text-gray-700 ml-1">Profile Image</label>
                    <div className="relative">
                      <input
                        type="file"
                        name="profile_image"
                        accept="image/*"
                        onChange={handleChange}
                        className="w-full p-2.5 border rounded-lg file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-purple-50 file:text-purple-700 hover:file:bg-purple-100 transition"
                      />
                    </div>
                  </div>

                  <div className="relative">
                    <FaLock className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                    <input
                      type="password"
                      name="password"
                      placeholder="Password (min. 8 characters)"
                      value={formData.password}
                      onChange={handleChange}
                      className="w-full p-3 border rounded-lg pl-10 focus:outline-none focus:ring-2 focus:ring-purple-500"
                      autoComplete="new-password"
                    />
                    {errors.password && (
                      <p className="text-red-500 text-xs mt-1">
                        {errors.password}
                      </p>
                    )}
                  </div>

                  <div className="relative">
                    <FaLock className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                    <input
                      type="password"
                      name="confirmPassword"
                      placeholder="Confirm Password"
                      value={formData.confirmPassword}
                      onChange={handleChange}
                      className="w-full p-3 border rounded-lg pl-10 focus:outline-none focus:ring-2 focus:ring-purple-500"
                      autoComplete="new-password"
                    />
                    {errors.confirmPassword && (
                      <p className="text-red-500 text-xs mt-1">
                        {errors.confirmPassword}
                      </p>
                    )}
                  </div>

                  <button
                    type="submit"
                    disabled={isLoading}
                    className="w-full bg-purple-600 text-white p-3 rounded-lg font-semibold hover:bg-purple-700 transition disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    {isLoading ? "Registering..." : "Register"}
                  </button>
                </form>

                <p className="text-sm text-center text-gray-600 mt-4">
                  Already have an account?{" "}
                  <span
                    onClick={() => navigate("/login")}
                    className="text-purple-600 font-semibold cursor-pointer hover:underline"
                  >
                    Login here
                  </span>
                </p>
              </>
            ) : (
              <>
                <h2 className="text-2xl font-bold mb-4 text-center">
                  Verify Your Email
                </h2>
                <p className="text-sm text-gray-600 text-center mb-6">
                  Enter the 6-digit code sent to{" "}
                  <span className="font-semibold">{formData.email}</span>
                </p>

                {serverError && (
                  <p className="text-red-500 text-center mb-4 bg-red-50 p-3 rounded-lg">{serverError}</p>
                )}

                <form onSubmit={handleOtpSubmit} className="space-y-4">
                  <div className="relative">
                    <input
                      type="text"
                      name="otp"
                      placeholder="Enter 6-digit OTP"
                      value={otp}
                      onChange={(e) => setOtp(e.target.value.replace(/\D/g, "").slice(0, 6))}
                      className="w-full p-3 border rounded-lg text-center text-2xl tracking-widest focus:outline-none focus:ring-2 focus:ring-purple-500"
                      maxLength={6}
                    />
                  </div>

                  <button
                    type="submit"
                    disabled={isLoading}
                    className="w-full bg-purple-600 text-white p-3 rounded-lg font-semibold hover:bg-purple-700 transition disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    {isLoading ? "Verifying..." : "Verify OTP"}
                  </button>
                </form>

                <div className="text-center mt-4">
                  <p className="text-sm text-gray-600">
                    Didn't receive the code?{" "}
                    <button
                      onClick={handleResendOtp}
                      disabled={isLoading}
                      className="text-purple-600 font-semibold hover:underline disabled:opacity-50"
                    >
                      Resend OTP
                    </button>
                  </p>
                </div>

                <button
                  onClick={() => setStep(1)}
                  className="w-full mt-4 text-gray-600 text-sm hover:underline"
                >
                  ΓåÉ Back to Registration
                </button>
              </>
            )}
          </div>
        </div>
      </div>
      <Footer />
    </>
  );
};

export default UserRegister;

